    def _has_test_pass_evidence(self, board: dict | None = None) -> bool:
        bb = board if isinstance(board, dict) else self._ensure_blackboard()
        logs = bb.get("execution_logs", []) if isinstance(bb.get("execution_logs"), list) else []
        feedback = bb.get("review_feedback", []) if isinstance(bb.get("review_feedback"), list) else []
        positive = ("test passed", "tests passed", "测试通过", "运行正常",
                     "all tests pass", "ok", "passed", "test succeeded")
        negative = ("failed", "error", "failure", "测试失败")
        combined = list(logs[-6:]) + list(feedback[-4:])
        for entry in reversed(combined[-8:]):
            txt = str((entry or {}).get("content", "") or "").lower() if isinstance(entry, dict) else str(entry or "").lower()
            if not txt:
                continue
            if any(neg in txt for neg in negative):
                continue
            if any(pos in txt for pos in positive):
                return True
        return False

    def _update_project_todo_status(self, board: dict | None = None):
        bb = board if isinstance(board, dict) else self._ensure_blackboard()
        todos = bb.get("project_todos", [])
        if not todos:
            return
        code_count = len(bb.get("code_artifacts", {}) or {})
        research_count = len(bb.get("research_notes", []) or [])
        exec_count = len(bb.get("execution_logs", []) or [])
        feedback_pass = self._manager_feedback_passed_from_blackboard(bb)

        for todo in todos:
            if todo.get("status") == "completed":
                continue
            cat = todo.get("category", "")
            if cat == "plan_step" and todo.get("status") == "in_progress" and not todo.get("activated_at"):
                step_idx = int(todo.get("plan_step_index", 0) or 0)
                prior_done_ts = [
                    float(t.get("completed_at", 0.0) or 0.0)
                    for t in todos
                    if t.get("category") == "plan_step"
                    and int(t.get("plan_step_index", 0) or 0) < step_idx
                    and t.get("completed_at")
                ]
                todo["activated_at"] = (
                    max(prior_done_ts)
                    if prior_done_ts
                    else (float(todo.get("created_at", 0.0) or 0.0) or float(now_ts()))
                )
            if cat == "setup" and (research_count > 0 or code_count > 0):
                todo.update(
                    status="completed",
                    completed_at=float(now_ts()),
                    evidence=self._ui_text("evidence_structure_analyzed"),
                )
            elif cat == "implement" and code_count > 0 and (exec_count > 0 or feedback_pass):
                todo.update(
                    status="completed",
                    completed_at=float(now_ts()),
                    completed_by="developer",
                    evidence=trim(
                        f"{self._ui_text('evidence_files_produced', count=code_count)} + observable execution evidence",
                        200,
                    ),
                )
            elif cat == "compile_test" and self._has_compile_pass_evidence(bb):
                todo.update(
                    status="completed",
                    completed_at=float(now_ts()),
                    evidence=self._ui_text("evidence_compile_passed"),
                )
            elif cat == "min_test" and self._has_test_pass_evidence(bb):
                todo.update(
                    status="completed",
                    completed_at=float(now_ts()),
                    evidence=self._ui_text("evidence_test_passed"),
                )
            elif cat == "review" and feedback_pass:
                todo.update(
                    status="completed",
                    completed_at=float(now_ts()),
                    evidence=self._ui_text("evidence_review_passed"),
                )
            elif cat == "plan_step":
                # Plan steps are never auto-completed here; only _advance_plan_step
                # may close them. Activation of the next eligible step is deferred
                # to _normalize_plan_step_progress (called below) so this path uses
                # the exact same invariant as advance/restore.
                pass

        if not any(t.get("status") == "in_progress" for t in todos):
            for t in todos:
                if t.get("status") == "pending":
                    t["status"] = "in_progress"
                    if not t.get("activated_at"):
                        t["activated_at"] = float(now_ts())
                    break

        bb["project_todos"] = todos
        # Canonical plan-step invariant: single lowest-index active step + derived
        # cursor. Shared with advance/restore so all paths agree on "current step".
        self._normalize_plan_step_progress(bb)
        todos = bb.get("project_todos", todos)
        self.blackboard = bb

    # --- Step advancement inference ------------------------------------------
    # Decide whether manager/developer text is valid evidence that the current
    # plan step has already finished, rather than a forward-looking dispatch.
    def _instruction_implies_step_advance(self, instruction: str, reason: str = "") -> bool:
        """Detect if manager instruction semantically implies current plan step is done."""
        bb = self._ensure_blackboard()
        plan_steps = [t for t in bb.get("project_todos", []) if t.get("category") == "plan_step"]
        if not plan_steps:
            return False
        # Must have an in_progress step to advance
        current = None
        for t in plan_steps:
            if t.get("status") == "in_progress":
                current = t
                break
        if not current:
            return False
        text = (str(instruction or "") + " " + str(reason or "")).lower()
        # Completion evidence must be backward-looking: the text must state that
        # the current step already passed or finished.
        step_done_patterns = (
            "审查通过", "通过审查", "已通过", "已完成", "完成了",
            "step completed", "step done", "step passed",
            "阶段完成", "阶段通过", "phase complete",
            "步骤 1.1 已完成", "步骤 1.2 已完成", "步骤 1.3 已完成",
            "步骤 1.4 已完成", "步骤 1.5 已完成",
        )
        # Forward-looking dispatch phrases are intentionally excluded here.
        # "start/proceed to step ..." only routes work; it does not prove that
        # the current step completed successfully.
        import re
        current_idx = int(current.get("plan_step_index", 0) or 0)
        # Only treat "move to step N" as advancement evidence when it skips
        # beyond the immediate next step; otherwise it is likely normal routing.
        next_step_pattern = re.search(
            r'(?:进入|enter|move\s+to|start|proceed\s+to)\s*(?:step\s*)?(\d+)',
            text, re.IGNORECASE
        )
        if next_step_pattern:
            mentioned_step = int(next_step_pattern.group(1))
            if mentioned_step > current_idx + 2:  # must skip at least 2 ahead to be meaningful
                return True
        # Mixed phrases such as "finished current step, start next step" only
        # count when the completed step index matches the active step exactly.
        step_ref = re.search(r'(?:完成|finished|done)\s*步骤\s*1\.(\d+)', text)
        if step_ref:
            ref_sub = int(step_ref.group(1))
            if ref_sub == current_idx + 1:  # explicitly says current step (1-based) is done
                return True
        return any(pat in text for pat in step_done_patterns)

    def _normalize_plan_step_progress(self, bb: dict | None = None) -> dict:
        """Single authority for the plan-step progress invariant.

        Enforces, over all `plan_step` todos:
          - ordered by plan_step_index;
          - AT MOST one in_progress (if several, keep the lowest index, demote
            the rest to pending);
          - if NONE is in_progress, activate the lowest-index non-completed step;
          - plan_step_cursor is DERIVED from the active step's index (never an
            independent +1), and plan_step_total reflects the row count.

        This is the canonical rule shared by advance / reconcile / restore so the
        three paths can never disagree on "which step is current" (the cause of
        same-tick contradictory switch notices and step-skips). It NEVER marks a
        step completed — only advance does that. Returns the active step dict (or
        {} when all steps are done).
        """
        bb = bb if isinstance(bb, dict) else self._ensure_blackboard()
        todos = bb.get("project_todos", []) if isinstance(bb.get("project_todos"), list) else []
        plan_rows = [
            t for t in todos
            if isinstance(t, dict) and str(t.get("category", "") or "") == "plan_step"
        ]
        if not plan_rows:
            return {}
        plan_rows.sort(key=lambda r: int(r.get("plan_step_index", 0) or 0))

        # Collapse multiple in_progress down to the lowest-index one.
        active_rows = [r for r in plan_rows if str(r.get("status", "") or "") == "in_progress"]
        if len(active_rows) > 1:
            keep = min(active_rows, key=lambda r: int(r.get("plan_step_index", 0) or 0))
            keep_id = id(keep)
            for row in active_rows:
                if id(row) != keep_id:
                    row["status"] = "pending"
                    row["activated_at"] = None

        # If nothing is active, activate the lowest-index non-completed step.
        if not any(str(r.get("status", "") or "") == "in_progress" for r in plan_rows):
            nxt = next((r for r in plan_rows if str(r.get("status", "") or "") != "completed"), None)
            if nxt is not None:
                nxt["status"] = "in_progress"
                if not nxt.get("activated_at"):
                    nxt["activated_at"] = float(now_ts())

        active_step = next((r for r in plan_rows if str(r.get("status", "") or "") == "in_progress"), None)
        if active_step is not None:
            bb["plan_step_cursor"] = int(active_step.get("plan_step_index", 0) or 0)
        else:
            bb["plan_step_cursor"] = len(plan_rows)
        bb["plan_step_total"] = len(plan_rows)
        # Only adopt as the live blackboard when operating on it directly; callers
        # building a fresh board (e.g. _normalize_blackboard) manage assignment.
        if bb is getattr(self, "blackboard", None):
            self.blackboard = bb
        return active_step if isinstance(active_step, dict) else {}

    def _retire_plan_step_worker_todos(
        self,
        plan_step: dict | None,
        *,
        evidence: str = "",
        actor: str = "developer",
        board: dict | None = None,
    ) -> bool:
        """Archive one completed step's subtasks and remove them from the live view."""
        if not isinstance(plan_step, dict):
            return False
        step_id = trim(str(plan_step.get("id", "") or ""), 40)
        if not step_id:
            return False
        bb = board if isinstance(board, dict) else self._ensure_blackboard()
        snapshot = self.todo.snapshot()
        closed_rows: list[dict] = []
        live_rows: list[dict] = []
        closed_at = float(now_ts())
        for raw in snapshot:
            if not isinstance(raw, dict):
                continue
            row = dict(raw)
            if (
                self._todo_row_kind(row) == "plan_worker"
                and trim(str(row.get("parent_step_id", "") or ""), 40) == step_id
            ):
                if str(row.get("status", "pending") or "pending").strip().lower() != "completed":
                    return False
                row["updated_at"] = closed_at
                closed_rows.append(row)
                continue
            live_rows.append(row)
        if closed_rows:
            try:
                self._sync_plan_worker_todos_to_blackboard(
                    step_id,
                    rows=closed_rows,
                    board=bb,
                )
            except Exception:
                pass
        if len(live_rows) == len(snapshot):
            return False
        with self.todo.lock:
            self.todo.items = live_rows
        return True

    def _reset_plan_step_execution_boundary(self, board: dict | None = None) -> None:
        """Reset transient execution state while preserving durable task evidence."""
        bb = board if isinstance(board, dict) else self._ensure_blackboard()
        transient_prefixes = RETRY_RUNTIME_HINT_PREFIXES + (
            "<read-context-strategy>",
            "<tool-memory-strategy>",
            "<web-search-strategy>",
            "<read-loop-intervention>",
            "<todo-focus>",
            "<verification-required>",
            "<acceptance-repair>",
            "<plan-state-repair-required>",
            "<action-required>",
        )

        def _keep_message(row: object) -> bool:
            if not isinstance(row, dict):
                return True
            if str(row.get("role", "") or "").strip() not in {"user", "system"}:
                return True
            content = str(row.get("content", "") or "").strip().lower()
            return not any(content.startswith(prefix) for prefix in transient_prefixes)

        self.messages = [row for row in self.messages if _keep_message(row)][-400:]
        self.agent_messages = [row for row in self.agent_messages if _keep_message(row)][-800:]
        self.manager_context = [row for row in self.manager_context if _keep_message(row)][-400:]
        self.contexts = {role: [] for role in AGENT_ROLES}
        self.tool_retry_counts = {}
        self.bash_read_loop_fp = ""
        self.bash_read_loop_count = 0
        self.read_file_loop_recent = []
        self.read_file_loop_state = {}
        self.read_file_loop_count = 0
        self.read_file_loop_last_intervention_ts = 0.0
        self.tool_memory_loop_state = {}
        self.agent_loop_progress_state = {}
        self.rounds_without_todo = 0
        self.last_todo_reminder_ts = 0.0
        self.todo_reminder_count = 0
        self.todo_write_issue_count = 0
        self.todo_last_issue = ""
        self.stall_severity_score = 0
        self.stall_severity_sources = []
        self.stall_escalation_triggered = False
        self.stall_escalation_round = 0
        self.developer_edit_fail_streaks = {}
        self.developer_edit_last_diag = {}
        self.reviewer_debug_mode = False
        self.reviewer_debug_rounds = 0
        self.reviewer_debug_context = ""
        self.active_agent_role = ""
        # AgentBus envelopes are executable only inside the step/subtask that
        # created them. Keep the public message history for audit/UI, but do not
        # carry old handoffs into the next step's dispatcher.
        self.agent_bus_messages = []
        self.manager_routes = []
        bb.pop("failure_recovery", None)
        bb["watchdog"] = self._new_watchdog_state()
        bb["decomposition_queue"] = self._new_decomposition_queue_state()
        bb["persisted_manager_routes"] = []
        bb["active_agent"] = ""
        bb["last_delegate"] = {
            "target": "",
            "instruction": "",
            "reason": "",
            "source": "",
            "progress_fp": "",
            "is_mandatory": False,
            "ts": 0.0,
        }
        bb["last_worker_reply"] = {"role": "", "text": "", "ts": 0.0}
        self.blackboard = bb

    def _activate_plan_step_execution(
        self,
        plan_step: dict | None = None,
        *,
        board: dict | None = None,
        owner: str = "",
        reason: str = "",
        sync_todos: bool = True,
    ) -> dict:
        """Compile any active plan step into the same executable subplan lifecycle."""
        bb = board if isinstance(board, dict) else self._ensure_blackboard()
        active_step = self._normalize_plan_step_progress(bb)
        if isinstance(plan_step, dict):
            requested_id = trim(str(plan_step.get("id", "") or ""), 40)
            active_id = trim(str((active_step or {}).get("id", "") or ""), 40)
            if requested_id and requested_id != active_id:
                return {
                    "ok": False,
                    "available": False,
                    "changed": False,
                    "reason": "requested-step-is-not-active",
                    "active_step_id": active_id,
                }
        if not isinstance(active_step, dict) or not active_step:
            bb["focus"] = self._blackboard_focus_identity(bb)
            self.blackboard = bb
            if sync_todos:
                self._sync_todos_from_blackboard(reason=reason or "plan-complete", board=bb)
            return {
                "ok": True,
                "available": False,
                "changed": False,
                "reason": "plan-complete",
                "active_step_id": "",
            }
        step_id = trim(str(active_step.get("id", "") or ""), 40)
        bb["focus"] = self._blackboard_focus_identity(bb)
        self.blackboard = bb
        worker = self._ensure_worker_todos_available_for_plan_step(
            active_step,
            owner=owner or self._current_plan_worker_owner(bb),
            force_refresh=False,
        )
        if bool(worker.get("available", False)):
            rows = self._active_plan_worker_todo_rows(step_id, role="")
            open_rows = [
                row for row in rows
                if str(row.get("status", "pending") or "pending").strip().lower() != "completed"
            ]
            active_rows = [
                row for row in open_rows
                if str(row.get("status", "") or "").strip().lower() == "in_progress"
            ]
            if open_rows and len(active_rows) != 1:
                worker = self._ensure_worker_todos_available_for_plan_step(
                    active_step,
                    owner=owner or self._current_plan_worker_owner(bb),
                    force_refresh=True,
                )
        self.runtime_plan_approved = True
        self.runtime_plan_mode_needed = False
        if sync_todos:
            self._sync_todos_from_blackboard(
                reason=reason or f"plan-step-active:{int(active_step.get('plan_step_index', 0) or 0) + 1}",
                board=self._ensure_blackboard(),
            )
        return {
            **dict(worker),
            "active_step_id": step_id,
            "active_step_index": int(active_step.get("plan_step_index", 0) or 0),
        }

    def _advance_plan_step(self, evidence: str = "", actor: str = "developer"):
        bb = self._ensure_blackboard()
        todos = bb.get("project_todos", [])
        if not todos:
            return False
        # Defensive: if plan-step state was corrupted (e.g. several in_progress at
        # once), normalize to the single lowest-index active step BEFORE deciding
        # what to complete, so we never advance off a dirty state.
        self._normalize_plan_step_progress(bb)
        todos = bb.get("project_todos", todos)
        current = None
        for t in todos:
            if t.get("category") == "plan_step" and t.get("status") == "in_progress":
                current = t
                break
        if not current:
            return False
        if not self._step_subtasks_all_completed(current):
            self._emit(
                "status",
                {
                    "summary": (
                        "plan step advancement blocked: current-step subtasks are not all completed; "
                        "the roadmap and subtask states were preserved"
                    )
                },
            )
            return False
        previous_focus = self._blackboard_focus_identity(bb)
        # Fix 5c: Reset TodoWrite loop counter on step advancement
        try:
            self._todowrite_step_counter.clear()
        except Exception:
            pass
        current["status"] = "completed"
        current["completed_at"] = float(now_ts())
        current["completed_by"] = actor
        current["evidence"] = trim(str(evidence or "").strip(), 200) or self._ui_text("step_completed_evidence")
        try:
            self._record_plan_step_result(current, evidence=evidence, actor=actor, board=bb)
            bb = self._ensure_blackboard()
            todos = bb.get("project_todos", todos)
        except Exception:
            pass
        # Clear single-mode validation gate flags for the completed step
        try:
            _completed_id = str(current.get("id", "") or "")
            for _attr_name in (f"_smvg_{_completed_id}", f"_smvg_ts_{_completed_id}", f"_smvg_n_{_completed_id}", f"_sync_exec_gate_n_{_completed_id}", f"_sync_sv_ts_{_completed_id}"):
                try:
                    delattr(self, _attr_name)
                except AttributeError:
                    pass
        except Exception:
            pass
        # Finish and archive the old subplan before the next step is activated.
        # This keeps the live Todo view step-local and prevents stale rows from
        # consuming capacity or being reconciled into the next step's graph.
        self._retire_plan_step_worker_todos(
            current,
            evidence=evidence,
            actor=actor,
            board=bb,
        )
        self._reset_plan_step_execution_boundary(bb)
        # Activate the next step via the canonical invariant: lowest-index
        # non-completed step becomes in_progress, cursor derived from its index.
        # (Never "first pending in list order" + independent cursor+1, which could
        # skip a step left in a non-pending state by a prior reconcile/rescue.)
        next_step = self._normalize_plan_step_progress(bb)
        next_step = next_step if isinstance(next_step, dict) and next_step else None
        if next_step:
            try:
                activation = self._activate_plan_step_execution(
                    next_step,
                    board=bb,
                    owner=self._current_plan_worker_owner(bb),
                    reason="plan-step-transition",
                    sync_todos=False,
                )
                if not bool(activation.get("available", False)):
                    self._emit(
                        "status",
                        {"summary": f"next plan subplan unavailable: {trim(str(activation.get('reason', 'unknown')), 120)}"},
                    )
            except Exception as exc:
                self._emit("status", {"summary": f"next plan subplan bootstrap failed: {trim(str(exc), 120)}"})
            step_idx = int(next_step.get("plan_step_index", 0) or 0) + 1
            total = int(bb.get("plan_step_total", len(todos)) or len(todos))
            self._emit("status", {
                "summary": self._ui_text(
                    "plan_step_summary",
                    step=step_idx,
                    total=total,
                    content=trim(str(next_step.get("content", "") or ""), 120),
                )
            })
        new_focus = self._blackboard_focus_identity(bb)
        bb["focus"] = new_focus
        dq = self._normalize_decomposition_queue_state(bb.get("decomposition_queue", {}))
        if bool(dq.get("active", False)):
            dq_focus = str(dq.get("focus_id", "") or "")
            prev_id = str(previous_focus.get("id", "") or "")
            if (not dq_focus) or dq_focus == prev_id:
                dq["active"] = False
                dq["last_error"] = "deactivated because active plan step advanced"
                bb["decomposition_queue"] = dq
        bb["last_step_transition"] = {
            "from_focus_id": str(previous_focus.get("id", "") or ""),
            "to_focus_id": str(new_focus.get("id", "") or ""),
            "from_title": trim(str(previous_focus.get("title", "") or ""), 240),
            "to_title": trim(str(new_focus.get("title", "") or ""), 240),
            "actor": trim(str(actor or "").strip(), 40),
            "evidence": trim(str(evidence or "").strip(), 300),
            "ts": float(now_ts()),
        }
        self.blackboard = bb
        self._blackboard_touch()
        self._blackboard_append_memory(
            "step_transition",
            (
                f"plan step advanced from {trim(str(previous_focus.get('title', '') or ''), 160)} "
                f"to {trim(str(new_focus.get('title', '') or 'complete'), 160)}; "
                f"evidence={trim(str(evidence or ''), 180)}"
            ),
            actor=actor,
            tier="long",
        )
        # Persist step status change to plan.md
        try:
            self._update_plan_file_step_status()
        except Exception:
            pass  # Plan file update is best-effort
        # Immediately sync todos so UI reflects plan step advancement
        _next_idx = int(next_step.get("plan_step_index", 0) or 0) + 1 if isinstance(next_step, dict) and next_step else int(bb.get("plan_step_cursor", 0) or 0)
        self._sync_todos_from_blackboard(reason=f"plan-step-advanced:{_next_idx}", board=bb)
        # Inject hint for the next step (works in both single and multi-agent mode).
        # Dedup against the last-hinted step id so one transition emits one notice.
        if next_step and str(getattr(self, "_last_step_hint_id", "") or "") != str(next_step.get("id", "") or ""):
            try:
                _ns_idx = int(next_step.get("plan_step_index", 0) or 0) + 1
                _ns_total = int(bb.get("plan_step_total", 0) or 0)
                _ns_text = trim(str(next_step.get("content", "") or ""), 200)
                _ns_id = str(next_step.get("id", "") or "")
                _ns_label = self._ui_text("plan_step_label", step=_ns_idx, total=_ns_total)
                _hint = self._ui_text(
                    "plan_step_hint",
                    step_label=_ns_label,
                    step_text=_ns_text,
                    plan_path=PLAN_FILE_RELATIVE_PATH,
                    parent_step_id=_ns_id,
                )
                target_roles: tuple[str, ...] = ()
                if self._is_multi_agent_mode():
                    active_role = self._current_plan_worker_owner(bb)
                    if active_role:
                        target_roles = (active_role,)
                if self._append_plan_guidance_bubble(
                    _hint,
                    target_roles=target_roles,
                    summary=f"plan step bubble injected ({_ns_idx}/{_ns_total})",
                ):
                    if _ns_id:
                        self._last_step_hint_id = _ns_id
            except Exception:
                pass
        return True

    def _post_execution_plan_step_check(self, route: dict, worker_step: dict) -> bool:
        """After worker execution, check if current plan step should advance based on evidence."""
        bb = self._ensure_blackboard()
        current = next(
            (t for t in bb.get("project_todos", [])
             if t.get("category") == "plan_step" and t.get("status") == "in_progress"),
            None,
        )
        if not current:
            # No plan steps — detect finish_current_task for pure-sync mode coordination.
            # Sets sync_worker_round_done flag so the sync loop can signal the manager.
            # Only reachable in pure sync mode (no plan steps); plan+sync always has `current`
            # set, so this branch never executes for plan modes.
            results = worker_step.get("tool_results", []) or []
            called_finish = any(
                isinstance(r, dict) and r.get("ok")
                and str(r.get("name", "")) in ("finish_current_task", "finish_task")
                for r in results
            )
            if called_finish:
                bb["sync_worker_round_done"] = True
                self._save_blackboard(bb)
            return False
        if isinstance(route, dict) and route.get("focus_id") and not self._route_matches_active_focus(route, bb):
            self._blackboard_append_memory(
                "decision",
                "ignored post-execution plan advancement from a stale delegate focus",
                actor="manager",
                tier="long",
            )
            return False
        # Parity with single-agent (Fix 1): bootstrap step-local subtasks when the
        # active step has none. Single-agent does this in _single_agent_plan_step_check
        # (:42564); multi-agent never did, so the acceptance gate's
        # "missing-step-local-subtasks" reason could never resolve and the run stalled
        # at step end. Auto-create the subtask chain so the gate has something to pass.
        _cur_step_id = str(current.get("id", "") or "")
        if _cur_step_id and not self._active_plan_worker_todo_rows(_cur_step_id, role=""):
            try:
                activation = self._activate_plan_step_execution(
                    current,
                    board=bb,
                    owner=self._current_plan_worker_owner(bb),
                    reason="multi-agent-runtime-bootstrap",
                    sync_todos=False,
                )
                if bool(activation.get("available", False)):
                    self._emit(
                        "status",
                        {"summary": "plan subtasks auto-created by runtime bootstrap (multi-agent)"},
                    )
            except Exception as exc:
                self._emit("status", {"summary": f"plan subtask bootstrap failed: {trim(str(exc), 120)}"})
        # Active pass: reconcile observable events before asking the manager or
        # reviewer to reason again. Exact aggregate evidence atomically closes
        # the acceptance row; only genuinely ambiguous evidence reaches the LLM.
        try:
            self._reconcile_plan_worker_progress_from_evidence(
                actor=str(route.get("target", "developer") or "developer")
            )
            bb = self._ensure_blackboard()
            current = self._get_active_plan_step(bb) or current
        except Exception:
            pass
        # 1. Manager explicitly requested advancement
        manager_requested = bool(route.get("advance_plan_step_requested", False))
        # 2. Worker produced concrete tool outputs
        worker_produced_output = self._worker_step_has_evidence(worker_step)
        # 3. All subtasks for this step are completed
        subtasks_all_done = self._step_subtasks_all_completed(current)
        # 4. Phase-based file+bash evidence (implement requires BOTH write + bash)
        step_content = str(current.get("full_content", "") or current.get("content", "") or "").lower()
        phase = self._plan_step_phase_hint(step_content)
        results = worker_step.get("tool_results", []) or []
        wrote_files = any(
            isinstance(r, dict) and r.get("ok", False)
            and str(r.get("name", "")) in ("write_file", "edit_file")
            for r in results
        )
        ran_bash_ok = any(
            isinstance(r, dict) and self._tool_result_is_passing_execution(r)
            for r in results
        )
        validation_ok_current = self._tool_results_have_validation_evidence(current, results)
        validation_ok_blackboard = self._plan_step_has_blackboard_evidence(current, bb)
        validation_ok = validation_ok_current or validation_ok_blackboard
        bb_sig = self._plan_step_blackboard_signals(current, bb)
        phase_evidence = False
        if phase in ("research", "design") and validation_ok:
            phase_evidence = True
        elif phase == "implement" and (
            (wrote_files and validation_ok_current)
            or (bb_sig["has_write"] and validation_ok_blackboard)
        ):
            phase_evidence = True
        elif phase in ("test", "review") and (
            (ran_bash_ok and validation_ok_current)
            or ((bb_sig["has_exec"] or bb_sig["has_review"]) and validation_ok_blackboard)
        ):
            phase_evidence = True
        # Advance when the step-local subtask chain is complete and concrete
        # evidence exists. The final acceptance subtask is the validation gate;
        # manager requests or phase heuristics cannot bypass incomplete subtasks.
        _has_subtasks = bool(self._active_plan_worker_todo_rows(
            str(current.get("id", "") or ""), role=""
        ))
        acceptance_gate = self._plan_step_acceptance_gate_status(current, worker_step, bb)
        acceptance_gate_ok = bool(acceptance_gate.get("ok", False))
        has_strong_evidence = self._plan_step_acceptance_ready_for_advance(
            current,
            acceptance_gate,
            bb,
        )
        # Parity with single-agent (Fix 1): phase-heuristic escape when the step
        # genuinely has NO step-local subtasks (bootstrap above couldn't decompose
        # it — e.g. an atomic step). Single-agent allows this via
        # `_can_use_phase_heuristic = subtasks_done or not _has_subtasks_s` (:42629).
        # Without it, a subtask-less step can never satisfy `subtasks_all_done` and
        # the multi-agent run stalls. Requires real phase evidence; never advances
        # on a bare claim.
        if not has_strong_evidence and not _has_subtasks and worker_produced_output:
            if phase_evidence or validation_ok:
                has_strong_evidence = True
        if manager_requested and worker_produced_output and not subtasks_all_done and _has_subtasks:
            self._blackboard_append_memory(
                "decision",
                "ignored plan advancement request because step-local subtasks are incomplete",
                actor="manager",
                tier="long",
            )
        if manager_requested and subtasks_all_done and not acceptance_gate_ok:
            self._blackboard_append_memory(
                "decision",
                (
                    "ignored plan advancement request because final acceptance subtask gate failed: "
                    f"{trim(str(acceptance_gate.get('reason', '') or ''), 160)}"
                ),
                actor="manager",
                tier="long",
            )
        if has_strong_evidence:
            evidence = self._collect_step_evidence(current, worker_step)
            # Clear sync exec gate counter on successful advance
            try:
                _sync_clear = f"_sync_exec_gate_n_{str(current.get('id', '') or '')}"
                if hasattr(self, _sync_clear):
                    delattr(self, _sync_clear)
            except Exception:
                pass
            return bool(self._advance_plan_step(
                evidence=evidence,
                actor=str(route.get("target", "developer") or "developer"),
            ))
        else:
            if (subtasks_all_done or self._step_work_subtasks_completed(current)) and not acceptance_gate_ok:
                target_role = self._sanitize_agent_role(str(route.get("target", "") or ""))
                # Drive diagnose→repair→re-verify; returns True only on a genuine
                # (semantic-verified) pass. Never force-advances.
                if self._acceptance_gate_handle_failure(
                    current,
                    acceptance_gate,
                    bb,
                    actor=str(route.get("target", "developer") or "developer"),
                    target_roles=((target_role,) if target_role else ()),
                ):
                    return True
            self._inject_rework_if_needed(current, worker_step)
        return False

    def _worker_step_has_evidence(self, step: dict) -> bool:
        """Check if worker step produced concrete tool outputs."""
        results = step.get("tool_results", []) or []
        return any(
            r.get("ok", False)
            and (
                str(r.get("name", "")) in (
                    "write_file", "edit_file", "bash",
                    "write_to_blackboard", "read_from_blackboard", "agent_web_search",
                    "query_code_library", "query_knowledge_library",
                )
                or (
                    str(r.get("name", "")) == "read_file"
                    and not self._is_plan_infrastructure_read_result(r)
                )
                or self._is_browser_runtime_tool_name(r.get("name", ""))
            )
            for r in results
            if isinstance(r, dict)
        )

    def _is_plan_infrastructure_read_result(self, result: dict) -> bool:
        if not isinstance(result, dict):
            return False
        if str(result.get("name", "") or "") != "read_file":
            return False
        args = result.get("args", {}) if isinstance(result.get("args"), dict) else {}
        path = str(args.get("path", "") or args.get("file_path", "") or "").replace("\\", "/")
        if not path:
            return False
        return (
            (path.endswith("plan.md") and ".clouds_coder/" in path)
            or ".clouds_coder/skills_cache/" in path
            or path.endswith("/.clouds_coder/skills_cache")
        )

    def _step_subtasks_all_completed(self, plan_step: dict) -> bool:
        """Check if all worker subtasks linked to this plan step are completed.
        Filters out cross-step subtasks (e.g., 2.1 under step 1) to prevent blocking.
        Fix 6: Also excludes 'next-step intent' items that were added alongside completed items."""
        step_id = str(plan_step.get("id", "") or "")
        if not step_id:
            return False
        worker_items = self._active_plan_worker_todo_rows(step_id, role="")
        if not worker_items:
            expected = self._extract_plan_step_subtasks(plan_step, limit=6)
            if expected:
                return False
            # Approved plan steps are executed through step-local worker
            # subtasks. If none exist yet, the bootstrap/LLM decomposition path
            # must run before this step can be considered complete.
            return False
        # Extract major step number from plan step content (e.g., "1. Project init" → "1")
        import re
        step_content = str(plan_step.get("full_content", "") or plan_step.get("content", "") or "")
        _m = re.match(r"^(\d+)\.", step_content.strip())
        active_major = _m.group(1) if _m else ""
        # Filter out cross-step subtasks (N.M where N != active major)
        if active_major:
            _cross_re = re.compile(r"^(\d+)\.\d+\s")
            relevant = []
            for r in worker_items:
                rc = str(r.get("content", "") or "").strip()
                cm = _cross_re.match(rc)
                if cm and cm.group(1) != active_major:
                    continue  # Skip cross-step items — don't let them block advancement
                relevant.append(r)
            if relevant:
                worker_items = relevant
        acceptance_items = [
            row for row in worker_items
            if self._is_plan_step_acceptance_subtask(row.get("content", ""))
        ]
        if not acceptance_items or any(
            str(row.get("status", "") or "").lower() != "completed"
            for row in acceptance_items
        ):
            return False
        # Fix 6: Exclude "next-step intent" pending items when all other items are completed.
        # When the worker completes step N and creates step N+1 subtasks in the same TodoWrite call,
        # the new pending items get parent_step_id of step N, blocking its advancement.
        completed_items = [r for r in worker_items if str(r.get("status", "")).lower() == "completed"]
        pending_items = [r for r in worker_items if str(r.get("status", "")).lower() != "completed"]
        if completed_items and pending_items:
            expected_subtasks = self._extract_plan_step_subtasks(plan_step, limit=7)
            expected_ids: set[str] = set()
            for item in expected_subtasks:
                mm = re.match(r"^(\d+\.\d+)\b", str(item or "").strip())
                if mm:
                    expected_ids.add(mm.group(1))
            if expected_ids:
                completed_ids: set[str] = set()
                pending_expected: list[dict] = []
                for row in completed_items:
                    mm = re.match(r"^(\d+\.\d+)\b", str(row.get("content", "") or "").strip())
                    if mm:
                        completed_ids.add(mm.group(1))
                for row in pending_items:
                    mm = re.match(r"^(\d+\.\d+)\b", str(row.get("content", "") or "").strip())
                    if mm and mm.group(1) in expected_ids:
                        pending_expected.append(row)
                if expected_ids.issubset(completed_ids) and not pending_expected:
                    worker_items = completed_items
                    pending_items = []
            # Check if pending items are content-wise duplicates of completed items
            # (indicating the worker re-sent the same items but some got stuck as pending)
            completed_content = {
                normalize_work_text(str(r.get("content", ""))).strip().lower()
                for r in completed_items
                if str(r.get("content", "") or "").strip()
            }
            truly_new_pending = [
                r for r in pending_items
                if normalize_work_text(str(r.get("content", ""))).strip().lower() not in completed_content
            ]
            # If all pending items are duplicates of completed items, they don't block
            if not truly_new_pending:
                worker_items = completed_items
            # If there are truly new pending items but all original items are done,
            # check if the new items match future plan step content
            elif truly_new_pending and len(completed_items) >= 2:
                bb = self._ensure_blackboard()
                future_step_content = set()
                found_current = False
                for t in bb.get("project_todos", []):
                    if not isinstance(t, dict) or t.get("category") != "plan_step":
                        continue
                    if str(t.get("id", "") or "") == step_id:
                        found_current = True
                        continue
                    if found_current:
                        fc = str(t.get("full_content", "") or t.get("content", "") or "").strip().lower()
                        future_step_content.add(fc)
                        for line in fc.split("\n"):
                            sl = line.strip().lower()
                            if sl:
                                future_step_content.add(sl)
                if future_step_content:
                    _still_blocking = []
                    for pi in truly_new_pending:
                        pc = normalize_work_text(str(pi.get("content", ""))).strip().lower()
                        # Check if this pending item's content appears in any future step
                        is_future = any(pc in fsc or fsc in pc for fsc in future_step_content if len(fsc) > 4)
                        if not is_future:
                            _still_blocking.append(pi)
                    if not _still_blocking:
                        worker_items = completed_items
        all_marked_done = all(str(r.get("status", "")).lower() == "completed" for r in worker_items)
        if not all_marked_done:
            return False
        return True

    def _step_work_subtasks_completed(self, plan_step: dict) -> bool:
        """Return whether executable work is done, regardless of acceptance state."""
        if not isinstance(plan_step, dict):
            return False
        step_id = str(plan_step.get("id", "") or "")
        if not step_id:
            return False
        rows = self._active_plan_worker_todo_rows(step_id, role="")
        work_rows = [
            row for row in rows
            if not self._is_plan_step_acceptance_subtask(row.get("content", ""))
        ]
        return bool(work_rows) and all(
            str(row.get("status", "") or "").strip().lower() == "completed"
            for row in work_rows
        )

    def _verify_subtasks_acceptance(self, subtasks: list[dict], step_id: str, bb: dict) -> list[str]:
        """Verify each completed subtask has real evidence. Returns list of unverified subtask descriptions.
        Checks step_files and execution_logs against what each subtask's content implies."""
        import re
        # Gather accumulated evidence for this step
        step_files_raw = bb.get("step_files", {}) if isinstance(bb.get("step_files"), dict) else {}
        step_entries = step_files_raw.get(step_id, []) if step_id and isinstance(step_files_raw.get(step_id), list) else []
        written_paths = set()
        for entry in step_entries:
            if isinstance(entry, dict) and str(entry.get("op", "")) in ("write_file", "edit_file"):
                written_paths.add(str(entry.get("path", "") or "").strip().lower())
        # Gather bash execution evidence
        exec_logs = bb.get("execution_logs", [])
        if not isinstance(exec_logs, list):
            exec_logs = []
        bash_outputs_lower = []
        for log in exec_logs[-30:]:
            if isinstance(log, dict):
                c = str(log.get("content", "") or "").lower()
                if c:
                    bash_outputs_lower.append(c)
        all_bash_text = " ".join(bash_outputs_lower)
        negative_hints = ("error:", "failed", "failure", "traceback", "fatal", "not found",
                          "no such file", "command not found", "permission denied")
        has_bash_failure = any(neg in all_bash_text for neg in negative_hints)
        # Define acceptance patterns from subtask content
        _file_create_re = re.compile(
            r"(?:创建|生成|编写|写入|create|write|generate|implement|scaffold)\s+(.+?)(?:\s|$|，|。|,|\()",
            re.IGNORECASE,
        )
        _run_test_kw = ("运行", "测试", "验证", "test", "pytest", "verify", "validate",
                        "run", "check", "确认", "检查")
        _compile_kw = ("编译", "构建", "compile", "build", "cmake", "make", "gcc", "gfortran")
        _install_kw = ("安装", "install", "pip install", "npm install", "apt install")
        unverified: list[str] = []
        for st in subtasks:
            content = str(st.get("content", "") or "").strip()
            if not content:
                continue
            content_lower = content.lower()
            # Rule 1: If subtask mentions creating a file, check it was actually written
            m = _file_create_re.search(content)
            if m:
                target = m.group(1).strip().strip("\"'`").lower()
                # Extract just filename from path-like strings
                if "/" in target:
                    target_parts = [p for p in target.split("/") if p.strip()]
                    target_name = target_parts[-1] if target_parts else target
                else:
                    target_name = target
                if target_name and len(target_name) > 2:
                    found = any(target_name in wp for wp in written_paths)
                    if not found:
                        unverified.append(f"file not created: {target_name}")
                        continue
            # Rule 2: If subtask mentions testing/running/verifying, check bash was executed
            if any(kw in content_lower for kw in _run_test_kw):
                if not bash_outputs_lower:
                    unverified.append(f"no bash execution for: {trim(content, 60)}")
                    continue
                # Check for test failures in recent bash output
                if has_bash_failure and any(kw in content_lower for kw in ("test", "测试", "pytest")):
                    # Only block if failure keywords appear near test-related content
                    test_related_failures = any(
                        ("test" in line or "pytest" in line or "assert" in line)
                        and any(neg in line for neg in negative_hints)
                        for line in bash_outputs_lower[-10:]
                    )
                    if test_related_failures:
                        unverified.append(f"test failures detected for: {trim(content, 60)}")
                        continue
            # Rule 3: If subtask mentions compiling/building, check bash + no compile errors
            if any(kw in content_lower for kw in _compile_kw):
                if not bash_outputs_lower:
                    unverified.append(f"no bash execution for compile: {trim(content, 60)}")
                    continue
                compile_failures = any(
                    any(neg in line for neg in ("error:", "failed", "failure"))
                    and any(kw in line for kw in ("compil", "build", "cmake", "make", "link"))
                    for line in bash_outputs_lower[-10:]
                )
                if compile_failures:
                    unverified.append(f"compile failures for: {trim(content, 60)}")
                    continue
            # Rule 4: If subtask mentions installing, check bash was run
            if any(kw in content_lower for kw in _install_kw):
                if not bash_outputs_lower:
                    unverified.append(f"no bash for install: {trim(content, 60)}")
                    continue
            # If none of the specific rules matched, the subtask is considered verified
            # (generic subtasks like "design" or "analyze" don't need tool evidence)
        return unverified

    def _inject_rework_if_needed(self, plan_step: dict, worker_step: dict):
        """When subtasks are marked completed but acceptance fails, inject rework instruction.
        Prevents the system from getting stuck or silently skipping unfinished work."""
        try:
            step_id = str(plan_step.get("id", "") or "")
            if not step_id:
                return
            rows = self._active_plan_worker_todo_rows(step_id, role="")
            completed_rows = [r for r in rows if str(r.get("status", "")).lower() == "completed"]
            if not completed_rows:
                return
            bb = self._ensure_blackboard()
            failures = self._verify_subtasks_acceptance(completed_rows, step_id, bb)
            if not failures:
                return
            # LLM-based acceptance check: semantic analysis over heuristics
            llm_verdict = self._llm_verify_subtask_acceptance(plan_step, completed_rows, bb)
            if llm_verdict.get("all_passed", False):
                return
            rework_items = llm_verdict.get("rework_items", failures)
            if not rework_items:
                return
            # Rate-limit rework injection
            _rework_key = f"_rework_injected_{step_id}"
            _last_rework = getattr(self, _rework_key, 0.0)
            if float(now_ts()) - float(_last_rework) < 30.0:
                return
            setattr(self, _rework_key, float(now_ts()))
            step_label = trim(str(plan_step.get("content", "") or ""), 80)
            rework_text = (
                f"<step-rework>\n"
                f"Step \"{step_label}\" acceptance check FAILED. "
                f"The following subtasks were marked completed but did not pass verification:\n"
            )
            for i, item in enumerate(rework_items[:5]):
                rework_text += f"  {i+1}. {trim(str(item), 120)}\n"
            rework_text += (
                "\nACTION REQUIRED: Fix these issues NOW before the step can advance.\n"
                "- For missing files: create them with write_file\n"
                "- For failed tests/builds: run the command again and fix errors\n"
                "- For unverified installs: re-run the install command\n"
                "After fixing, update TodoWrite to reflect the corrected state.\n"
                "</step-rework>"
            )
            # Revert false "completed" status back to in_progress
            _snap = self.todo.snapshot()
            _modified = False
            for row in _snap:
                if not isinstance(row, dict):
                    continue
                if str(row.get("parent_step_id", "") or "") != step_id:
                    continue
                if str(row.get("status", "")).lower() != "completed":
                    continue
                rc = str(row.get("content", "") or "").strip().lower()
                for fail in rework_items:
                    fail_lower = str(fail).lower()
                    if rc and (rc[:20] in fail_lower or any(w in fail_lower for w in rc.split()[:3] if len(w) > 3)):
                        row["status"] = "in_progress"
                        _modified = True
                        break
            if _modified:
                try:
                    self.todo.update(_snap)
                except Exception:
                    pass
            target_roles: tuple[str, ...] = ()
            if self._is_multi_agent_mode():
                active_role = str(bb.get("active_agent", "") or "developer")
                if active_role:
                    target_roles = (active_role,)
            self._append_plan_guidance_bubble(
                rework_text,
                target_roles=target_roles,
                summary=f"step rework: {len(rework_items)} items failed acceptance",
            )
        except Exception:
            pass

    def _llm_verify_subtask_acceptance(self, plan_step: dict, completed_subtasks: list[dict], bb: dict) -> dict:
        """Use LLM semantic analysis to verify if subtasks are truly completed.
        Returns {"all_passed": bool, "rework_items": list[str]}."""
        try:
            step_id = str(plan_step.get("id", "") or "")
            step_files_raw = bb.get("step_files", {}) if isinstance(bb.get("step_files"), dict) else {}
            step_entries = step_files_raw.get(step_id, []) if step_id else []
            files_summary = []
            for entry in (step_entries[-15:] if isinstance(step_entries, list) else []):
                if isinstance(entry, dict):
                    files_summary.append(f"{entry.get('op','?')}: {entry.get('path','?')}")
            exec_logs = bb.get("execution_logs", [])
            recent_exec = []
            for log in (exec_logs[-8:] if isinstance(exec_logs, list) else []):
                if isinstance(log, dict):
                    c = trim(str(log.get("content", "") or ""), 200)
                    if c:
                        recent_exec.append(c)
            subtask_list = "\n".join(
                f"- [{str(st.get('status','')).upper()}] {trim(str(st.get('content','') or ''), 120)}"
                for st in completed_subtasks[:8]
            )
            prompt = (
                "Analyze whether these subtasks are TRULY completed based on the evidence.\n\n"
                f"SUBTASKS:\n{subtask_list}\n\n"
                f"FILES CREATED/MODIFIED:\n{chr(10).join(files_summary[-10:]) or '(none)'}\n\n"
                f"RECENT EXECUTION OUTPUT:\n{chr(10).join(recent_exec[-5:]) or '(none)'}\n\n"
                "For each subtask, determine if it's genuinely done:\n"
                "- File creation tasks: was the file actually created?\n"
                "- Test/verify tasks: was a test/command actually run? Did it pass?\n"
                "- Build/compile tasks: was compilation attempted? Any errors?\n"
                "- Install tasks: was the install command run?\n\n"
                "Reply ONLY as JSON: {\"all_passed\": true/false, \"rework_items\": [\"description of what failed\"]}\n"
                "If all subtasks pass, return {\"all_passed\": true, \"rework_items\": []}"
            )
            resp = self.ollama.chat(
                [{"role": "user", "content": prompt}],
                system=self._inject_runtime_environment_context("You are a strict QA reviewer. Verify task completion against evidence. Reply ONLY valid JSON."),
                max_tokens=300,
                think=False,
            )
            import json
            text = str(resp.get("text", "") or "").strip()
            if "{" in text:
                json_str = text[text.index("{"):text.rindex("}") + 1]
                result = json.loads(json_str)
                if isinstance(result, dict):
                    return {
                        "all_passed": bool(result.get("all_passed", False)),
                        "rework_items": list(result.get("rework_items", [])),
                    }
        except Exception:
            pass
        return {"all_passed": False, "rework_items": []}

    def _acceptance_semantic_judge(
        self,
        plan_step: dict,
        gate: dict,
        bb: dict,
        worker_step: dict | None = None,
    ) -> dict:
        """Strict LLM judge that decides whether a step GENUINELY meets its
        acceptance criteria, used when the heuristic gate keeps failing.

        The heuristic gate (`_plan_step_acceptance_gate_status`) matches evidence
        by keyword and CAN false-negative (e.g. tests passed but output contains
        the word "failed" in a warning, or the worker used a different-but-valid
        check). This judge reads the ACTUAL evidence and renders a verdict, so a
        genuinely-complete step advances as semantic-verified rather than looping.
        It is intentionally strict: it must PASS only on concrete evidence, never
        on a completion claim. Returns:
          {passed: bool, confidence: "high"|"medium"|"low",
           evidence: str, rework_items: list[str]}
        """
        default = {"passed": False, "confidence": "low", "evidence": "", "rework_items": []}
        try:
            step_text = trim(
                normalize_embedded_newlines(
                    str(plan_step.get("full_content", "") or plan_step.get("content", "") or "")
                ),
                700,
            )
            step_id = str(plan_step.get("id", "") or "")
            guidance = {}
            try:
                guidance = self._plan_step_acceptance_guidance(plan_step)
            except Exception:
                guidance = {}
            gate_reason = trim(str((gate or {}).get("reason", "") or ""), 120)
            gate_expected = trim(str((gate or {}).get("expected", "") or ""), 160)

            # Acceptance subtask text (what the worker said it would verify).
            acceptance = (gate or {}).get("acceptance", {}) if isinstance((gate or {}).get("acceptance"), dict) else {}
            acceptance_text = trim(
                str(
                    (gate or {}).get("acceptance_contract", "")
                    or self._effective_plan_step_acceptance_text(
                        plan_step,
                        acceptance.get("content", ""),
                    )
                ),
                500,
            )

            # Use only step-scoped, current evidence. Legacy aggregate logs can
            # mix steps and include checks invalidated by later edits.
            acceptance_since = self._acceptance_evidence_since_ts(acceptance, plan_step)
            durable = self._plan_step_evidence_records(
                step_id,
                board=bb,
                since_ts=acceptance_since,
            ) if step_id else []
            if step_id:
                durable.extend(self._plan_step_acceptance_review_records(
                    plan_step,
                    board=bb,
                    since_ts=acceptance_since,
                ))
            files_summary = [
                f"{row.get('tool', '?')}: {row.get('path', '') or ', '.join(row.get('changed_files', []) or [])}"
                for row in durable[-15:]
                if str(row.get("kind", "") or "") == "file" or row.get("changed_files")
            ]
            recent_exec = [
                trim(
                    f"{row.get('tool', '?')} {row.get('command', '')}: "
                    f"exit_code={row.get('exit_code')} {row.get('summary', '')}",
                    320,
                )
                for row in durable[-10:]
                if str(row.get("kind", "") or "") == "runtime"
            ]
            durable_evidence = [
                trim(
                    f"{row.get('kind', '?')}/{row.get('tool', '?')} "
                    f"path={row.get('path', '')} exit_code={row.get('exit_code')} "
                    f"ok={row.get('ok')} {row.get('summary', '')}",
                    420,
                )
                for row in durable[-16:]
            ]
            cur_results = []
            if isinstance(worker_step, dict):
                for r in (worker_step.get("tool_results", []) or []):
                    if isinstance(r, dict) and r.get("ok", False):
                        nm = str(r.get("name", "") or "")
                        if nm in {"bash", "worktree_run", "check_background"} and not self._tool_result_is_passing_execution(r):
                            continue
                        ex = self._tool_result_output_excerpt(r, 160)
                        cur_results.append(f"{nm}: {ex}" if ex else nm)

            prompt = (
                "A heuristic acceptance gate flagged this plan step as NOT verified, but the heuristic "
                "matches evidence by keyword and can be a FALSE NEGATIVE. As a strict QA judge, read the "
                "ACTUAL evidence below and decide whether the step genuinely meets its acceptance criteria.\n\n"
                f"PLAN STEP: {step_text}\n"
                f"ACCEPTANCE CHECK (what should be verified): {acceptance_text or guidance.get('what','')}\n"
                f"EXPECTED EVIDENCE KIND: {gate_expected or guidance.get('evidence_kind','')}\n"
                f"GATE FAILURE REASON: {gate_reason}\n\n"
                f"FILES CREATED/MODIFIED FOR THIS STEP:\n{chr(10).join(files_summary[-12:]) or '(none)'}\n\n"
                f"EXECUTION OUTPUT (this step):\n{chr(10).join(recent_exec[-6:]) or '(none)'}\n\n"
                f"AGGREGATED STEP EVIDENCE:\n{chr(10).join(durable_evidence[-12:]) or '(none)'}\n\n"
                f"CURRENT-TURN TOOL RESULTS:\n{chr(10).join(cur_results[-6:]) or '(none)'}\n\n"
                "Decide STRICTLY:\n"
                "- PASS only if concrete evidence shows the step's deliverable exists AND is correct "
                "(e.g. file truly created with the right content; test/build actually ran and succeeded; "
                "exit code 0; research produced cited findings). A warning word like 'failed' inside "
                "otherwise-successful output is NOT a failure.\n"
                "- FAIL if the deliverable is missing, the check never ran, or evidence shows a real error.\n"
                "- Never PASS on a mere claim without evidence.\n\n"
                "Reply ONLY as JSON: "
                "{\"passed\": true/false, \"confidence\": \"high|medium|low\", "
                "\"evidence\": \"<cite the specific evidence you relied on>\", "
                "\"rework_items\": [\"<what concretely must still be fixed if FAIL>\"]}"
            )
            resp = self.ollama.chat(
                [{"role": "user", "content": prompt}],
                system=self._inject_runtime_environment_context(
                    "You are a strict, evidence-driven QA judge for plan-step acceptance. "
                    "You correct heuristic false-negatives but never rubber-stamp unproven claims. Reply ONLY valid JSON."
                ),
                max_tokens=400,
                think=False,
            )
            import json
            text = str(resp.get("content", "") or resp.get("text", "") or "").strip()
            if "{" in text and "}" in text:
                result = json.loads(text[text.index("{"):text.rindex("}") + 1])
                if isinstance(result, dict):
                    conf = str(result.get("confidence", "low") or "low").strip().lower()
                    if conf not in ("high", "medium", "low"):
                        conf = "low"
                    return {
                        "passed": bool(result.get("passed", False)),
                        "confidence": conf,
                        "evidence": trim(str(result.get("evidence", "") or ""), 300),
                        "rework_items": [trim(str(x), 200) for x in (result.get("rework_items", []) or [])][:6],
                    }
        except Exception:
            pass
        return default

    def _collect_step_evidence(self, plan_step: dict, worker_step: dict) -> str:
        """Collect evidence summary from worker step for plan step completion."""
        parts = []
        results = worker_step.get("tool_results", []) or []
        for r in results:
            if not isinstance(r, dict) or not r.get("ok", False):
                continue
            name = str(r.get("name", ""))
            if name in ("write_file", "edit_file"):
                path = str(r.get("args", {}).get("path", "") or "")
                parts.append(f"{name}: {path}")
            elif name == "bash":
                cmd = trim(str(r.get("args", {}).get("command", "") or ""), 80)
                out = self._tool_result_output_excerpt(r, 120)
                parts.append(f"bash: {cmd}" + (f" => {out}" if out else ""))
            elif name == "read_file":
                path = str(r.get("args", {}).get("path", "") or "")
                # Skip plan-infrastructure reads — not meaningful implementation evidence
                _p = str(path)
                if (_p.endswith("plan.md") and ".clouds_coder" in _p) or ".clouds_coder/skills_cache/" in _p:
                    continue
                out = self._tool_result_output_excerpt(r, 90)
                parts.append(f"read: {path}" + (f" => {out}" if out else ""))
            elif name in ("write_to_blackboard", "read_from_blackboard", "query_code_library", "query_knowledge_library", "agent_web_search"):
                out = self._tool_result_output_excerpt(r, 100)
                parts.append(f"{name}" + (f": {out}" if out else ""))
        if not parts:
            bb_evidence = self._collect_blackboard_step_evidence(plan_step)
            if bb_evidence:
                return bb_evidence
        return trim("; ".join(parts) or "post-execution evidence", 200)

    def _get_active_plan_step(self, board: dict | None = None) -> dict | None:
        bb = board if isinstance(board, dict) else self._ensure_blackboard()
        todos = bb.get("project_todos", []) if isinstance(bb.get("project_todos", []), list) else []
        for todo in todos:
            if isinstance(todo, dict) and todo.get("category") == "plan_step" and todo.get("status") == "in_progress":
                return todo
        return None

    def _plan_step_ordinal(self, plan_step: dict | None, board: dict | None = None) -> int:
        """1-based ordinal N used as the prefix in worker subtasks 'N.M'.

        Derived from the step's plan_step_index (authoritative), falling back to
        the numeric suffix of a 'pt:NNN' id, then to the step's position among
        plan_step todos. Returns 1 when nothing is determinable so numbering is
        always present (never blank).
        """
        if not isinstance(plan_step, dict):
            return 1
        idx = plan_step.get("plan_step_index", None)
        try:
            if idx is not None and int(idx) >= 0:
                return int(idx) + 1
        except Exception:
            pass
        sid = str(plan_step.get("id", "") or "")
        m = re.match(r"^pt:(\d+)$", sid)
        if m:
            try:
                return int(m.group(1)) + 1
            except Exception:
                pass
        bb = board if isinstance(board, dict) else self._ensure_blackboard()
        todos = bb.get("project_todos", []) if isinstance(bb.get("project_todos"), list) else []
        pos = 0
        for todo in todos:
            if isinstance(todo, dict) and todo.get("category") == "plan_step":
                pos += 1
                if str(todo.get("id", "") or "") == sid:
                    return pos
        return 1

    def _current_plan_worker_owner(self, board: dict | None = None) -> str:
        bb = board if isinstance(board, dict) else self._ensure_blackboard()
        step = self._get_active_plan_step(bb)
        if isinstance(step, dict):
            child = self._current_plan_worker_subtask_snapshot(board=bb, role="")
            for source in (child, step):
                for key in ("owner", "owner_role", "assigned_expert"):
                    owner = self._sanitize_agent_role(source.get(key, "")) if isinstance(source, dict) else ""
                    if owner in AGENT_ROLES:
                        return owner
        delegate = bb.get("last_delegate", {}) if isinstance(bb.get("last_delegate"), dict) else {}
        candidates = [
            str(self.active_agent_role or "").strip().lower(),
            str(bb.get("active_agent", "") or "").strip().lower(),
            str(delegate.get("target", "") or "").strip().lower(),
        ]
        for cand in candidates:
            if cand in {"developer", "explorer", "reviewer"}:
                return cand
        assigned = self._sanitize_agent_role(
            (bb.get("task_profile", {}) if isinstance(bb.get("task_profile"), dict) else {}).get(
                "assigned_expert", self.runtime_assigned_expert
            )
        )
        return assigned or "developer"

    def _get_plan_step_by_id(self, step_id: str, board: dict | None = None) -> dict | None:
        step_key = trim(str(step_id or "").strip(), 40)
        if not step_key:
            return None
        bb = board if isinstance(board, dict) else self._ensure_blackboard()
        todos = bb.get("project_todos", []) if isinstance(bb.get("project_todos", []), list) else []
        for todo in todos:
            if (
                isinstance(todo, dict)
                and str(todo.get("category", "") or "") == "plan_step"
                and trim(str(todo.get("id", "") or "").strip(), 40) == step_key
            ):
                return todo
        return None

    def _canonical_plan_worker_parent_id(
        self,
        parent_step_id: object,
        *,
        rows: list[dict] | None = None,
        board: dict | None = None,
    ) -> str:
        """Resolve legacy step aliases onto the canonical project todo id."""
        bb = board if isinstance(board, dict) else self._ensure_blackboard()
        plan_steps = [
            item for item in (bb.get("project_todos", []) if isinstance(bb.get("project_todos"), list) else [])
            if isinstance(item, dict) and str(item.get("category", "") or "") == "plan_step"
        ]
        if not plan_steps:
            return ""
        raw_parent = trim(str(parent_step_id or "").strip(), 40)
        exact = next(
            (
                trim(str(item.get("id", "") or "").strip(), 40)
                for item in plan_steps
                if trim(str(item.get("id", "") or "").strip(), 40) == raw_parent
            ),
            "",
        )
        if exact:
            return exact

        desired_index: int | None = None
        alias = re.fullmatch(
            r"(?:step|步骤|步驟|阶段|階段)[\s:_-]*0*(\d+)",
            raw_parent,
            flags=re.IGNORECASE,
        )
        if alias:
            desired_index = max(0, int(alias.group(1)) - 1)
        else:
            # Providers commonly serialize a plan-step ordinal as the bare
            # value ``"1"`` (or ``"#1"``) instead of echoing the opaque
            # canonical ``pt:<epoch>:000`` id.  Treat that shape as a 1-based
            # roadmap ordinal.  Resolution still goes through project_todos,
            # so an alias for a different step remains a real cross-step row
            # and is rejected by the caller rather than silently rebound.
            ordinal_alias = re.fullmatch(
                r"#?\s*0*(\d+)\s*[.)、．]?",
                raw_parent,
                flags=re.IGNORECASE,
            )
            if ordinal_alias:
                desired_index = max(0, int(ordinal_alias.group(1)) - 1)
            else:
                pt_alias = re.fullmatch(r"pt[\s:_-]*0*(\d+)", raw_parent, flags=re.IGNORECASE)
                if pt_alias:
                    desired_index = max(0, int(pt_alias.group(1)))

        if desired_index is None and isinstance(rows, list):
            majors: list[int] = []
            for row in rows:
                if not isinstance(row, dict):
                    continue
                content = normalize_embedded_newlines(str(row.get("content", "") or "")).strip()
                marker = self._plan_line_marker(content)
                if isinstance(marker, dict) and str(marker.get("kind", "") or "") == "sub":
                    majors.append(int(marker.get("major", 0) or 0))
            unique_majors = {major for major in majors if major > 0}
            if len(unique_majors) == 1:
                desired_index = next(iter(unique_majors)) - 1

        if desired_index is None:
            return ""
        match = next(
            (
                item for item in plan_steps
                if (
                    int(item.get("plan_step_index"))
                    if item.get("plan_step_index") not in (None, "")
                    else -1
                ) == desired_index
            ),
            None,
        )
        return trim(str((match or {}).get("id", "") or "").strip(), 40)

    def _plan_worker_content_core(self, text: object) -> str:
        raw = normalize_work_text(str(text or "")) or str(text or "")
        raw = re.sub(r"^\s*\d+\.\d+\s+", "", raw)
        raw = re.sub(r"\s+", " ", raw.strip().lower())
        return raw

    def _plan_worker_semantic_core(self, text: object) -> str:
        """Normalize harmless Todo phrasing differences without changing IDs."""
        raw = unicodedata.normalize(
            "NFKC",
            normalize_work_text(str(text or "")) or str(text or ""),
        ).strip().lower()
        _status, parsed = split_todo_status_text(raw)
        raw = parsed or raw
        raw = re.sub(
            r"^\s*(?:(?:step|subtask|task|步骤|步驟|子任务|子任務)\s*)?"
            r"\d+(?:\.\d+)*\s*[.)、:：-]?\s*",
            "",
            raw,
            flags=re.IGNORECASE,
        )
        raw = re.split(
            r"\s*[;；]\s*(?:evidence|证据|證據|証拠)\s*[:：]",
            raw,
            maxsplit=1,
            flags=re.IGNORECASE,
        )[0]
        raw = re.sub(r"[\s\W_]+", " ", raw, flags=re.UNICODE).strip()
        return raw

    def _plan_worker_todo_match_score(self, incoming: dict | None, existing: dict | None) -> float:
        """Score two active-step rows; only high, unique scores are canonical matches."""
        if not isinstance(incoming, dict) or not isinstance(existing, dict):
            return 0.0
        incoming_acceptance = self._is_plan_step_acceptance_subtask(incoming.get("content", ""))
        existing_acceptance = self._is_plan_step_acceptance_subtask(existing.get("content", ""))
        if incoming_acceptance or existing_acceptance:
            return 1.0 if incoming_acceptance and existing_acceptance else 0.0
        incoming_id = trim(str(incoming.get("subtask_id", "") or ""), 80)
        existing_id = trim(str(existing.get("subtask_id", "") or ""), 80)
        if incoming_id and existing_id and incoming_id == existing_id:
            return 1.0
        incoming_aliases = self._plan_worker_external_identity_values(incoming)
        existing_aliases = self._plan_worker_external_identity_values(existing)
        if incoming_aliases and existing_aliases and incoming_aliases.intersection(existing_aliases):
            return 0.999
        left = self._plan_worker_semantic_core(incoming.get("content", ""))
        right = self._plan_worker_semantic_core(existing.get("content", ""))
        if not left or not right:
            return 0.0
        if left == right:
            return 0.99
        if min(len(left), len(right)) >= 6 and (left in right or right in left):
            containment = min(len(left), len(right)) / max(len(left), len(right))
            if containment >= 0.55:
                return max(0.80, min(0.94, 0.72 + containment * 0.22))
        sequence_score = difflib.SequenceMatcher(None, left, right).ratio()
        left_tokens = self._plan_revision_relation_tokens(left)
        right_tokens = self._plan_revision_relation_tokens(right)
        token_score = (
            len(left_tokens & right_tokens) / max(1, min(len(left_tokens), len(right_tokens)))
            if left_tokens and right_tokens
            else 0.0
        )
        left_paths = {
            normalize_rel_preview_path(value).lower()
            for value in self._extract_plan_step_referenced_paths(left, limit=8)
            if normalize_rel_preview_path(value)
        }
        right_paths = {
            normalize_rel_preview_path(value).lower()
            for value in self._extract_plan_step_referenced_paths(right, limit=8)
            if normalize_rel_preview_path(value)
        }
        path_score = 0.0
        if left_paths and right_paths and left_paths.intersection(right_paths):
            path_score = 0.90
        base_score = max(sequence_score, token_score, path_score)
        left_number = re.match(r"^\s*(\d+\.\d+)\b", str(incoming.get("content", "") or ""))
        right_number = re.match(r"^\s*(\d+\.\d+)\b", str(existing.get("content", "") or ""))
        if (
            left_number
            and right_number
            and left_number.group(1) == right_number.group(1)
            and base_score >= 0.34
        ):
            base_score = max(base_score, 0.88)
        return float(min(1.0, base_score))

    def _plan_worker_rows_equivalent(self, incoming: dict | None, existing: dict | None) -> bool:
        return self._plan_worker_todo_match_score(incoming, existing) >= 0.64

    @staticmethod
    def _is_canonical_plan_worker_subtask_id(value: object, step_id: object = "") -> bool:
        subtask_id = trim(str(value or "").strip(), 100)
        if not subtask_id.startswith("pst:"):
            return False
        step_key = trim(str(step_id or "").strip(), 40)
        return not step_key or subtask_id.startswith(f"pst:{step_key}:")

    def _plan_worker_external_identity_values(self, row: dict | None) -> set[str]:
        """Return provider identities without confusing them with canonical IDs."""
        if not isinstance(row, dict):
            return set()
        values: set[str] = set()
        for field in (
            "external_subtask_id", "external_id", "todo_id", "task_id",
            "item_id", "row_id", "id", "key",
        ):
            value = trim(str(row.get(field, "") or "").strip(), 120)
            if value and not value.startswith("bb:"):
                values.add(value.casefold())
        supplied = trim(str(row.get("subtask_id", "") or "").strip(), 100)
        if supplied and not self._is_canonical_plan_worker_subtask_id(supplied):
            values.add(supplied.casefold())
        return values

    def _capture_plan_worker_external_identity(self, row: dict, step_id: object) -> dict:
        """Preserve a legacy/provider subtask id before assigning a pst: id."""
        if not isinstance(row, dict):
            return row
        supplied = trim(str(row.get("subtask_id", "") or "").strip(), 100)
        if supplied and not self._is_canonical_plan_worker_subtask_id(supplied, step_id):
            row.setdefault("external_subtask_id", supplied)
        return row

    def _stable_plan_worker_subtask_id(
        self,
        step_id: object,
        row: dict | None,
    ) -> str:
        item = row if isinstance(row, dict) else {}
        step_key = trim(str(step_id or item.get("parent_step_id", "") or "").strip(), 40)
        if not step_key:
            return ""
        content = str(item.get("content", "") or "")
        if self._is_plan_step_acceptance_subtask(content):
            return f"pst:{step_key}:acceptance"
        existing = trim(str(item.get("subtask_id", "") or "").strip(), 80)
        if existing and self._is_canonical_plan_worker_subtask_id(existing, step_key):
            return existing
        core = self._plan_worker_content_core(content)
        if not core:
            return ""
        digest = hashlib.sha1(f"{step_key}|{core}".encode("utf-8", "ignore")).hexdigest()[:16]
        return f"pst:{step_key}:{digest}"

    def _dedupe_plan_worker_rows(self, rows: list[dict], step_id: object) -> list[dict]:
        step_key = trim(str(step_id or "").strip(), 40)
        if not step_key:
            return [dict(row) for row in (rows or []) if isinstance(row, dict)]
        status_rank = {"completed": 3, "in_progress": 2, "pending": 1, "blocked": 0}
        merged: dict[str, dict] = {}
        order: list[str] = []
        for index, raw in enumerate(rows or []):
            if not isinstance(raw, dict):
                continue
            row = dict(raw)
            self._capture_plan_worker_external_identity(row, step_key)
            identity = self._stable_plan_worker_subtask_id(step_key, row)
            if not identity:
                identity = f"anonymous:{index}:{self._plan_worker_content_core(row.get('content', ''))}"
            row["parent_step_id"] = step_key
            row["subtask_id"] = identity
            prior = merged.get(identity)
            if prior is None:
                merged[identity] = row
                order.append(identity)
                continue
            prior_status = self._normalize_todo_status_value(prior.get("status", ""), "pending")
            row_status = self._normalize_todo_status_value(row.get("status", ""), "pending")
            winner = row if status_rank.get(row_status, 0) > status_rank.get(prior_status, 0) else prior
            combined = dict(prior)
            for field in (
                "status", "completed_at", "completed_by", "evidence", "started_at",
                "updated_at", "owner", "key", "external_subtask_id",
            ):
                if winner.get(field) not in (None, "", 0, 0.0):
                    combined[field] = winner.get(field)
            prior_content = str(prior.get("content", "") or "")
            row_content = str(row.get("content", "") or "")
            if self._is_plan_step_acceptance_subtask(prior_content or row_content):
                prior_numbered = bool(re.match(r"^\s*\d+\.\d+\s+", normalize_work_text(prior_content) or prior_content))
                row_numbered = bool(re.match(r"^\s*\d+\.\d+\s+", normalize_work_text(row_content) or row_content))
                if row_numbered and not prior_numbered:
                    combined["content"] = row_content
            elif not prior_content and row_content:
                combined["content"] = row_content
            combined["parent_step_id"] = step_key
            combined["subtask_id"] = identity
            merged[identity] = combined
        return [merged[key] for key in order if key in merged]

    def _migrate_plan_worker_todo_partitions(self, board: dict) -> bool:
        """Merge legacy step aliases into canonical parent partitions without losing history."""
        if not isinstance(board, dict):
            return False
        mirror = board.get("plan_worker_todos", {})
        if not isinstance(mirror, dict) or not mirror:
            return False
        grouped: dict[str, list[dict]] = {}
        changed = False
        for raw_parent, raw_rows in mirror.items():
            rows = [dict(row) for row in raw_rows if isinstance(row, dict)] if isinstance(raw_rows, list) else []
            canonical = self._canonical_plan_worker_parent_id(
                raw_parent,
                rows=rows,
                board=board,
            )
            if not canonical:
                changed = True
                continue
            if canonical != trim(str(raw_parent or "").strip(), 40):
                changed = True
            for row in rows:
                if trim(str(row.get("parent_step_id", "") or "").strip(), 40) != canonical:
                    changed = True
                row["parent_step_id"] = canonical
                self._capture_plan_worker_external_identity(row, canonical)
                row["subtask_id"] = self._stable_plan_worker_subtask_id(canonical, row)
                grouped.setdefault(canonical, []).append(row)

        status_rank = {"completed": 3, "in_progress": 2, "pending": 1, "blocked": 0}
        migrated: dict[str, list[dict]] = {}
        for step_id, rows in grouped.items():
            plan_step = self._get_plan_step_by_id(step_id, board)
            rows = self._filter_parent_step_duplicate_worker_rows(rows, plan_step, board)
            merged_by_identity: dict[str, dict] = {}
            order: list[str] = []
            for row in rows:
                identity = self._stable_plan_worker_subtask_id(step_id, row)
                if not identity:
                    identity = f"legacy:{len(order)}:{self._plan_worker_content_core(row.get('content', ''))}"
                row["subtask_id"] = identity
                prior = merged_by_identity.get(identity)
                if prior is None:
                    merged_by_identity[identity] = dict(row)
                    order.append(identity)
                    continue
                changed = True
                prior_status = self._normalize_todo_status_value(prior.get("status", ""), "pending")
                row_status = self._normalize_todo_status_value(row.get("status", ""), "pending")
                winner = row if status_rank.get(row_status, 0) > status_rank.get(prior_status, 0) else prior
                loser = prior if winner is row else row
                combined = dict(loser)
                combined.update(winner)
                if len(str(loser.get("content", "") or "")) > len(str(combined.get("content", "") or "")):
                    combined["content"] = loser.get("content", "")
                for field in ("completed_at", "completed_by", "evidence", "started_at"):
                    if not combined.get(field) and loser.get(field):
                        combined[field] = loser.get(field)
                combined["updated_at"] = max(
                    float(prior.get("updated_at", 0.0) or 0.0),
                    float(row.get("updated_at", 0.0) or 0.0),
                )
                combined["parent_step_id"] = step_id
                combined["subtask_id"] = identity
                merged_by_identity[identity] = combined
            clean_rows = [merged_by_identity[key] for key in order if key in merged_by_identity]
            active_seen = False
            for row in clean_rows:
                status = self._normalize_todo_status_value(row.get("status", ""), "pending")
                if status == "in_progress":
                    if active_seen:
                        row["status"] = "pending"
                        changed = True
                    else:
                        active_seen = True
            if clean_rows:
                migrated[step_id] = clean_rows
        if migrated != mirror:
            changed = True
        board["plan_worker_todos"] = migrated
        return changed

    def _plan_todo_compare_forms(self, text: object) -> set[str]:
        import re

        raw = normalize_embedded_newlines(normalize_work_text(str(text or "")) or str(text or "")).strip()
        if not raw:
            return set()
        first = next((ln.strip() for ln in raw.splitlines() if ln.strip()), raw)
        _status, parsed = split_todo_status_text(first)
        base = parsed or first
        forms: set[str] = set()

        def _clean(value: str) -> str:
            val = normalize_work_text(value) or value
            val = re.sub(r"\s+", " ", val.strip().lower())
            val = re.sub(r"^(?:[-*•]\s*)?(?:\[[x >_]\]\s*)+", "", val).strip()
            val = re.sub(r"^#+\s*", "", val).strip()
            return val

        current = _clean(base)
        while current and current not in forms:
            forms.add(current)
            stripped = re.sub(
                r"^(?:(?:step|步骤|步驟|阶段|階段)\s*)?\d+\s*[：:]\s*",
                "",
                current,
                flags=re.IGNORECASE,
            ).strip()
            stripped = re.sub(r"^(?:step|步骤|步驟|阶段|階段)\s*\d+[\.\)．、]\s*", "", stripped, flags=re.IGNORECASE).strip()
            stripped = re.sub(r"^\d+[\.\)．、]\s+", "", stripped).strip()
            stripped = _clean(stripped)
            if stripped == current:
                break
            current = stripped
        return {form for form in forms if len(form) >= 2}

    def _plan_worker_row_duplicates_parent_step(self, row: dict | None, plan_step: dict | None) -> bool:
        if not isinstance(row, dict) or not isinstance(plan_step, dict):
            return False
        content = normalize_embedded_newlines(str(row.get("content", "") or "")).strip()
        if not content or self._is_plan_step_acceptance_subtask(content):
            return False
        marker = self._plan_line_marker(content)
        if isinstance(marker, dict) and marker.get("kind") == "sub":
            return False
        step_texts = [
            str(plan_step.get("content", "") or ""),
            str(plan_step.get("full_content", "") or ""),
        ]
        step_forms: set[str] = set()
        for text in step_texts:
            if not text:
                continue
            step_forms.update(self._plan_todo_compare_forms(text))
            first = next((ln.strip() for ln in normalize_embedded_newlines(text).splitlines() if ln.strip()), "")
            if first:
                step_forms.update(self._plan_todo_compare_forms(first))
        row_forms = self._plan_todo_compare_forms(content)
        if not row_forms or not step_forms:
            return False
        if row_forms.intersection(step_forms):
            return True
        if isinstance(marker, dict) and marker.get("kind") == "major":
            try:
                row_major = int(marker.get("major", 0) or 0)
                step_index = int(plan_step.get("plan_step_index", -1) or -1) + 1
            except Exception:
                row_major = 0
                step_index = -1
            marker_title_forms = self._plan_todo_compare_forms(str(marker.get("title", "") or ""))
            if row_major > 0 and row_major == step_index and marker_title_forms.intersection(step_forms):
                return True
        return False

    def _plan_worker_row_is_foreign_plan_step(
        self,
        row: dict | None,
        plan_step: dict | None,
        board: dict | None = None,
    ) -> bool:
        """Keep roadmap rows out of a step-local worker todo list."""
        if not isinstance(row, dict) or not isinstance(plan_step, dict):
            return False
        content = normalize_embedded_newlines(str(row.get("content", "") or "")).strip()
        if not content:
            return False
        active_ordinal = self._plan_step_ordinal(plan_step, board)
        head = next((line.strip() for line in content.splitlines() if line.strip()), content)
        marker = self._plan_line_marker(head)
        if isinstance(marker, dict):
            marker_kind = str(marker.get("kind", "") or "")
            marker_major = int(marker.get("major", 0) or 0)
            if marker_kind == "major" and marker_major != active_ordinal:
                return True
            if marker_kind == "sub" and marker_major != active_ordinal:
                return True
        if self._is_plan_step_acceptance_subtask(content):
            return False
        head = re.sub(r"^\s*\d+\.\d+\s+", "", head).strip()
        bb = board if isinstance(board, dict) else self._ensure_blackboard()
        todos = bb.get("project_todos", []) if isinstance(bb.get("project_todos"), list) else []
        row_forms = self._plan_todo_compare_forms(head)
        if not row_forms:
            return False
        for candidate in todos:
            if not isinstance(candidate, dict) or str(candidate.get("category", "") or "") != "plan_step":
                continue
            candidate_forms: set[str] = set()
            for value in (candidate.get("content", ""), candidate.get("full_content", "")):
                candidate_text = normalize_embedded_newlines(str(value or "")).strip()
                if not candidate_text:
                    continue
                first = next((line.strip() for line in candidate_text.splitlines() if line.strip()), candidate_text)
                candidate_forms.update(self._plan_todo_compare_forms(first))
            if row_forms.intersection(candidate_forms):
                return True
        return False

    def _filter_foreign_plan_step_worker_rows(
        self,
        rows: list[dict],
        plan_step: dict | None,
        board: dict | None = None,
    ) -> list[dict]:
        if not isinstance(rows, list) or not isinstance(plan_step, dict):
            return list(rows or [])
        return [
            dict(row)
            for row in rows
            if isinstance(row, dict)
            and not self._plan_worker_row_is_foreign_plan_step(row, plan_step, board)
        ]

    def _filter_parent_step_duplicate_worker_rows(
        self,
        rows: list[dict],
        plan_step: dict | None,
        board: dict | None = None,
    ) -> list[dict]:
        if not isinstance(rows, list) or not isinstance(plan_step, dict):
            return list(rows or [])
        deduped = [
            dict(row)
            for row in rows
            if isinstance(row, dict) and not self._plan_worker_row_duplicates_parent_step(row, plan_step)
        ]
        return self._filter_foreign_plan_step_worker_rows(deduped, plan_step, board)

    def _active_plan_worker_todo_rows(self, step_id: str, role: str = "") -> list[dict]:
        step_key = str(step_id or "").strip()
        if not step_key:
            return []
        role_key = self._sanitize_agent_role(role)
        all_rows: list[dict] = []
        for row in self.todo.snapshot():
            if not isinstance(row, dict):
                continue
            if str(row.get("parent_step_id", "") or "").strip() != step_key:
                continue
            owner = str(row.get("owner", "") or "").strip().lower()
            if owner not in {"developer", "explorer", "reviewer"}:
                continue
            all_rows.append(dict(row))
        if not all_rows:
            return self._plan_worker_todo_rows_from_blackboard(step_key, role=role_key)
        plan_step = self._get_plan_step_by_id(step_key)
        all_rows = self._filter_parent_step_duplicate_worker_rows(all_rows, plan_step)
        all_rows = self._dedupe_plan_worker_rows(all_rows, step_key)
        rows = [r for r in all_rows if str(r.get("owner", "") or "").strip().lower() == role_key] if role_key else list(all_rows)
        if role_key and not rows:
            rows = list(all_rows)
        rows.sort(key=self._plan_worker_todo_sort_key)
        return rows

    def _current_plan_worker_subtask_snapshot(
        self,
        *,
        board: dict | None = None,
        role: str = "",
    ) -> dict:
        bb = board if isinstance(board, dict) else self._ensure_blackboard()
        step = self._get_active_plan_step(bb)
        if not isinstance(step, dict):
            return {}
        step_id = trim(str(step.get("id", "") or ""), 40)
        if not step_id:
            return {}
        # The current subtask is one shared execution cursor. In Sync mode a
        # role-filtered view can hide another agent's in-progress row and make
        # the manager delegate a pending sibling or rebuild the subplan.
        rows = self._active_plan_worker_todo_rows(step_id, role="")
        current = next(
            (
                row for row in rows
                if str(row.get("status", "pending") or "pending").strip().lower() == "in_progress"
            ),
            None,
        )
        if not isinstance(current, dict):
            return {"step_id": step_id, "subtask_id": "", "subtask_content": "", "owner": ""}
        subtask_id = self._stable_plan_worker_subtask_id(step_id, current)
        return {
            "step_id": step_id,
            "subtask_id": subtask_id,
            "subtask_content": trim(str(current.get("content", "") or ""), 500),
            "owner": self._sanitize_agent_role(current.get("owner", "")),
        }

    def _plan_subtask_route_fields(
        self,
        *,
        board: dict | None = None,
        role: str = "",
    ) -> dict:
        snapshot = self._current_plan_worker_subtask_snapshot(board=board, role=role)
        return {
            "plan_subtask_id": trim(str(snapshot.get("subtask_id", "") or ""), 100),
            "plan_subtask_content": trim(str(snapshot.get("subtask_content", "") or ""), 500),
        }

    def _plan_worker_completed_status_has_evidence(
        self,
        row: dict | None,
        plan_step: dict | None,
        board: dict | None = None,
        *,
        allow_acceptance_semantic_review: bool = False,
        actor: str = "",
    ) -> bool:
        """Return whether a persisted completed worker row is evidence-backed.

        TodoManager and the blackboard are intentionally two durable views of
        the same execution graph.  A stale view can contain ``completed`` even
        though the tool event that justified it was never recorded (or belongs
        to another parent step).  Never let that stale bit win a merge.  The
        check is deliberately step-local and uses the stable subtask identity,
        so sync handoffs cannot manufacture completion or move the cursor back
        to an earlier child.
        """
        if not isinstance(row, dict) or not isinstance(plan_step, dict):
            return False
        status = self._normalize_todo_status_value(row.get("status", ""), "pending")
        if status != "completed":
            return True
        if self._normalize_todo_status_value(plan_step.get("status", ""), "pending") == "completed":
            return True
        step_id = trim(str(plan_step.get("id", "") or ""), 40)
        if not step_id:
            return False
        subtask_id = trim(str(row.get("subtask_id", "") or ""), 80)
        if not subtask_id:
            subtask_id = self._stable_plan_worker_subtask_id(step_id, row)
        content = str(row.get("content", "") or "").strip()
        if not content:
            return False
        if self._is_plan_step_acceptance_subtask(content):
            # Acceptance completion is validated by the dedicated gate. A
            # non-empty evidence field is only a hint: accept either concrete
            # tool evidence or an internally-authorized, contract-bound audit
            # event. Arbitrary Todo text can satisfy neither branch.
            records = self._matching_acceptance_evidence_records(
                plan_step,
                row,
                board=board,
                expected=self._acceptance_expected_evidence(
                    self._effective_plan_step_acceptance_text(plan_step, content)
                ),
            )
            if records:
                return True
            try:
                since_ts = self._acceptance_evidence_since_ts(row, plan_step)
            except Exception:
                since_ts = 0.0
            if self._trusted_plan_step_acceptance_records(
                plan_step,
                row,
                board=board,
                since_ts=since_ts,
            ):
                return True
            if not allow_acceptance_semantic_review:
                return False
            # A model explicitly requesting completion is the correct point for
            # the one-shot semantic fallback.  Passive restore/sync paths keep
            # this disabled, so simply loading a stale completed bit can never
            # trigger an LLM decision or manufacture progress.
            return self._semantic_acceptance_completion_has_evidence(
                plan_step,
                row,
                board=board,
                actor=actor,
            )
        bb = board if isinstance(board, dict) else self._ensure_blackboard()
        bindings = bb.get("plan_subtask_evidence_bindings", {}) if isinstance(bb.get("plan_subtask_evidence_bindings"), dict) else {}
        step_bindings = bindings.get(step_id, {}) if isinstance(bindings.get(step_id), dict) else {}
        binding = step_bindings.get(subtask_id, {}) if isinstance(step_bindings.get(subtask_id), dict) else {}
        if (
            binding
            and str(binding.get("source", "") or "") in {
                "direct", "semantic", "status_update", "evidence_reconcile", "trusted_restore",
            }
            and bool(binding.get("evidence_ids"))
        ):
            return True
        try:
            since_ts = float(row.get("created_at", 0.0) or row.get("started_at", 0.0) or 0.0)
        except Exception:
            since_ts = 0.0
        if self._plan_subtask_has_accumulated_evidence(
            plan_step,
            content,
            board=board,
            subtask_id=subtask_id,
            since_ts=since_ts,
        ):
            return True
        return bool(self._plan_subtask_semantic_completion_records(
            plan_step,
            row,
            board=board,
            subtask_id=subtask_id,
            since_ts=since_ts,
        ))

    def _semantic_acceptance_completion_has_evidence(
        self,
        plan_step: dict,
        acceptance: dict,
        *,
        board: dict | None = None,
        actor: str = "",
    ) -> bool:
        """Resolve an ambiguous acceptance completion against real step evidence.

        The existing quality judge is signature-cached.  We invoke it only when
        the deterministic gate reports semantic ambiguity and has current,
        step-local product evidence.  PASS is persisted as a contract-bound
        trusted event; VERIFY and REPAIR stay open and retain their audit for the
        normal gate/recovery route.
        """
        if not isinstance(plan_step, dict) or not isinstance(acceptance, dict):
            return False
        bb = board if isinstance(board, dict) else self._ensure_blackboard()
        step_id = trim(str(plan_step.get("id", "") or ""), 40)
        if not step_id:
            return False
        rows = self._active_plan_worker_todo_rows(step_id, role="")
        work_rows = [
            row for row in rows
            if not self._is_plan_step_acceptance_subtask(row.get("content", ""))
        ]
        if not work_rows or any(
            str(row.get("status", "") or "").strip().lower() != "completed"
            for row in work_rows
        ):
            return False
        since_ts = self._acceptance_evidence_since_ts(acceptance, plan_step)
        records = self._plan_step_evidence_records(step_id, board=bb, since_ts=since_ts)
        records.extend(self._plan_step_acceptance_review_records(
            plan_step,
            board=bb,
            since_ts=since_ts,
        ))
        product_records = [
            row for row in records
            if isinstance(row, dict)
            and not self._is_non_product_acceptance_error_record(row)
        ]
        passing_candidates = [
            row for row in product_records
            if self._plan_evidence_record_passes(row)
            or (
                str(row.get("assertion_kind", "") or "") == "negative_search_no_match"
                and bool(row.get("assertion_ok", False))
                and bool(row.get("assertion_complete", False))
            )
        ]
        if not passing_candidates:
            return False
        contract_text = self._effective_plan_step_acceptance_text(
            plan_step,
            acceptance.get("content", ""),
        )
        expected = self._acceptance_expected_evidence(contract_text)
        evaluation = self._evaluate_acceptance_evidence_records(
            product_records,
            expected,
            acceptance_text=contract_text,
            subject_text=str(
                plan_step.get("full_content", "")
                or plan_step.get("content", "")
                or ""
            ),
        )
        if str(evaluation.get("status", "") or "") == "failed":
            return False
        gate = {
            "ok": False,
            "reason": "final-acceptance-semantic-coverage-uncertain",
            "expected": expected,
            "acceptance": dict(acceptance),
            "acceptance_contract": contract_text,
            "candidate_evidence": product_records[-16:],
            "current_results": [],
            "evidence_evaluation": evaluation,
        }
        review = self._llm_review_plan_step_quality(
            plan_step,
            {"tool_results": []},
            bb,
            candidate_evidence={"gate": gate, "records": product_records[-16:]},
        )
        if not (
            review.get("available")
            and review.get("passed")
            and str(review.get("confidence", "") or "").lower() in {"high", "medium"}
        ):
            return False
        evidence_items = review.get("evidence", []) or []
        if not isinstance(evidence_items, list):
            evidence_items = [evidence_items]
        evidence_text = "; ".join(
            trim(str(item or ""), 260)
            for item in evidence_items[:4]
            if str(item or "").strip()
        ) or trim(str(review.get("reason", "") or "semantic acceptance pass"), 500)
        trusted = self._record_trusted_plan_step_acceptance_event(
            plan_step,
            acceptance,
            evidence=trim(f"[semantic-audit] {evidence_text}", 900),
            actor=str(actor or "reviewer"),
            source="semantic_audit",
        )
        return bool(trusted)

    def _plan_subtask_semantic_evidence_signature(
        self,
        plan_step: dict,
        row: dict,
        *,
        board: dict | None = None,
        subtask_id: str = "",
        since_ts: float = 0.0,
    ) -> tuple[str, list[dict]]:
        """Return a stable review signature and real current-step candidates."""
        if not isinstance(plan_step, dict) or not isinstance(row, dict):
            return "", []
        bb = board if isinstance(board, dict) else self._ensure_blackboard()
        step_id = trim(str(plan_step.get("id", "") or ""), 40)
        stable_id = trim(str(subtask_id or row.get("subtask_id", "") or ""), 80)
        if not stable_id and step_id:
            stable_id = self._stable_plan_worker_subtask_id(step_id, row)
        lower_bound = max(float(since_ts or 0.0), self._plan_step_activation_ts(plan_step))
        candidates = self._plan_step_evidence_records(
            step_id,
            board=bb,
            since_ts=lower_bound,
        ) if step_id else []
        payload = {
            "step_id": step_id,
            "subtask_id": stable_id,
            "subtask": trim(str(row.get("content", "") or ""), 800),
            "evidence": [
                (
                    str(record.get("id", "") or ""),
                    str(record.get("kind", "") or ""),
                    str(record.get("tool", "") or ""),
                    bool(record.get("ok", False)),
                    record.get("exit_code"),
                    str(record.get("path", "") or ""),
                    tuple(str(value or "") for value in (record.get("changed_files", []) or [])),
                    trim(str(record.get("summary", "") or ""), 500),
                )
                for record in candidates[-16:]
            ],
        }
        signature = hashlib.sha1(json_dumps(payload).encode("utf-8", "ignore")).hexdigest()[:20]
        return signature, candidates[-16:]

    def _cached_plan_subtask_semantic_review(
        self,
        plan_step: dict,
        row: dict,
        *,
        board: dict | None = None,
        subtask_id: str = "",
        since_ts: float = 0.0,
    ) -> tuple[dict, list[dict]]:
        bb = board if isinstance(board, dict) else self._ensure_blackboard()
        step_id = trim(str((plan_step or {}).get("id", "") or ""), 40)
        stable_id = trim(str(subtask_id or (row or {}).get("subtask_id", "") or ""), 80)
        if not stable_id and step_id and isinstance(row, dict):
            stable_id = self._stable_plan_worker_subtask_id(step_id, row)
        signature, candidates = self._plan_subtask_semantic_evidence_signature(
            plan_step,
            row,
            board=bb,
            subtask_id=stable_id,
            since_ts=since_ts,
        )
        all_reviews = bb.get("plan_subtask_semantic_reviews", {}) if isinstance(bb.get("plan_subtask_semantic_reviews"), dict) else {}
        step_reviews = all_reviews.get(step_id, {}) if isinstance(all_reviews.get(step_id), dict) else {}
        review = step_reviews.get(stable_id, {}) if isinstance(step_reviews.get(stable_id), dict) else {}
        if not review or str(review.get("evidence_signature", "") or "") != signature:
            return {}, candidates
        return dict(review), candidates

    def _record_plan_subtask_semantic_review(
        self,
        plan_step: dict,
        row: dict,
        review: dict,
        *,
        board: dict | None = None,
        subtask_id: str = "",
    ) -> None:
        if not isinstance(plan_step, dict) or not isinstance(row, dict) or not isinstance(review, dict):
            return
        bb = board if isinstance(board, dict) else self._ensure_blackboard()
        step_id = trim(str(plan_step.get("id", "") or ""), 40)
        stable_id = trim(str(subtask_id or row.get("subtask_id", "") or ""), 80)
        if not stable_id and step_id:
            stable_id = self._stable_plan_worker_subtask_id(step_id, row)
        if not step_id or not stable_id:
            return
        all_reviews = dict(bb.get("plan_subtask_semantic_reviews", {}) if isinstance(bb.get("plan_subtask_semantic_reviews"), dict) else {})
        step_reviews = dict(all_reviews.get(step_id, {}) if isinstance(all_reviews.get(step_id), dict) else {})
        step_reviews[stable_id] = dict(review)
        all_reviews[step_id] = step_reviews
        bb["plan_subtask_semantic_reviews"] = all_reviews
        bb["updated_at"] = float(now_ts())
        self.blackboard = bb

    def _llm_review_plan_subtask_completion(
        self,
        plan_step: dict,
        row: dict,
        *,
        board: dict | None = None,
        subtask_id: str = "",
        since_ts: float = 0.0,
    ) -> dict:
        """Use one cached LLM audit when deterministic evidence binding fails.

        The deterministic matcher remains the fast path.  This fallback runs
        only for an explicit completion request with passing, step-local tool
        evidence, so action verbs and path wording remain hints rather than a
        brittle source of permanent Todo deadlocks.
        """
        default = {
            "available": False,
            "passed": False,
            "decision": "verify",
            "confidence": "low",
            "reason": "semantic subtask review unavailable",
            "evidence": "",
            "evidence_ids": [],
            "source": "subtask-semantic-judge",
        }
        if (
            not isinstance(plan_step, dict)
            or not isinstance(row, dict)
            or self._is_plan_step_acceptance_subtask(row.get("content", ""))
        ):
            return default
        bb = board if isinstance(board, dict) else self._ensure_blackboard()
        stable_id = trim(str(subtask_id or row.get("subtask_id", "") or ""), 80)
        if not stable_id:
            stable_id = self._stable_plan_worker_subtask_id(
                trim(str(plan_step.get("id", "") or ""), 40),
                row,
            )
        cached, candidates = self._cached_plan_subtask_semantic_review(
            plan_step,
            row,
            board=bb,
            subtask_id=stable_id,
            since_ts=since_ts,
        )
        if cached:
            return cached
        signature, candidates = self._plan_subtask_semantic_evidence_signature(
            plan_step,
            row,
            board=bb,
            subtask_id=stable_id,
            since_ts=since_ts,
        )
        if not candidates:
            return default
        evidence_lines = [
            trim(
                f"ID={record.get('id', '')} kind={record.get('kind', '')} "
                f"tool={record.get('tool', '')} ok={record.get('ok')} exit={record.get('exit_code')} "
                f"path={record.get('path', '')} changed={record.get('changed_files', [])} "
                f"summary={record.get('summary', '')}",
                700,
            )
            for record in candidates
        ]
        review = dict(default)
        review["evidence_signature"] = signature
        review["subtask_id"] = stable_id
        try:
            prompt = (
                "A deterministic Todo evidence matcher could not decide whether one current subtask is complete. "
                "Audit the REAL step-local records semantically; action verbs, numbering, and exact path wording are hints, "
                "not the verdict. Decide pass only when the records concretely prove this subtask's intended result. "
                "Equivalent implementation/verification methods are allowed, but evidence for another subtask is not. "
                "Use verify when proof is insufficient and repair only when a real defect is shown. Never pass a claim without tool evidence.\n\n"
                f"PARENT STEP:\n{trim(str(plan_step.get('full_content', '') or plan_step.get('content', '') or ''), 1400)}\n\n"
                f"SUBTASK:\n{trim(str(row.get('content', '') or ''), 800)}\n\n"
                f"EVIDENCE RECORDS:\n{chr(10).join(evidence_lines)}\n\n"
                "Reply JSON only: {\"decision\":\"pass|verify|repair\",\"passed\":true|false,"
                "\"confidence\":\"high|medium|low\",\"reason\":\"...\",\"evidence\":\"...\","
                "\"evidence_ids\":[\"ID from records\"]}"
            )
            resp = self.ollama.chat(
                [{"role": "user", "content": prompt}],
                system=self._inject_runtime_environment_context(
                    "/no_think\nYou are a strict evidence-grounded subtask auditor. Reply only valid JSON."
                ),
                max_tokens=360,
                temperature=0.1,
                think=False,
            )
            raw = str(resp.get("content", "") or resp.get("text", "") or "").strip()
            payload = extract_json_object_from_text(raw, {})
            if isinstance(payload, dict) and "passed" in payload:
                confidence = str(payload.get("confidence", "low") or "low").strip().lower()
                if confidence not in {"high", "medium", "low"}:
                    confidence = "low"
                decision = str(payload.get("decision", "") or "").strip().lower()
                if decision not in {"pass", "verify", "repair"}:
                    decision = "pass" if bool(payload.get("passed", False)) else "verify"
                evidence_text = trim(str(payload.get("evidence", "") or ""), 500)
                valid_ids = {
                    str(record.get("id", "") or "")
                    for record in candidates
                    if record.get("id") and self._plan_evidence_record_passes(record)
                }
                cited_ids = [
                    trim(str(value or ""), 80)
                    for value in (payload.get("evidence_ids", []) if isinstance(payload.get("evidence_ids"), list) else [])
                    if trim(str(value or ""), 80) in valid_ids
                ]
                requested_pass = bool(
                    payload.get("passed", False)
                    and decision == "pass"
                    and confidence in {"high", "medium"}
                    and evidence_text
                )
                if requested_pass and not cited_ids:
                    cited_ids = [
                        str(record.get("id", "") or "")
                        for record in candidates
                        if record.get("id") and self._plan_evidence_record_passes(record)
                    ]
                passed = bool(requested_pass and cited_ids)
                review.update({
                    "available": True,
                    "passed": passed,
                    "decision": decision,
                    "confidence": confidence,
                    "reason": trim(str(payload.get("reason", "") or ""), 500),
                    "evidence": evidence_text,
                    "evidence_ids": cited_ids[-16:] if passed else [],
                    "raw": trim(raw, 1200),
                })
        except Exception as exc:
            review["reason"] = trim(f"semantic subtask review unavailable: {exc}", 300)
        review["ts"] = float(now_ts())
        self._record_plan_subtask_semantic_review(
            plan_step,
            row,
            review,
            board=bb,
            subtask_id=stable_id,
        )
        return review

    def _plan_subtask_semantic_completion_records(
        self,
        plan_step: dict,
        row: dict,
        *,
        board: dict | None = None,
        subtask_id: str = "",
        since_ts: float = 0.0,
    ) -> list[dict]:
        review, candidates = self._cached_plan_subtask_semantic_review(
            plan_step,
            row,
            board=board,
            subtask_id=subtask_id,
            since_ts=since_ts,
        )
        if not (
            review.get("available")
            and review.get("passed")
            and str(review.get("confidence", "") or "").lower() in {"high", "medium"}
        ):
            return []
        evidence_ids = {str(value or "") for value in (review.get("evidence_ids", []) or []) if str(value or "")}
        return [
            record for record in candidates
            if str(record.get("id", "") or "") in evidence_ids
            and self._plan_evidence_record_passes(record)
        ]

    def _plan_subtask_completion_audit_warning(
        self,
        plan_step: dict,
        row: dict,
        *,
        board: dict | None = None,
        subtask_id: str = "",
        since_ts: float = 0.0,
    ) -> str:
        label = trim(str((row or {}).get("content", "") or ""), 120)
        review, _candidates = self._cached_plan_subtask_semantic_review(
            plan_step,
            row,
            board=board,
            subtask_id=subtask_id,
            since_ts=since_ts,
        )
        if not review.get("available"):
            return label
        decision = trim(str(review.get("decision", "verify") or "verify"), 16)
        reason = trim(str(review.get("reason", "") or ""), 120)
        return trim(
            f"{label} [LLM audit={decision}{(': ' + reason) if reason else ''}]",
            260,
        )

    def _plan_worker_completion_has_evidence(
        self,
        plan_step: dict,
        row: dict,
        *,
        board: dict | None = None,
        subtask_id: str = "",
        since_ts: float = 0.0,
        evidence: object = None,
    ) -> bool:
        """Audit a requested completion using the row's own semantic type."""
        if not isinstance(plan_step, dict) or not isinstance(row, dict):
            return False
        candidate = dict(row)
        candidate["status"] = "completed"
        if subtask_id:
            candidate["subtask_id"] = subtask_id
        if self._is_plan_step_acceptance_subtask(candidate.get("content", "")):
            return self._plan_worker_completed_status_has_evidence(
                candidate,
                plan_step,
                board,
                allow_acceptance_semantic_review=True,
                actor=str(candidate.get("completed_by", "") or self._current_plan_worker_owner(board)),
            )
        if self._plan_subtask_has_accumulated_evidence(
            plan_step,
            candidate.get("content", ""),
            board=board,
            subtask_id=subtask_id,
            since_ts=since_ts,
            evidence=evidence,
        ):
            return True
        review = self._llm_review_plan_subtask_completion(
            plan_step,
            candidate,
            board=board,
            subtask_id=subtask_id,
            since_ts=since_ts,
        )
        return bool(
            review.get("available")
            and review.get("passed")
            and str(review.get("confidence", "") or "").lower() in {"high", "medium"}
        )

    def _plan_worker_completion_evidence_records(
        self,
        plan_step: dict,
        row: dict,
        *,
        board: dict | None = None,
        subtask_id: str = "",
        since_ts: float = 0.0,
        evidence: object = None,
    ) -> list[dict]:
        """Return the exact records that justified one accepted completion."""
        if not isinstance(plan_step, dict) or not isinstance(row, dict):
            return []
        if self._is_plan_step_acceptance_subtask(row.get("content", "")):
            records = self._matching_acceptance_evidence_records(
                plan_step,
                row,
                board=board,
                expected=self._acceptance_expected_evidence(
                    self._effective_plan_step_acceptance_text(
                        plan_step,
                        row.get("content", ""),
                    )
                ),
            )
            if records:
                return records
            return self._trusted_plan_step_acceptance_records(
                plan_step,
                row,
                board=board,
                since_ts=since_ts,
            )
        records = self._plan_subtask_evidence_records(
            plan_step,
            row.get("content", ""),
            board=board,
            subtask_id=subtask_id,
            since_ts=since_ts,
            evidence=evidence,
        )
        if records:
            return records
        return self._plan_subtask_semantic_completion_records(
            plan_step,
            row,
            board=board,
            subtask_id=subtask_id,
            since_ts=since_ts,
        )

    def _record_plan_subtask_evidence_binding(
        self,
        plan_step: dict,
        row: dict,
        records: list[dict],
        *,
        source: str,
        actor: str,
        board: dict | None = None,
    ) -> dict:
        """Persist the runtime's evidence decision beyond the rolling ledger window."""
        if not isinstance(plan_step, dict) or not isinstance(row, dict):
            return {}
        step_id = trim(str(plan_step.get("id", "") or ""), 40)
        subtask_id = self._stable_plan_worker_subtask_id(step_id, row)
        passing = [
            dict(record)
            for record in (records or [])
            if isinstance(record, dict)
            and self._plan_evidence_record_passes(record)
            and (not record.get("step_id") or str(record.get("step_id", "") or "") == step_id)
        ]
        evidence_ids = [trim(str(record.get("id", "") or ""), 80) for record in passing if record.get("id")]
        if not step_id or not subtask_id or not evidence_ids:
            return {}
        latest = passing[-1]
        binding = {
            "subtask_id": subtask_id,
            "content_core": self._plan_worker_content_core(row.get("content", "")),
            "source": trim(str(source or "direct"), 40),
            "actor": trim(str(actor or "developer"), 40),
            "evidence_ids": evidence_ids[-12:],
            "evidence": trim(
                f"{latest.get('tool', 'tool')}: {latest.get('summary', '')}",
                300,
            ),
            "ts": float(now_ts()),
        }
        bb = board if isinstance(board, dict) else self._ensure_blackboard()
        all_bindings = dict(
            bb.get("plan_subtask_evidence_bindings", {})
            if isinstance(bb.get("plan_subtask_evidence_bindings"), dict)
            else {}
        )
        step_bindings = dict(all_bindings.get(step_id, {}) if isinstance(all_bindings.get(step_id), dict) else {})
        step_bindings[subtask_id] = binding
        all_bindings[step_id] = step_bindings
        bb["plan_subtask_evidence_bindings"] = all_bindings
        bb["updated_at"] = float(now_ts())
        self.blackboard = bb
        return binding

    def _clear_plan_subtask_evidence_binding(
        self,
        step_id: object,
        subtask_id: object,
        *,
        board: dict | None = None,
    ) -> bool:
        step_key = trim(str(step_id or ""), 40)
        subtask_key = trim(str(subtask_id or ""), 80)
        bb = board if isinstance(board, dict) else self._ensure_blackboard()
        all_bindings = dict(
            bb.get("plan_subtask_evidence_bindings", {})
            if isinstance(bb.get("plan_subtask_evidence_bindings"), dict)
            else {}
        )
        step_bindings = dict(all_bindings.get(step_key, {}) if isinstance(all_bindings.get(step_key), dict) else {})
        if not step_key or not subtask_key or subtask_key not in step_bindings:
            return False
        step_bindings.pop(subtask_key, None)
        if step_bindings:
            all_bindings[step_key] = step_bindings
        else:
            all_bindings.pop(step_key, None)
        bb["plan_subtask_evidence_bindings"] = all_bindings
        bb["updated_at"] = float(now_ts())
        self.blackboard = bb
        return True

    def _bind_tool_result_to_plan_subtask(self, item: dict, snapshot: dict | None) -> dict:
        if not isinstance(item, dict) or not isinstance(snapshot, dict):
            return item
        step_id = trim(str(snapshot.get("step_id", "") or ""), 40)
        subtask_id = trim(str(snapshot.get("subtask_id", "") or ""), 80)
        subtask_content = trim(str(snapshot.get("subtask_content", "") or ""), 500)
        if step_id:
            item["plan_step_id"] = step_id
        if subtask_id:
            item["plan_subtask_id"] = subtask_id
        if subtask_content:
            item["plan_subtask_content"] = subtask_content
        return item

    def _plan_worker_todo_rows_from_blackboard(self, step_id: str, role: str = "", board: dict | None = None) -> list[dict]:
        step_key = trim(str(step_id or "").strip(), 40)
        if not step_key:
            return []
        bb = board if isinstance(board, dict) else (self.blackboard if isinstance(getattr(self, "blackboard", None), dict) else {})
        mirror = bb.get("plan_worker_todos", {}) if isinstance(bb.get("plan_worker_todos"), dict) else {}
        raw_rows = mirror.get(step_key, []) if isinstance(mirror.get(step_key), list) else []
        plan_step = self._get_plan_step_by_id(step_key, bb)
        role_key = self._sanitize_agent_role(role)
        rows: list[dict] = []
        for row in raw_rows:
            if not isinstance(row, dict):
                continue
            owner = self._sanitize_agent_role(row.get("owner", "")) or "developer"
            if role_key and owner != role_key:
                continue
            raw_content = str(row.get("content", "") or "").strip()
            parsed_status, parsed_content = split_todo_status_text(raw_content)
            content = trim(normalize_work_text(parsed_content or raw_content) or (parsed_content or raw_content), 360)
            if not content:
                continue
            raw_status = str(row.get("status", "") or "").strip().lower().replace("-", "_").replace(" ", "_")
            status = self._normalize_todo_status_value(row.get("status", ""), parsed_status or "pending")
            if parsed_status and raw_status in {"", "todo", "pending"}:
                status = parsed_status
            if status == "blocked":
                status = "pending"
            item = {
                "content": content,
                "status": status,
                "owner": owner,
                "parent_step_id": step_key,
                "created_at": float(row.get("created_at", 0.0) or 0.0),
                "updated_at": float(row.get("updated_at", 0.0) or 0.0),
                "started_at": float(row.get("started_at", 0.0) or 0.0),
                "completed_at": float(row.get("completed_at", 0.0) or 0.0) if row.get("completed_at") else None,
                "completed_by": trim(str(row.get("completed_by", "") or ""), 40),
                "evidence": trim(str(row.get("evidence", "") or ""), 300),
            }
            external_subtask_id = trim(
                str(row.get("external_subtask_id", "") or "").strip(),
                120,
            )
            supplied_subtask_id = trim(str(row.get("subtask_id", "") or "").strip(), 100)
            if supplied_subtask_id and not self._is_canonical_plan_worker_subtask_id(
                supplied_subtask_id,
                step_key,
            ):
                external_subtask_id = external_subtask_id or supplied_subtask_id
            if external_subtask_id:
                item["external_subtask_id"] = external_subtask_id
            row_key = trim(str(row.get("key", "") or "").strip(), 120)
            if row_key and not row_key.startswith("bb:"):
                item["key"] = row_key
            item["subtask_id"] = self._stable_plan_worker_subtask_id(step_key, row)
            if (
                item["status"] == "completed"
                and isinstance(plan_step, dict)
                and not self._plan_worker_completed_status_has_evidence(item, plan_step, bb)
            ):
                item["status"] = "pending"
                item["completed_at"] = None
                item["completed_by"] = ""
                item["evidence"] = ""
            rows.append(item)
        rows = self._filter_parent_step_duplicate_worker_rows(rows, plan_step, bb)
        rows = self._dedupe_plan_worker_rows(rows, step_key)
        if role_key and not rows:
            return self._plan_worker_todo_rows_from_blackboard(step_key, role="", board=bb)
        rows.sort(key=self._plan_worker_todo_sort_key)
        return rows

    def _sync_plan_worker_todos_to_blackboard(
        self,
        step_id: str = "",
        *,
        rows: list[dict] | None = None,
        board: dict | None = None,
        transaction: dict | None = None,
    ) -> bool:
        bb = board if isinstance(board, dict) else self._ensure_blackboard()
        if transaction is not None:
            valid, stale_reason = self._todo_write_transaction_is_current(
                transaction,
                board=bb,
            )
            if not valid:
                self._emit_stale_todo_write_discarded(stale_reason)
                return False
        self._migrate_plan_worker_todo_partitions(bb)
        if transaction is not None:
            valid, stale_reason = self._todo_write_transaction_is_current(
                transaction,
                board=self._ensure_blackboard(),
            )
            if not valid:
                self._emit_stale_todo_write_discarded(stale_reason)
                return False
        mirror = dict(bb.get("plan_worker_todos", {}) if isinstance(bb.get("plan_worker_todos"), dict) else {})
        changed = False
        worker_owners = {"developer", "explorer", "reviewer"}
        step_filter = self._canonical_plan_worker_parent_id(step_id, board=bb) or trim(str(step_id or "").strip(), 40)
        src_rows = rows if isinstance(rows, list) else self.todo.snapshot()
        grouped: dict[str, list[dict]] = {}
        plan_step_cache: dict[str, dict | None] = {}
        for parent, raw_mirror_rows in list(mirror.items()):
            parent_key = trim(str(parent or "").strip(), 40)
            plan_step_cache[parent_key] = self._get_plan_step_by_id(parent_key, bb)
            if not parent_key or plan_step_cache[parent_key] is None:
                mirror.pop(parent, None)
                changed = True
                continue
            existing_rows = raw_mirror_rows if isinstance(raw_mirror_rows, list) else []
            clean_existing = self._filter_parent_step_duplicate_worker_rows(
                existing_rows,
                plan_step_cache[parent_key],
                bb,
            )
            protected_existing: list[dict] = []
            for existing_row in clean_existing:
                normalized_existing = dict(existing_row)
                if (
                    self._normalize_todo_status_value(normalized_existing.get("status", ""), "pending") == "completed"
                    and not self._plan_worker_completed_status_has_evidence(
                        normalized_existing,
                        plan_step_cache[parent_key],
                        bb,
                    )
                ):
                    normalized_existing["status"] = "pending"
                    normalized_existing["completed_at"] = None
                    normalized_existing["completed_by"] = ""
                    normalized_existing["evidence"] = ""
                protected_existing.append(normalized_existing)
            clean_existing = protected_existing
            if clean_existing != existing_rows or parent_key != parent:
                mirror.pop(parent, None)
                if clean_existing:
                    mirror[parent_key] = clean_existing
                changed = True
        for raw in src_rows:
            if not isinstance(raw, dict):
                continue
            owner = self._sanitize_agent_role(raw.get("owner", "")) or ""
            raw_parent = trim(str(raw.get("parent_step_id", "") or "").strip(), 40)
            parent = self._canonical_plan_worker_parent_id(raw_parent, rows=[raw], board=bb) or raw_parent
            if owner not in worker_owners or not parent:
                continue
            if step_filter and parent != step_filter:
                continue
            if parent not in plan_step_cache:
                plan_step_cache[parent] = self._get_plan_step_by_id(parent, bb)
            if plan_step_cache[parent] is None:
                continue
            raw_content = str(raw.get("content", "") or "").strip()
            parsed_status, parsed_content = split_todo_status_text(raw_content)
            content = trim(normalize_work_text(parsed_content or raw_content) or (parsed_content or raw_content), 360)
            if not content:
                continue
            raw_status = str(raw.get("status", "") or "").strip().lower().replace("-", "_").replace(" ", "_")
            status = self._normalize_todo_status_value(raw.get("status", ""), parsed_status or "pending")
            if parsed_status and raw_status in {"", "todo", "pending"}:
                status = parsed_status
            if status == "blocked":
                status = "pending"
            if self._plan_worker_row_duplicates_parent_step(
                {"content": content, "parent_step_id": parent, "owner": owner},
                plan_step_cache.get(parent),
            ):
                continue
            item = {
                "content": content,
                "status": status,
                "owner": owner,
                "parent_step_id": parent,
                "created_at": float(raw.get("created_at", 0.0) or 0.0),
                "updated_at": float(raw.get("updated_at", 0.0) or 0.0),
                "started_at": float(raw.get("started_at", 0.0) or 0.0),
                "completed_at": float(raw.get("completed_at", 0.0) or 0.0) if raw.get("completed_at") else None,
                "completed_by": trim(str(raw.get("completed_by", "") or ""), 40),
                "evidence": trim(str(raw.get("evidence", "") or ""), 300),
            }
            external_subtask_id = trim(
                str(raw.get("external_subtask_id", "") or "").strip(),
                120,
            )
            supplied_subtask_id = trim(str(raw.get("subtask_id", "") or "").strip(), 100)
            if supplied_subtask_id and not self._is_canonical_plan_worker_subtask_id(
                supplied_subtask_id,
                parent,
            ):
                external_subtask_id = external_subtask_id or supplied_subtask_id
            if external_subtask_id:
                item["external_subtask_id"] = external_subtask_id
            row_key = trim(str(raw.get("key", "") or "").strip(), 120)
            if row_key and not row_key.startswith("bb:"):
                item["key"] = row_key
            item["subtask_id"] = self._stable_plan_worker_subtask_id(parent, raw)
            if (
                item["status"] == "completed"
                and not self._plan_worker_completed_status_has_evidence(item, plan_step_cache.get(parent), bb)
            ):
                item["status"] = "pending"
                item["completed_at"] = None
                item["completed_by"] = ""
                item["evidence"] = ""
            grouped.setdefault(parent, []).append(item)
        target_steps = {step_filter} if step_filter else set(grouped.keys())
        if not step_filter:
            target_steps.update(
                trim(str(row.get("parent_step_id", "") or "").strip(), 40)
                for row in src_rows
                if isinstance(row, dict)
                and self._sanitize_agent_role(row.get("owner", "")) in worker_owners
                and str(row.get("parent_step_id", "") or "").strip()
            )
        for parent in sorted(x for x in target_steps if x):
            clean_rows = grouped.get(parent, [])
            if parent not in plan_step_cache:
                plan_step_cache[parent] = self._get_plan_step_by_id(parent, bb)
            clean_rows = self._filter_parent_step_duplicate_worker_rows(
                clean_rows,
                plan_step_cache.get(parent),
                bb,
            )
            clean_rows = self._dedupe_plan_worker_rows(clean_rows, parent)
            clean_rows.sort(key=self._plan_worker_todo_sort_key)
            if clean_rows:
                if mirror.get(parent) != clean_rows:
                    mirror[parent] = clean_rows
                    changed = True
            elif parent in mirror:
                mirror.pop(parent, None)
                changed = True
        if changed:
            if transaction is not None:
                valid, stale_reason = self._todo_write_transaction_is_current(
                    transaction,
                    board=self._ensure_blackboard(),
                )
                if not valid:
                    self._emit_stale_todo_write_discarded(stale_reason)
                    return False
            bb["plan_worker_todos"] = mirror
            bb["updated_at"] = float(now_ts())
            self.blackboard = bb
        return changed

    def _reconcile_plan_worker_todos_with_blackboard(
        self,
        step_id: str,
        *,
        board: dict | None = None,
    ) -> bool:
        step_key = trim(str(step_id or "").strip(), 20)
        if not step_key:
            return False
        bb = board if isinstance(board, dict) else self._ensure_blackboard()
        mirror_rows = self._plan_worker_todo_rows_from_blackboard(step_key, role="", board=bb)
        worker_owners = {"developer", "explorer", "reviewer"}
        plan_step = self._get_plan_step_by_id(step_key, bb)
        memory_rows = [
            dict(row) for row in self.todo.snapshot()
            if isinstance(row, dict)
            and str(row.get("owner", "") or "").strip().lower() in worker_owners
            and trim(str(row.get("parent_step_id", "") or "").strip(), 20) == step_key
        ]
        memory_rows = self._filter_parent_step_duplicate_worker_rows(memory_rows, plan_step, bb)
        if not mirror_rows:
            mirror = bb.get("plan_worker_todos", {}) if isinstance(bb.get("plan_worker_todos"), dict) else {}
            raw_mirror = mirror.get(step_key, []) if isinstance(mirror.get(step_key), list) else []
            if raw_mirror or memory_rows:
                return self._sync_plan_worker_todos_to_blackboard(step_key, rows=memory_rows, board=bb)
            return False
        # Merge the two persistence views before restoring them.  The blackboard
        # mirror and TodoManager are written by different event paths and one can
        # legitimately lag the other by a turn.  Restore is monotonic: a completed
        # row (and its evidence) can never be downgraded by an older pending or
        # in_progress snapshot.  This keeps sync from visually moving a finished
        # child back to the first open child after a manager handoff.
        status_rank = {"pending": 1, "in_progress": 2, "completed": 3}
        merged_by_id: dict[str, dict] = {}
        merged_order: list[str] = []
        for source_row in mirror_rows + memory_rows:
            row = dict(source_row)
            identity = self._stable_plan_worker_subtask_id(step_key, row)
            if not identity:
                continue
            row["subtask_id"] = identity
            row["parent_step_id"] = step_key
            if (
                self._normalize_todo_status_value(row.get("status", ""), "pending") == "completed"
                and not self._plan_worker_completed_status_has_evidence(row, plan_step, bb)
            ):
                row["status"] = "pending"
                row["completed_at"] = None
                row["completed_by"] = ""
                row["evidence"] = ""
            prior = merged_by_id.get(identity)
            if prior is None:
                merged_by_id[identity] = row
                merged_order.append(identity)
                continue
            prior_status = self._normalize_todo_status_value(prior.get("status", ""), "pending")
            incoming_status = self._normalize_todo_status_value(row.get("status", ""), "pending")
            if status_rank.get(incoming_status, 0) >= status_rank.get(prior_status, 0):
                winner, loser = row, prior
            else:
                winner, loser = prior, row
            combined = dict(loser)
            combined.update(winner)
            # Preserve completion metadata even if the winning copy is an old
            # serialized row without its optional fields.
            for field in ("completed_at", "completed_by", "evidence", "created_at", "started_at"):
                if combined.get(field) in (None, "", 0, 0.0):
                    value = prior.get(field, row.get(field))
                    if value not in (None, "", 0, 0.0):
                        combined[field] = value
            combined["status"] = "completed" if max(
                status_rank.get(prior_status, 0), status_rank.get(incoming_status, 0)
            ) >= status_rank["completed"] else self._normalize_todo_status_value(
                winner.get("status", ""), "pending"
            )
            combined["parent_step_id"] = step_key
            combined["subtask_id"] = identity
            if (
                self._normalize_todo_status_value(combined.get("status", ""), "pending") == "completed"
                and not self._plan_worker_completed_status_has_evidence(combined, plan_step, bb)
            ):
                # A completed bit from one persistence view is not proof by
                # itself.  Downgrade only the unproven row; keep its identity
                # and content so the active child remains resumable.
                combined["status"] = "pending"
                combined["completed_at"] = None
                combined["completed_by"] = ""
                combined["evidence"] = ""
            merged_by_id[identity] = combined
        restore_rows = [merged_by_id[key] for key in merged_order if key in merged_by_id]
        if not restore_rows:
            return False
        before = [
            (
                self._plan_worker_todo_identity(row),
                str(row.get("status", "") or "").strip().lower(),
                str(row.get("owner", "") or "").strip().lower(),
                trim(str(row.get("parent_step_id", "") or "").strip(), 20),
            )
            for row in memory_rows
        ]
        role_key = self._current_plan_worker_owner(bb)
        self._merge_plan_worker_todo_items(
            restore_rows,
            role=role_key,
            trusted_restore=True,
        )
        after_rows = [
            dict(row) for row in self.todo.snapshot()
            if isinstance(row, dict)
            and str(row.get("owner", "") or "").strip().lower() in worker_owners
            and trim(str(row.get("parent_step_id", "") or "").strip(), 20) == step_key
        ]
        after_rows = self._filter_parent_step_duplicate_worker_rows(after_rows, plan_step, bb)
        after = [
            (
                self._plan_worker_todo_identity(row),
                str(row.get("status", "") or "").strip().lower(),
                str(row.get("owner", "") or "").strip().lower(),
                trim(str(row.get("parent_step_id", "") or "").strip(), 20),
            )
            for row in after_rows
        ]
        return before != after

    def _active_plan_step_has_worker_todos(self, role: str = "") -> bool:
        step = self._get_active_plan_step()
        if not isinstance(step, dict):
            return False
        step_id = str(step.get("id", "") or "").strip()
        if not step_id:
            return False
        return bool(self._active_plan_worker_todo_rows(step_id, role=role))

    def _bridge_flat_todos_to_active_plan_step(
        self,
        rows: list[dict] | None,
        board: dict | None = None,
    ) -> tuple[list[dict], bool]:
        bb = board if isinstance(board, dict) else self._ensure_blackboard()
        step = self._get_active_plan_step(bb)
        if not isinstance(step, dict):
            return (list(rows or []), False)
        step_id = trim(str(step.get("id", "") or ""), 20)
        if not step_id:
            return (list(rows or []), False)
        snap = [dict(row) for row in (rows or []) if isinstance(row, dict)]
        if not snap:
            return (snap, False)
        worker_owners = {"developer", "explorer", "reviewer"}
        if any(str(row.get("parent_step_id", "") or "").strip() for row in snap):
            return (snap, False)
        if any(
            str(row.get("owner", "") or "").strip().lower() in worker_owners
            and str(row.get("parent_step_id", "") or "").strip() == step_id
            for row in snap
        ):
            return (snap, False)
        owner_key = self._current_plan_worker_owner(bb)
        bridged: list[dict] = []
        migrated = False
        for row in snap:
            key = trim(str(row.get("key", "") or "").strip(), 120)
            if key.startswith("bb:"):
                bridged.append(dict(row))
                continue
            content = normalize_work_text(str(row.get("content", "") or "")) or str(row.get("content", "") or "").strip()
            if not content:
                continue
            new_row = dict(row)
            new_row["content"] = content
            new_row["parent_step_id"] = step_id
            owner = str(new_row.get("owner", "") or "").strip().lower()
            if owner not in worker_owners:
                new_row["owner"] = owner_key
            bridged.append(new_row)
            migrated = True
        return (bridged, migrated)

    def _active_plan_progress_snapshot(self, board: dict | None = None) -> dict:
        bb = board if isinstance(board, dict) else self._ensure_blackboard()
        step = self._current_plan_step_row(bb)
        if not isinstance(step, dict):
            return {
                "step_id": "",
                "step_index": 0,
                "step_text": "",
                "expected_count": 0,
                "worker_todo_count": 0,
                "completed_count": 0,
                "in_progress_count": 0,
                "pending_count": 0,
                "current_subtask": "",
                "next_pending_subtask": "",
                "owners": [],
            }
        step_id = trim(str(step.get("id", "") or ""), 20)
        rows = self._active_plan_worker_todo_rows(step_id, role="") if step_id else []
        expected = self._extract_plan_step_subtasks(step, limit=6)
        completed_count = 0
        in_progress_count = 0
        pending_count = 0
        current_subtask = ""
        next_pending_subtask = ""
        owners: set[str] = set()
        for row in rows:
            status = str(row.get("status", "pending") or "pending").strip().lower()
            content = trim(str(row.get("content", "") or "").strip(), 220)
            owner = self._sanitize_agent_role(row.get("owner", ""))
            if owner:
                owners.add(owner)
            if status == "completed":
                completed_count += 1
            elif status == "in_progress":
                in_progress_count += 1
                if content and not current_subtask:
                    current_subtask = content
            else:
                pending_count += 1
                if content and not next_pending_subtask:
                    next_pending_subtask = content
        return {
            "step_id": step_id,
            "step_index": max(0, int(step.get("plan_step_index", 0) or 0)),
            "step_text": self._current_plan_step_text(bb),
            "expected_count": len(expected),
            "worker_todo_count": len(rows),
            "completed_count": completed_count,
            "in_progress_count": in_progress_count,
            "pending_count": pending_count,
            "current_subtask": current_subtask,
            "next_pending_subtask": next_pending_subtask,
            "owners": sorted(owners),
        }

    def _manager_worker_progress_capsule(self, role: str, step: dict, board: dict | None = None) -> str:
        bb = board if isinstance(board, dict) else self._ensure_blackboard()
        role_key = self._sanitize_agent_role(role) or "developer"
        safe_step = step if isinstance(step, dict) else {}
        snapshot = self._active_plan_progress_snapshot(bb)
        tool_results = safe_step.get("tool_results", []) or []
        tool_names: list[str] = []
        for item in tool_results:
            if not isinstance(item, dict):
                continue
            name = str(item.get("name", "") or "").strip()
            if not name or name in tool_names:
                continue
            tool_names.append(name)
            if len(tool_names) >= 5:
                break
        parts = [
            f"[worker-progress] owner={role_key}",
            f"status={trim(str(safe_step.get('status', '') or ''), 40) or '-'}",
        ]
        if tool_names:
            parts.append("tools=" + ",".join(tool_names))
        step_text = trim(str(snapshot.get("step_text", "") or ""), 180)
        if step_text:
            parts.append(f"step={step_text}")
        todo_state = (
            f"todos={int(snapshot.get('completed_count', 0) or 0)}/"
            f"{int(snapshot.get('in_progress_count', 0) or 0)}/"
            f"{int(snapshot.get('pending_count', 0) or 0)}"
        )
        if int(snapshot.get("worker_todo_count", 0) or 0) > 0:
            parts.append(todo_state)
        focus = trim(str(snapshot.get("current_subtask", "") or ""), 160)
        if focus:
            parts.append(f"focus={focus}")
        elif str(snapshot.get("next_pending_subtask", "") or "").strip():
            parts.append(f"next={trim(str(snapshot.get('next_pending_subtask', '') or ''), 160)}")
        current_step = self._current_plan_step_row(bb)
        if isinstance(current_step, dict):
            evidence = self._collect_blackboard_step_evidence(current_step, bb)
            if evidence:
                parts.append(f"evidence={trim(evidence, 180)}")
            if self._step_subtasks_all_completed(current_step) and self._plan_step_acceptance_gate_passed(current_step, None, bb):
                parts.append("acceptance=ready")
        reply = bb.get("last_worker_reply", {}) if isinstance(bb.get("last_worker_reply"), dict) else {}
        if self._sanitize_agent_role(reply.get("role", "")) == role_key:
            reply_text = trim(str(reply.get("text", "") or "").strip(), 180)
            if reply_text:
                parts.append(f"reply={reply_text}")
        return trim(" | ".join(parts), 1600)

    def _manager_recovery_route_for_repeated_delegate(self, route: dict, board: dict | None = None) -> dict:
        bb = board if isinstance(board, dict) else self._ensure_blackboard()
        row = dict(route or {})
        step = self._current_plan_step_row(bb)
        if not isinstance(step, dict):
            row["target"] = "developer"
            row["instruction"] = (
                "Recovery routing after repeated identical delegation. "
                "Continue the current objective with one concrete tool action and write observable progress."
            )
            row["reason"] = trim(f"{row.get('reason', '')}|loop-recovery-no-plan-step", 600)
            row["source"] = "loop-recovery"
            row["is_mandatory"] = True
            return row
        snapshot = self._active_plan_progress_snapshot(bb)
        step_text = trim(str(snapshot.get("step_text", "") or ""), 220)
        current_subtask = trim(str(snapshot.get("current_subtask", "") or ""), 180)
        next_pending = trim(str(snapshot.get("next_pending_subtask", "") or ""), 180)
        subtasks_done = self._step_subtasks_all_completed(step)
        has_evidence = self._plan_step_has_blackboard_evidence(step, bb)
        profile = self._ensure_blackboard_task_profile(bb)
        if subtasks_done and has_evidence:
            owner = self._sanitize_agent_role(row.get("target", "")) or self._current_plan_worker_owner(bb)
            if owner not in AGENT_ROLES:
                owner = self._sanitize_agent_role(profile.get("assigned_expert", "")) or "developer"
            row["target"] = owner
            row["instruction"] = trim(
                (
                    "Recovery routing after repeated identical delegation. "
                    f"Validate ONLY the current plan step: {step_text}. "
                    "Worker subtasks are complete and blackboard evidence already exists. "
                    "Run acceptance for this step only, record pass/fix with concrete evidence, and do not jump ahead."
                ),
                1200,
            )
            row["reason"] = trim(f"{row.get('reason', '')}|loop-recovery-acceptance", 600)
            row["source"] = "loop-recovery"
            row["is_mandatory"] = True
            return row
        owner = self._sanitize_agent_role(row.get("target", "")) or self._current_plan_worker_owner(bb)
        if owner not in AGENT_ROLES:
            owner = self._sanitize_agent_role(profile.get("assigned_expert", "")) or "developer"
        if current_subtask:
            action_text = f"Continue ONLY the current in_progress subtask: {current_subtask}."
        elif next_pending:
            action_text = f"Resume the next pending subtask: {next_pending}."
        else:
            action_text = "Continue the current plan step with one concrete tool action."
        evidence_text = ""
        if has_evidence:
            evidence_text = (
                " Blackboard already contains partial evidence for this step; build on that work instead of restarting."
            )
        progress_instruction = (
            "Tool results are evidence, not ordinary work-status commands. After a real subtask boundary, use TodoWrite update_mode='status_update' before starting work from another row; one call may update every evidence-backed completed row and select exactly one remaining row as in_progress."
            if not self._is_multi_agent_mode()
            else "After the subtask is finished, immediately call TodoWrite to mark it completed and move the next subtask to in_progress."
        )
        row["target"] = owner
        row["instruction"] = trim(
            (
                "Recovery routing after repeated identical delegation. "
                f"Stay on the current plan step: {step_text}. "
                f"{action_text} "
                "Do not branch to a different step or restate the whole plan. "
                f"{progress_instruction}"
                f"{evidence_text}"
            ),
            1200,
        )
        row["reason"] = trim(f"{row.get('reason', '')}|loop-recovery-execute", 600)
        row["source"] = "loop-recovery"
        row["is_mandatory"] = True
        return row

    def _todo_has_plan_steps(self, board: dict | None = None) -> bool:
        bb = board if isinstance(board, dict) else self._ensure_blackboard()
        todos = bb.get("project_todos", []) if isinstance(bb.get("project_todos"), list) else []
        return any(
            isinstance(todo, dict) and todo.get("category") == "plan_step"
            for todo in todos
        )

    def _todo_worker_role_hint(self, role: str = "", board: dict | None = None) -> str:
        role_key = self._sanitize_agent_role(role)
        if role_key in {"developer", "explorer", "reviewer"}:
            return role_key
        return self._current_plan_worker_owner(board)

    def _todo_route_kind(self, role: str = "", board: dict | None = None) -> str:
        bb = board if isinstance(board, dict) else self._ensure_blackboard()
        if self._todo_has_plan_steps(bb):
            return "plan_sync" if self._is_multi_agent_mode() else "plan_single"
        role_key = self._todo_worker_role_hint(role, bb)
        if self._is_multi_agent_mode() and role_key in {"developer", "explorer", "reviewer"}:
            return "pure_sync"
        return "pure_single"

    def _todo_row_kind(self, row: dict | None) -> str:
        if not isinstance(row, dict):
            return ""
        key = str(row.get("key", "") or "").strip()
        if key.startswith("bb:"):
            return "system"
        owner = str(row.get("owner", "") or "").strip().lower()
        parent_step_id = str(row.get("parent_step_id", "") or "").strip()
        if owner in {"developer", "explorer", "reviewer"} and parent_step_id:
            return "plan_worker"
        if owner in {"developer", "explorer", "reviewer"}:
            return "owner_worker"
        return "flat"

    def _normalize_todo_status_value(self, value: object, default: str = "pending") -> str:
        raw = str(value or "").strip().lower().replace("-", "_").replace(" ", "_")
        aliases = {
            "todo": "pending",
            "open": "pending",
            "not_started": "pending",
            "notstarted": "pending",
            "待处理": "pending",
            "待處理": "pending",
            "未开始": "pending",
            "未開始": "pending",
            "[_]": "pending",
            "[]": "pending",
            "[ ]": "pending",
            "doing": "in_progress",
            "working": "in_progress",
            "active": "in_progress",
            "started": "in_progress",
            "进行中": "in_progress",
            "進行中": "in_progress",
            "处理中": "in_progress",
            "處理中": "in_progress",
            "inprogress": "in_progress",
            "in_progress": "in_progress",
            "[>]": "in_progress",
            ">": "in_progress",
            "done": "completed",
            "complete": "completed",
            "success": "completed",
            "succeeded": "completed",
            "passed": "completed",
            "完成": "completed",
            "已完成": "completed",
            "finish": "completed",
            "finished": "completed",
            "[x]": "completed",
            "x": "completed",
        }
        status = aliases.get(raw, raw or default)
        if status in {"pending", "in_progress", "completed", "blocked"}:
            return status
        return default

    def _normalize_plan_worker_todo_input(
        self,
        item: object,
        *,
        step_id: str,
        role_key: str,
        default_status: str = "pending",
    ) -> dict:
        worker_owners = {"developer", "explorer", "reviewer"}
        step_key = trim(str(step_id or "").strip(), 40)
        owner_hint = self._sanitize_agent_role(role_key) or self._current_plan_worker_owner()
        if isinstance(item, str):
            raw: dict = {"content": item}
        elif isinstance(item, dict):
            raw = dict(item)
        else:
            raw = {"content": str(item or "").strip()}
        key = trim(str(raw.get("key", "") or "").strip(), 120)
        if key.startswith("bb:"):
            return raw
        raw_content = str(
            raw.get(
                "content",
                raw.get(
                        "text",
                        raw.get(
                            "title",
                            raw.get(
                                "task",
                                raw.get("description", raw.get("label", raw.get("name", raw.get("summary", "")))),
                            ),
                        ),
                ),
            )
            or ""
        ).strip()
        parsed_status, parsed_content = split_todo_status_text(raw_content)
        content = normalize_work_text(parsed_content or raw_content) or (parsed_content or raw_content)
        content = trim(str(content or "").strip(), 500)
        if not content:
            return {}
        # Accept provider-specific aliases without changing the canonical row
        # identity.  A resume payload often uses ``done``/``finished`` booleans
        # instead of a status string.
        raw_status_value = raw.get("status", raw.get("state", raw.get("phase", "")))
        if raw_status_value in (None, ""):
            if any(
                _to_bool_like(raw.get(key, False), default=False)
                for key in ("completed", "complete", "done", "finished", "passed", "success")
            ):
                raw_status_value = "completed"
            elif any(
                _to_bool_like(raw.get(key, False), default=False)
                for key in ("in_progress", "inprogress", "active", "working", "started")
            ):
                raw_status_value = "in_progress"
        raw_status = str(raw_status_value or "").strip()
        raw_status_key = raw_status.lower().replace("-", "_").replace(" ", "_")
        status = self._normalize_todo_status_value(raw_status, parsed_status or default_status)
        if parsed_status and raw_status_key in {"", "todo", "pending"}:
            status = parsed_status
        if status == "blocked":
            status = "pending"
        owner = self._sanitize_agent_role(raw.get("owner", "")) or owner_hint
        if owner not in worker_owners:
            owner = owner_hint
        # A plan TodoWrite call is scoped to the active step. Model-provided
        # aliases such as "step1" must never create a parallel orphan partition.
        parent_step_id = step_key
        row: dict = {
            "content": content,
            "status": status,
            "owner": owner,
        }
        if key:
            row["key"] = key
        if parent_step_id:
            row["parent_step_id"] = parent_step_id
        active_form = str(raw.get("activeForm", raw.get("active_form", "")) or "").strip()
        if active_form:
            row["activeForm"] = active_form
        for meta_key in (
            "created_at", "updated_at", "started_at", "completed_at",
            "completed_by", "evidence", "evidence_binding", "evidence_ids",
            "revision_reason", "revision_evidence",
        ):
            if meta_key in raw and raw.get(meta_key) not in (None, ""):
                row[meta_key] = raw.get(meta_key)
        for source_key in ("proof", "evidence_ref", "evidence_refs"):
            if not row.get("evidence") and raw.get(source_key) not in (None, ""):
                row["evidence"] = raw.get(source_key)
        supplied_subtask_id = trim(
            str(raw.get("subtask_id", raw.get("subtaskId", "")) or "").strip(),
            100,
        )
        if supplied_subtask_id:
            if self._is_canonical_plan_worker_subtask_id(supplied_subtask_id, step_key):
                row["subtask_id"] = supplied_subtask_id
            else:
                row["external_subtask_id"] = supplied_subtask_id
        for alias_key in (
            "external_subtask_id", "externalSubtaskId", "external_id", "externalId",
            "todo_id", "todoId", "task_id", "taskId", "item_id", "itemId",
            "row_id", "rowId", "id",
        ):
            alias = trim(str(raw.get(alias_key, "") or "").strip(), 120)
            if alias:
                row.setdefault("external_subtask_id", alias)
                break
        if key and not key.startswith("bb:"):
            row.setdefault("external_subtask_id", key)
        row["subtask_id"] = self._stable_plan_worker_subtask_id(step_key, row)
        return row

    def _plan_worker_todo_sort_key(self, row: dict | None) -> tuple:
        import re

        if not isinstance(row, dict):
            return (9999, 9999, 9, 0.0, "")
        content = normalize_work_text(str(row.get("content", "") or "")) or str(row.get("content", "") or "")
        text = content.strip()
        low = text.lower()
        match = re.match(r"^(\d+)\.(\d+)\b", low)
        if match:
            major = int(match.group(1))
            minor = int(match.group(2))
        elif self._is_plan_step_acceptance_subtask(text):
            major = 9998
            minor = 9998
        else:
            major = 9999
            minor = 9999
        status_order = {"completed": 0, "in_progress": 1, "pending": 2, "blocked": 3}
        status = self._normalize_todo_status_value(row.get("status", ""), "pending")
        try:
            created_at = float(row.get("created_at", 0.0) or 0.0)
        except Exception:
            created_at = 0.0
        return (
            major,
            minor,
            status_order.get(status, 9),
            created_at,
            str(row.get("owner", "") or "").strip().lower(),
            low,
        )

    def _todo_route_rows(
        self,
        route_kind: str,
        *,
        rows: list[dict] | None = None,
        role: str = "",
        board: dict | None = None,
    ) -> list[dict]:
        bb = board if isinstance(board, dict) else self._ensure_blackboard()
        snap = [dict(row) for row in (rows if isinstance(rows, list) else self.todo.snapshot()) if isinstance(row, dict)]
        if route_kind in {"plan_single", "plan_sync"}:
            step = self._get_active_plan_step(bb)
            step_id = trim(str((step or {}).get("id", "") or ""), 20)
            if not step_id:
                return []
            scoped = [
                row for row in snap
                if self._todo_row_kind(row) == "plan_worker"
                and str(row.get("parent_step_id", "") or "").strip() == step_id
            ]
            return self._filter_parent_step_duplicate_worker_rows(scoped, step, bb)
        if route_kind == "pure_sync":
            role_key = self._todo_worker_role_hint(role, bb)
            owner_rows = [row for row in snap if self._todo_row_kind(row) == "owner_worker"]
            if role_key in {"developer", "explorer", "reviewer"}:
                scoped = [
                    row for row in owner_rows
                    if str(row.get("owner", "") or "").strip().lower() == role_key
                ]
                if scoped:
                    return scoped
            return owner_rows
        if route_kind == "pure_single":
            # Normal TodoWrite calls are stamped with the active owner so the
            # UI can show who is working.  Older sessions may still contain
            # owner-less ``flat`` rows, while newer sessions contain
            # ``owner_worker`` rows.  A payload-less resume must see both
            # representations; filtering to only ``flat`` made
            # TodoWriteResume fail immediately after a normal TodoWrite.
            return [
                row for row in snap
                if self._todo_row_kind(row) in {"flat", "owner_worker"}
            ]
        return []

    def _filter_plan_fragment_todo_rows(self, rows: list[dict]) -> list[dict]:
        if not isinstance(rows, list) or len(rows) <= 1:
            return list(rows or [])
        out: list[dict] = []
        expected = 1
        candidate_count = len(rows)
        for row in rows:
            if not isinstance(row, dict):
                continue
            content = normalize_embedded_newlines(row.get("content", "") or "").strip()
            marker = self._plan_line_marker(content)
            if self._plan_marker_is_sequence_outlier(
                marker,
                expected_number=expected,
                candidate_count=candidate_count,
            ):
                continue
            out.append(row)
            if isinstance(marker, dict) and marker.get("kind") == "major":
                number = int(marker.get("major", expected) or expected)
                if number >= expected:
                    expected = number + 1
        return out

    def _todo_runtime_has_worker_rows(self, role: str = "") -> bool:
        route_kind = self._todo_route_kind(role=role)
        return bool(self._todo_route_rows(route_kind, role=role))

    def _merge_todo_signal_rows(self, items: list[dict], role: str = "", board: dict | None = None) -> str:
        bb = board if isinstance(board, dict) else self._ensure_blackboard()
        role_key = self._sanitize_agent_role(role)
        route_kind = self._todo_route_kind(role=role_key, board=bb)
        step = self._get_active_plan_step(bb) if route_kind in {"plan_single", "plan_sync"} else None
        step_id = trim(str((step or {}).get("id", "") or ""), 20)
        normalized: list[dict] = []
        for item in items or []:
            if not isinstance(item, dict):
                continue
            row = dict(item)
            if role_key in {"developer", "explorer", "reviewer"} and not str(row.get("owner", "") or "").strip():
                row["owner"] = role_key
            if step_id and not str(row.get("parent_step_id", "") or "").strip():
                row["parent_step_id"] = step_id
            normalized.append(row)
        if not normalized:
            return self.todo.no_changes_text()
        if route_kind in {"plan_single", "plan_sync"}:
            return self._merge_plan_worker_todo_items(normalized, role=role_key)
        if route_kind == "pure_sync":
            return self._merge_owner_scoped_todo_items(normalized, role=role_key)
        return self._merge_flat_todo_items(normalized, role=role_key)

    def _plan_worker_todo_identity(self, row: dict | None) -> str:
        if not isinstance(row, dict):
            return ""
        parent_step_id = trim(str(row.get("parent_step_id", "") or "").strip(), 40)
        subtask_id = self._stable_plan_worker_subtask_id(parent_step_id, row)
        if subtask_id:
            return f"id:{subtask_id}"
        content = self._plan_worker_content_core(row.get("content", ""))
        if not content:
            return ""
        if parent_step_id and self._is_plan_step_acceptance_subtask(content):
            return f"acceptance:{parent_step_id}"
        return f"text:{content}"

    def _plan_worker_revision_references(self, value: object) -> list[str]:
        if isinstance(value, str):
            candidates = [part.strip() for part in re.split(r"[\n;；]+", value)]
        elif isinstance(value, list):
            candidates = [str(part or "").strip() for part in value]
        else:
            candidates = []
        return [trim(part, 240) for part in candidates if part][:8]

    def _plan_worker_revision_evidence_candidates(
        self,
        plan_step: dict,
        *,
        board: dict | None = None,
        since_ts: float = 0.0,
    ) -> list[dict]:
        bb = board if isinstance(board, dict) else self._ensure_blackboard()
        step_id = trim(str((plan_step or {}).get("id", "") or ""), 40)
        rows = self._plan_step_evidence_records(step_id, board=bb, since_ts=since_ts)
        feedback = bb.get("review_feedback", []) if isinstance(bb.get("review_feedback"), list) else []
        for index, raw in enumerate(feedback[-16:]):
            if not isinstance(raw, dict):
                continue
            row_step = trim(str(raw.get("plan_step_id", "") or raw.get("focus_id", "") or ""), 40)
            if row_step and row_step != step_id:
                continue
            try:
                row_ts = float(raw.get("ts", 0.0) or 0.0)
            except Exception:
                row_ts = 0.0
            if since_ts > 0 and row_ts > 0 and row_ts + 1e-6 < since_ts:
                continue
            content = trim(str(raw.get("content", "") or ""), 900)
            status = trim(str(raw.get("status", "") or ""), 80)
            if not content and not status:
                continue
            verdict = self._review_feedback_verdict(raw)
            rows.append({
                "id": f"review:{step_id}:{index}:{int(row_ts or 0)}",
                "step_id": step_id,
                "subtask_id": "",
                "subtask_content": "",
                "kind": "blackboard",
                "tool": "review_feedback",
                "ok": verdict != "fail",
                "command": "",
                "path": "",
                "summary": trim("\n".join(part for part in (status, content) if part), 900),
                "changed_files": [],
                "exit_code": None,
                "actor": trim(str(raw.get("actor", "reviewer") or "reviewer"), 40),
                "ts": row_ts,
                "review_verdict": verdict,
            })
        rows.sort(key=lambda row: float(row.get("ts", 0.0) or 0.0))
        return rows[-40:]

    def _plan_worker_revision_reference_matches(self, reference: str, record: dict) -> bool:
        ref = normalize_work_text(str(reference or "")) or str(reference or "")
        ref = re.sub(r"\s+", " ", ref.strip().lower())
        if len(ref) < 4 or not isinstance(record, dict):
            return False
        event_id = str(record.get("id", "") or "").strip().lower()
        if ref == event_id or (event_id and event_id in ref):
            return True
        tool = str(record.get("tool", "") or "").strip().lower()
        path = normalize_rel_preview_path(str(record.get("path", "") or "")).lower()
        changed = [
            normalize_rel_preview_path(str(value or "")).lower()
            for value in (record.get("changed_files", []) if isinstance(record.get("changed_files"), list) else [])
        ]
        command = re.sub(r"\s+", " ", str(record.get("command", "") or "").strip().lower())
        summary = re.sub(r"\s+", " ", str(record.get("summary", "") or "").strip().lower())
        haystack = " ".join(value for value in (event_id, tool, path, command, summary, " ".join(changed)) if value)
        if ref in haystack or (len(haystack) >= 8 and haystack in ref):
            return True
        tokens = [
            token for token in re.findall(r"[\w./:\\-]{3,}", ref, flags=re.UNICODE)
            if token not in {
                "tool", "result", "evidence", "latest", "recent", "output", "record",
                "工具", "结果", "結果", "证据", "證據", "最新", "最近", "输出", "輸出",
            }
        ]
        if not tokens:
            return False
        matched = [token for token in tokens if token in haystack]
        has_specific = any("/" in token or "\\" in token or "." in token or token.startswith("ev:") for token in matched)
        return bool(has_specific or len(matched) >= min(2, len(tokens)))

    def _append_plan_worker_revision_audit(
        self,
        *,
        step_id: str,
        actor: str,
        status: str,
        reason: str,
        evidence_refs: list[str],
        evidence_ids: list[str],
        before_open: list[str],
        after_open: list[str],
        board: dict | None = None,
    ) -> None:
        bb = board if isinstance(board, dict) else self._ensure_blackboard()
        rows = list(bb.get("plan_todo_revisions", []) if isinstance(bb.get("plan_todo_revisions"), list) else [])
        rows.append({
            "step_id": trim(str(step_id or ""), 40),
            "actor": trim(str(actor or ""), 40),
            "status": trim(str(status or ""), 24),
            "reason": trim(str(reason or ""), 600),
            "evidence_refs": [trim(str(value or ""), 240) for value in evidence_refs[:8]],
            "evidence_ids": [trim(str(value or ""), 80) for value in evidence_ids[:8]],
            "before_open": [trim(str(value or ""), 240) for value in before_open[:8]],
            "after_open": [trim(str(value or ""), 240) for value in after_open[:8]],
            "ts": float(now_ts()),
        })
        bb["plan_todo_revisions"] = rows[-40:]
        bb["updated_at"] = float(now_ts())
        self.blackboard = bb

    def _semantic_audit_plan_worker_revision(
        self,
        plan_step: dict,
        *,
        reason: str,
        before_open: list[str],
        after_open: list[str],
        evidence: list[dict],
    ) -> dict:
        step_text = trim(
            normalize_embedded_newlines(
                str((plan_step or {}).get("full_content", "") or (plan_step or {}).get("content", "") or "")
            ),
            1200,
        )
        evidence_lines = []
        for row in evidence[-8:]:
            evidence_lines.append(
                "- "
                + trim(
                    f"id={row.get('id', '')} tool={row.get('tool', '')} ok={bool(row.get('ok', False))} "
                    f"path={row.get('path', '')} command={row.get('command', '')} "
                    f"review={row.get('review_verdict', '')} result={row.get('summary', '')}",
                    900,
                )
            )
        prompt = (
            "/no_think\n"
            "Audit a proposed rolling revision of only the OPEN subtasks under one approved plan step.\n"
            "Approve only when the cited observable evidence logically requires or materially justifies the exact additions, removals, rewrites, splits, merges, or reorderings.\n"
            "Reject speculative optimization, unrelated evidence, scope drift into another plan step, deletion of still-required work, or a reason that merely restates the proposal.\n"
            "Completed history is protected outside this proposal. Judge the open-part revision against the approved parent step.\n"
            "Return JSON only: {\"approved\":true|false,\"confidence\":\"high|medium|low\",\"reason\":\"...\",\"unsupported_changes\":[\"...\"]}.\n\n"
            f"APPROVED PARENT STEP:\n{step_text}\n\n"
            f"REVISION REASON:\n{trim(reason, 600)}\n\n"
            "CURRENT OPEN SUBTASKS:\n"
            + ("\n".join(f"- {item}" for item in before_open) or "(none)")
            + "\n\nPROPOSED OPEN SUBTASKS:\n"
            + ("\n".join(f"- {item}" for item in after_open) or "(none)")
            + "\n\nCITED CURRENT-STEP EVIDENCE:\n"
            + ("\n".join(evidence_lines) or "(none)")
        )
        try:
            response = self.ollama.chat(
                [{"role": "user", "content": prompt}],
                system=self._inject_runtime_environment_context(
                    "/no_think\nYou are an independent execution-plan revision auditor. Reply only valid JSON."
                ),
                max_tokens=360,
                temperature=0.1,
                think=False,
            )
            raw = str(response.get("content", "") or response.get("text", "") or "").strip()
            payload = extract_json_object_from_text(raw, {})
            if not isinstance(payload, dict):
                return {"available": False, "approved": False, "reason": "semantic audit returned invalid JSON"}
            confidence = str(payload.get("confidence", "low") or "low").strip().lower()
            approved = bool(payload.get("approved", False))
            return {
                "available": True,
                "approved": approved,
                "confidence": confidence,
                "reason": trim(str(payload.get("reason", "") or ""), 600),
                "unsupported_changes": [
                    trim(str(value or ""), 240)
                    for value in (payload.get("unsupported_changes", []) if isinstance(payload.get("unsupported_changes"), list) else [])[:8]
                    if str(value or "").strip()
                ],
            }
        except Exception as exc:
            return {
                "available": False,
                "approved": False,
                "confidence": "low",
                "reason": f"semantic audit unavailable: {trim(str(exc), 180)}",
                "unsupported_changes": [],
            }

    @staticmethod
    def _plan_revision_relation_tokens(value: object) -> set[str]:
        text = unicodedata.normalize("NFKC", str(value or "")).lower()
        tokens = set(re.findall(r"[a-z0-9][a-z0-9_.+-]{2,}", text))
        for run in re.findall(r"[\u4e00-\u9fff]{2,}", text):
            tokens.update(run[index:index + 2] for index in range(max(1, len(run) - 1)))
        stop = {
            "the", "and", "with", "from", "this", "that", "error", "failed", "failure",
            "tool", "result", "output", "step", "task", "运行", "執行", "验证", "驗證",
            "检查", "檢查", "当前", "當前", "步骤", "步驟", "任务", "任務", "报错", "報錯",
        }
        return {token for token in tokens if token not in stop}

    def _plan_revision_texts_related(self, left: object, right: object, minimum: float) -> bool:
        left_text = normalize_work_text(str(left or "")) or str(left or "")
        right_text = normalize_work_text(str(right or "")) or str(right or "")
        left_tokens = self._plan_revision_relation_tokens(left_text)
        right_tokens = self._plan_revision_relation_tokens(right_text)
        token_score = (
            len(left_tokens & right_tokens) / max(1, min(len(left_tokens), len(right_tokens)))
            if left_tokens and right_tokens
            else 0.0
        )
        sequence_score = difflib.SequenceMatcher(None, left_text.lower(), right_text.lower()).ratio()
        return max(token_score, sequence_score) >= float(minimum)

    def _review_plan_worker_revision(
        self,
        plan_step: dict,
        existing_rows: list[dict],
        proposed_rows: list[dict],
        *,
        update_mode: str,
        revision_reason: str,
        revision_evidence: object,
        actor: str,
        board: dict | None = None,
    ) -> dict:
        bb = board if isinstance(board, dict) else self._ensure_blackboard()
        step_id = trim(str((plan_step or {}).get("id", "") or ""), 40)
        before_open = [
            self._plan_worker_content_core(row.get("content", ""))
            for row in existing_rows
            if isinstance(row, dict)
            and str(row.get("status", "pending") or "pending").lower() != "completed"
            and not self._is_plan_step_acceptance_subtask(row.get("content", ""))
        ]
        after_open = [
            self._plan_worker_content_core(row.get("content", ""))
            for row in proposed_rows
            if isinstance(row, dict)
            and str(row.get("status", "pending") or "pending").lower() != "completed"
            and not self._is_plan_step_acceptance_subtask(row.get("content", ""))
        ]
        if before_open == after_open:
            return {"ok": True, "structural": False, "evidence_ids": [], "reason": "status-only update"}
        refs = self._plan_worker_revision_references(revision_evidence)
        reason = trim(str(revision_reason or "").strip(), 600)
        mode = str(update_mode or "status_update").strip().lower()
        if mode not in {"revise_open", "rework_completed"}:
            return {
                "ok": False,
                "structural": True,
                "reason": "open-subtask structure changed without update_mode='revise_open'",
                "before_open": before_open,
                "after_open": after_open,
                "evidence_ids": [],
            }
        if len(normalize_work_text(reason) or reason) < 6:
            return {
                "ok": False,
                "structural": True,
                "reason": "revision_reason must explain the concrete new finding",
                "before_open": before_open,
                "after_open": after_open,
                "evidence_ids": [],
            }
        if not refs:
            return {
                "ok": False,
                "structural": True,
                "reason": "revision_evidence must cite a concrete recent tool result or review finding",
                "before_open": before_open,
                "after_open": after_open,
                "evidence_ids": [],
            }
        accepted_rows = [
            row for row in (bb.get("plan_todo_revisions", []) if isinstance(bb.get("plan_todo_revisions"), list) else [])
            if isinstance(row, dict)
            and str(row.get("step_id", "") or "") == step_id
            and str(row.get("status", "") or "") == "accepted"
        ]
        since_ts = self._plan_step_activation_ts(plan_step)
        if accepted_rows:
            since_ts = max(since_ts, float(accepted_rows[-1].get("ts", 0.0) or 0.0))
        candidates = self._plan_worker_revision_evidence_candidates(plan_step, board=bb, since_ts=since_ts)
        matched: list[dict] = []
        for record in candidates:
            if any(self._plan_worker_revision_reference_matches(ref, record) for ref in refs):
                matched.append(record)
        if not matched:
            return {
                "ok": False,
                "structural": True,
                "reason": "revision_evidence did not match any current-step evidence recorded since the last accepted revision",
                "before_open": before_open,
                "after_open": after_open,
                "evidence_ids": [],
            }
        if mode == "rework_completed" and not any(
            (not bool(row.get("ok", False))) or str(row.get("review_verdict", "") or "") == "fail"
            for row in matched
        ):
            return {
                "ok": False,
                "structural": True,
                "reason": "rework_completed requires matching failure evidence or a reviewer fail finding",
                "before_open": before_open,
                "after_open": after_open,
                "evidence_ids": [str(row.get("id", "") or "") for row in matched],
            }
        semantic_audit = self._semantic_audit_plan_worker_revision(
            plan_step,
            reason=reason,
            before_open=before_open,
            after_open=after_open,
            evidence=matched,
        )
        if not bool(semantic_audit.get("available", False)):
            return {
                "ok": False,
                "structural": True,
                "reason": str(semantic_audit.get("reason", "semantic revision audit unavailable") or "semantic revision audit unavailable"),
                "before_open": before_open,
                "after_open": after_open,
                "evidence_ids": [str(row.get("id", "") or "") for row in matched],
            }
        if not bool(semantic_audit.get("approved", False)):
            unsupported = "; ".join(str(value) for value in (semantic_audit.get("unsupported_changes", []) or [])[:4])
            detail = str(semantic_audit.get("reason", "semantic audit rejected the revision") or "semantic audit rejected the revision")
            if unsupported:
                detail = f"{detail}; unsupported: {unsupported}"
            return {
                "ok": False,
                "structural": True,
                "reason": trim(detail, 700),
                "before_open": before_open,
                "after_open": after_open,
                "evidence_ids": [str(row.get("id", "") or "") for row in matched],
            }
        return {
            "ok": True,
            "structural": True,
            "reason": trim(
                str(semantic_audit.get("reason", "runtime evidence and semantic audit accepted the rolling subplan revision") or ""),
                600,
            ),
            "before_open": before_open,
            "after_open": after_open,
            "evidence_ids": [str(row.get("id", "") or "") for row in matched],
        }

    def _flat_todo_identity(self, row: dict | None) -> str:
        import re

        if not isinstance(row, dict):
            return ""
        key = trim(str(row.get("key", "") or "").strip(), 120)
        if key.startswith("bb:"):
            return f"system:{key}"
        for field in (
            "key", "external_subtask_id", "external_id", "todo_id", "task_id",
            "item_id", "row_id", "id", "subtask_id",
        ):
            external_id = trim(str(row.get(field, "") or "").strip(), 120)
            if external_id and not external_id.startswith("bb:"):
                return f"external:{external_id.casefold()}"
        content = normalize_work_text(str(row.get("content", "") or "")) or str(row.get("content", "") or "")
        content = re.sub(r"\s+", " ", content.strip().lower())
        if not content:
            return ""
        match = re.match(r"^(\d+\.\d+)\b", content)
        if match:
            return f"substep:{match.group(1)}"
        return f"text:{content}"

    def _stable_root_todo_id(self, row: dict | None) -> str:
        item = row if isinstance(row, dict) else {}
        existing = trim(str(item.get("subtask_id", "") or "").strip(), 100)
        if existing.startswith("rt:"):
            return existing
        identity = self._flat_todo_identity({key: value for key, value in item.items() if key != "subtask_id"})
        if not identity:
            return ""
        return "rt:" + hashlib.sha1(identity.encode("utf-8", "ignore")).hexdigest()[:20]

    def _ensure_root_todo_baseline(self, rows: list[dict], *, board: dict | None = None) -> list[dict]:
        bb = board if isinstance(board, dict) else self._ensure_blackboard()
        baseline = list(bb.get("todo_tree_baseline", []) if isinstance(bb.get("todo_tree_baseline"), list) else [])
        known = {
            str(row.get("identity", "") or "")
            for row in baseline
            if isinstance(row, dict) and str(row.get("identity", "") or "")
        }
        changed = False
        for raw in rows:
            if not isinstance(raw, dict) or self._todo_row_kind(raw) == "system":
                continue
            identity = self._flat_todo_identity(raw) or self._stable_root_todo_id(raw)
            if not identity or identity in known:
                continue
            baseline.append({
                "identity": identity,
                "content": trim(str(raw.get("content", "") or ""), 500),
                "owner": self._sanitize_agent_role(raw.get("owner", "")),
                "status": self._normalize_todo_status_value(raw.get("status", ""), "pending"),
                "created_at": float(raw.get("created_at", 0.0) or now_ts()),
            })
            known.add(identity)
            changed = True
        if changed or "todo_tree_baseline" not in bb:
            bb["todo_tree_baseline"] = baseline[:40]
            bb["updated_at"] = float(now_ts())
            self.blackboard = bb
        return baseline[:40]

    def _root_todo_revision_evidence(self, revision_evidence: object, *, board: dict | None = None) -> list[str]:
        bb = board if isinstance(board, dict) else self._ensure_blackboard()
        evidence: list[str] = []
        if isinstance(revision_evidence, str):
            if revision_evidence.strip():
                evidence.append(revision_evidence.strip())
        elif isinstance(revision_evidence, list):
            evidence.extend(str(value or "").strip() for value in revision_evidence if str(value or "").strip())
        elif isinstance(revision_evidence, dict):
            evidence.append(json.dumps(revision_evidence, ensure_ascii=False, sort_keys=True))
        for section, label in (("execution_logs", "execution"), ("review_feedback", "review")):
            rows = bb.get(section, []) if isinstance(bb.get(section), list) else []
            for row in rows[-8:]:
                if not isinstance(row, dict):
                    continue
                content = str(row.get("content", "") or "").strip()
                if content:
                    evidence.append(f"{label}: {content}")
        artifacts = bb.get("code_artifacts", {}) if isinstance(bb.get("code_artifacts"), dict) else {}
        for path, row in list(artifacts.items())[-12:]:
            summary = str((row or {}).get("summary", "") or "").strip() if isinstance(row, dict) else ""
            evidence.append(f"artifact: {path}" + (f" - {summary}" if summary else ""))
        return list(dict.fromkeys(trim(value, 900) for value in evidence if value))[:24]

    @staticmethod
    def _normalize_root_todo_replacement_mapping(value: object) -> list[dict]:
        if isinstance(value, dict):
            value = [
                {"removed": key, "replacement": replacement, "reason": ""}
                for key, replacement in value.items()
            ]
        if not isinstance(value, list):
            return []
        rows: list[dict] = []
        for raw in value[:40]:
            if not isinstance(raw, dict):
                continue
            removed = str(raw.get("removed", raw.get("from", raw.get("objective", ""))) or "").strip()
            replacement = str(raw.get("replacement", raw.get("to", raw.get("covered_by", ""))) or "").strip()
            reason = str(raw.get("reason", raw.get("rationale", "")) or "").strip()
            if removed:
                rows.append({
                    "removed": trim(removed, 500),
                    "replacement": trim(replacement, 500),
                    "reason": trim(reason, 500),
                })
        return rows

    def _semantic_audit_root_todo_revision(
        self,
        *,
        reason: str,
        baseline: list[dict],
        current_rows: list[dict],
        proposed_rows: list[dict],
        removed_objectives: list[str],
        evidence: list[str],
    ) -> dict:
        goal = str(self._authoritative_user_goal_for_model() or self._ensure_blackboard().get("original_goal", "") or "").strip()
        completed = [
            str(row.get("content", "") or "").strip()
            for row in current_rows
            if isinstance(row, dict) and self._normalize_todo_status_value(row.get("status", ""), "pending") == "completed"
        ]

        def _render(rows: list[dict]) -> str:
            return "\n".join(
                f"- [{self._normalize_todo_status_value(row.get('status', ''), 'pending')}] {str(row.get('content', '') or '').strip()}"
                for row in rows
                if isinstance(row, dict) and str(row.get("content", "") or "").strip()
            ) or "(none)"

        prompt = (
            "/no_think\n"
            "You are the independent safety reviewer for a proposed rewrite of an execution Todo tree. "
            "Dynamic replanning is allowed, but task completion and every authoritative user requirement must remain covered.\n"
            "Reject when an unfinished objective disappears without a concrete replacement or completion proof, when the proposal narrows scope, "
            "when the stated reason merely restates the new list, or when evidence/coverage is uncertain. Do not classify stages by keywords; judge semantics.\n"
            "Return JSON only with ALL fields: "
            "{\"decision\":\"approve|reject\",\"confidence\":\"high|medium|low\",\"reason\":\"...\","
            "\"removed_objectives\":[\"...\"],\"replacement_mapping\":[{\"removed\":\"...\",\"replacement\":\"...\",\"reason\":\"...\"}],"
            "\"requirement_coverage\":[\"requirement -> proposed objective/evidence\"],\"completion_risk\":\"low|medium|high\","
            "\"evidence\":[\"...\"]}.\n\n"
            f"AUTHORITATIVE USER GOAL:\n{goal or '(unavailable)'}\n\n"
            "ORIGINAL TODO BASELINE:\n" + _render(baseline) + "\n\n"
            "CURRENT CANONICAL TODO TREE:\n" + _render(current_rows) + "\n\n"
            "PROPOSED COMPLETE TODO TREE:\n" + _render(proposed_rows) + "\n\n"
            f"PROPOSER REASON:\n{reason}\n\n"
            "DETERMINISTICALLY REMOVED OR MATERIALLY REWRITTEN OPEN OBJECTIVES:\n"
            + ("\n".join(f"- {value}" for value in removed_objectives) or "(none)")
            + "\n\nCOMPLETED ROWS:\n"
            + ("\n".join(f"- {value}" for value in completed) or "(none)")
            + "\n\nAVAILABLE EVIDENCE:\n"
            + ("\n".join(f"- {value}" for value in evidence) or "(none)")
        )
        try:
            response = self.ollama.chat(
                [{"role": "user", "content": prompt}],
                system=self._inject_runtime_environment_context(
                    "/no_think\nYou audit Todo-tree rewrites for requirement preservation. Reply only valid JSON."
                ),
                max_tokens=1000,
                temperature=0.1,
                think=False,
            )
            raw = str(response.get("content", "") or response.get("text", "") or "").strip()
            payload = extract_json_object_from_text(raw, {})
            if not isinstance(payload, dict) or not payload:
                return {"available": False, "approved": False, "reason": "Todo-tree review returned invalid structured JSON"}
            decision = str(payload.get("decision", "") or "").strip().lower()
            confidence = str(payload.get("confidence", "low") or "low").strip().lower()
            risk = str(payload.get("completion_risk", "high") or "high").strip().lower()
            review_reason = str(payload.get("reason", "") or "").strip()
            reported_removed = payload.get("removed_objectives", [])
            coverage = payload.get("requirement_coverage", [])
            review_evidence = payload.get("evidence", [])
            mapping = self._normalize_root_todo_replacement_mapping(payload.get("replacement_mapping", []))
            required_shape = (
                decision in {"approve", "reject"}
                and confidence in {"high", "medium", "low"}
                and risk in {"low", "medium", "high"}
                and len(review_reason) >= 6
                and isinstance(reported_removed, list)
                and isinstance(coverage, list)
                and isinstance(review_evidence, list)
            )
            if not required_shape:
                return {"available": False, "approved": False, "reason": "Todo-tree review omitted required decision, reason, mapping, coverage, risk, or evidence fields"}
            reported_removed = [trim(str(value or ""), 500) for value in reported_removed[:40] if str(value or "").strip()]
            coverage = [trim(str(value or ""), 700) for value in coverage[:40] if str(value or "").strip()]
            review_evidence = [trim(str(value or ""), 700) for value in review_evidence[:20] if str(value or "").strip()]
            # All semantic judgment belongs to the reviewer model. The runtime
            # validates only the response contract and honors its decision; it
            # does not second-guess coverage with keywords, similarity scores,
            # locally assigned risk thresholds, or stage classifiers.
            approved = decision == "approve"
            return {
                "available": True,
                "approved": approved,
                "decision": decision,
                "confidence": confidence,
                "reason": trim(review_reason, 1200),
                "removed_objectives": reported_removed,
                "replacement_mapping": mapping,
                "requirement_coverage": coverage,
                "completion_risk": risk,
                "evidence": review_evidence,
            }
        except Exception as exc:
            return {
                "available": False,
                "approved": False,
                "confidence": "low",
                "completion_risk": "high",
                "reason": f"Todo-tree semantic review unavailable: {trim(str(exc), 240)}",
            }

    def _append_root_todo_revision_audit(
        self,
        *,
        actor: str,
        status: str,
        mode: str,
        reason: str,
        review: dict,
        before_open: list[str],
        after_open: list[str],
        board: dict | None = None,
    ) -> None:
        bb = board if isinstance(board, dict) else self._ensure_blackboard()
        rows = list(bb.get("todo_tree_revisions", []) if isinstance(bb.get("todo_tree_revisions"), list) else [])
        rows.append({
            "actor": trim(str(actor or ""), 40),
            "status": trim(str(status or ""), 24),
            "mode": trim(str(mode or ""), 32),
            "reason": trim(str(reason or ""), 1200),
            "review_reason": trim(str(review.get("reason", "") or ""), 1200),
            "completion_risk": trim(str(review.get("completion_risk", "high") or "high"), 24),
            "removed_objectives": list(review.get("removed_objectives", []) or [])[:40],
            "replacement_mapping": list(review.get("replacement_mapping", []) or [])[:40],
            "requirement_coverage": list(review.get("requirement_coverage", []) or [])[:40],
            "evidence": list(review.get("evidence", []) or [])[:20],
            "before_open": [trim(str(value or ""), 500) for value in before_open[:40]],
            "after_open": [trim(str(value or ""), 500) for value in after_open[:40]],
            "ts": float(now_ts()),
        })
        bb["todo_tree_revisions"] = rows[-40:]
        bb["updated_at"] = float(now_ts())
        self.blackboard = bb
        self._emit(
            "status",
            {
                "summary": trim(
                    f"Todo-tree revision {status}: {review.get('reason', reason)}",
                    300,
                )
            },
        )

    def _root_todo_material_changes(self, existing_rows: list[dict], proposed_rows: list[dict]) -> tuple[list[str], list[str], list[str]]:
        before_open = [
            str(row.get("content", "") or "").strip()
            for row in existing_rows
            if isinstance(row, dict) and self._normalize_todo_status_value(row.get("status", ""), "pending") != "completed"
        ]
        after_open = [
            str(row.get("content", "") or "").strip()
            for row in proposed_rows
            if isinstance(row, dict) and self._normalize_todo_status_value(row.get("status", ""), "pending") != "completed"
        ]
        proposed_by_id = {
            self._flat_todo_identity(row): row
            for row in proposed_rows
            if isinstance(row, dict) and self._flat_todo_identity(row)
        }
        removed: list[str] = []
        for row in existing_rows:
            if not isinstance(row, dict) or self._normalize_todo_status_value(row.get("status", ""), "pending") == "completed":
                continue
            identity = self._flat_todo_identity(row)
            proposed = proposed_by_id.get(identity)
            old_content = str(row.get("content", "") or "").strip()
            if not isinstance(proposed, dict) or self._normalize_todo_status_value(proposed.get("status", ""), "pending") == "completed":
                removed.append(old_content)
                continue
            new_content = str(proposed.get("content", "") or "").strip()
            if normalize_work_text(old_content) != normalize_work_text(new_content):
                removed.append(old_content)
        return before_open, after_open, list(dict.fromkeys(value for value in removed if value))

    def _merge_root_todo_scope(
        self,
        items: list[dict],
        *,
        role: str,
        existing_scope: list[dict],
        preserved_rows: list[dict],
        update_mode: str,
        revision_reason: str,
        revision_evidence: object,
        transaction: dict | None,
    ) -> str:
        role_key = self._sanitize_agent_role(role)
        bb = self._ensure_blackboard()
        self._ensure_root_todo_baseline(existing_scope, board=bb)
        mode = str(update_mode or "status_update").strip().lower().replace("-", "_")
        if mode not in {"status_update", "revise_open", "rework_completed"}:
            mode = "status_update"
        if mode == "status_update" and (str(revision_reason or "").strip() or self._plan_worker_revision_references(revision_evidence)):
            mode = "revise_open"

        normalized: list[dict] = []
        passthrough: list[dict] = []
        for item in items:
            row = self._normalize_generic_todo_row(item, owner=role_key)
            if not row:
                continue
            if str(row.get("key", "") or "").startswith("bb:"):
                passthrough.append(row)
                continue
            if role_key in {"manager", "explorer", "developer", "reviewer"}:
                row["owner"] = role_key
            row["subtask_id"] = self._stable_root_todo_id(row)
            normalized.append(row)
        if not normalized:
            return self.todo.update(preserved_rows + passthrough + existing_scope)

        existing_entries: list[tuple[str, dict, int]] = []
        for index, row in enumerate(existing_scope):
            identity = self._flat_todo_identity(row)
            if identity:
                existing_entries.append((identity, dict(row), index))
        used: set[str] = set()
        matched: list[tuple[dict, str, dict | None, int]] = []
        for incoming in normalized:
            identity = self._flat_todo_identity(incoming)
            prior: dict | None = None
            prior_index = -1
            for candidate_id, candidate, candidate_index in existing_entries:
                if candidate_id == identity and candidate_id not in used:
                    prior = candidate
                    prior_index = candidate_index
                    identity = candidate_id
                    break
            if prior is None:
                scored: list[tuple[float, str, dict, int]] = []
                for candidate_id, candidate, candidate_index in existing_entries:
                    if candidate_id in used:
                        continue
                    score = self._plan_worker_todo_match_score(incoming, candidate)
                    if score >= 0.64:
                        scored.append((score, candidate_id, candidate, candidate_index))
                scored.sort(key=lambda value: value[0], reverse=True)
                if scored and (scored[0][0] >= 0.86 or len(scored) == 1 or scored[0][0] - scored[1][0] >= 0.08):
                    _score, identity, prior, prior_index = scored[0]
            if isinstance(prior, dict):
                used.add(identity)
                incoming["subtask_id"] = prior.get("subtask_id", "") or self._stable_root_todo_id(prior)
                if prior.get("external_subtask_id") and not incoming.get("external_subtask_id"):
                    incoming["external_subtask_id"] = prior.get("external_subtask_id")
            matched.append((incoming, identity, prior, prior_index))

        if not existing_scope:
            state_lock = getattr(self, "lock", None)
            if state_lock is not None:
                state_lock.acquire()
            try:
                valid, stale_reason = self._todo_write_transaction_is_current(transaction, board=self._ensure_blackboard())
                if not valid:
                    return self._emit_stale_todo_write_discarded(stale_reason)
                result = self.todo.update(preserved_rows + passthrough + normalized)
            finally:
                if state_lock is not None:
                    state_lock.release()
            self._ensure_root_todo_baseline(normalized, board=bb)
            return result

        if mode == "status_update":
            merged_scope = [dict(row) for row in existing_scope]
            for incoming, _identity, prior, prior_index in matched:
                if isinstance(prior, dict) and prior_index >= 0:
                    merged = dict(prior)
                    prior_status = self._normalize_todo_status_value(prior.get("status", ""), "pending")
                    incoming_status = self._normalize_todo_status_value(incoming.get("status", ""), prior_status)
                    if prior_status == "completed" and incoming_status != "completed":
                        incoming_status = "completed"
                    merged["status"] = incoming_status
                    merged["updated_at"] = float(now_ts())
                    for meta_key in ("evidence", "evidence_binding", "evidence_ids", "completed_at", "completed_by", "started_at"):
                        if incoming.get(meta_key) not in (None, "", []):
                            merged[meta_key] = incoming.get(meta_key)
                    # Status updates cannot silently abbreviate or redirect an
                    # objective. Structural text changes belong to revise_open.
                    merged_scope[prior_index] = merged
                else:
                    incoming["created_at"] = float(incoming.get("created_at", 0.0) or now_ts())
                    merged_scope.append(incoming)
            state_lock = getattr(self, "lock", None)
            if state_lock is not None:
                state_lock.acquire()
            try:
                valid, stale_reason = self._todo_write_transaction_is_current(transaction, board=self._ensure_blackboard())
                if not valid:
                    return self._emit_stale_todo_write_discarded(stale_reason)
                return self.todo.update(preserved_rows + passthrough + merged_scope)
            finally:
                if state_lock is not None:
                    state_lock.release()

        reason = trim(str(revision_reason or "").strip(), 1200)
        if not (normalize_work_text(reason) or reason).strip():
            review = {"reason": "revision_reason must explain why the existing open objectives no longer form a completion-safe tree", "completion_risk": "high"}
            before_open, after_open, _removed = self._root_todo_material_changes(existing_scope, existing_scope)
            self._append_root_todo_revision_audit(
                actor=role_key, status="rejected", mode=mode, reason=reason,
                review=review, before_open=before_open, after_open=after_open, board=bb,
            )
            return self._plan_control_feedback("preserve_todo_tree", f"Todo-tree revision rejected: {review['reason']}.\n\n{self.todo.render()}")

        proposed_scope: list[dict] = []
        represented: set[str] = set()
        for incoming, identity, prior, _prior_index in matched:
            if isinstance(prior, dict):
                represented.add(identity)
                prior_status = self._normalize_todo_status_value(prior.get("status", ""), "pending")
                if prior_status == "completed" and mode != "rework_completed":
                    proposed_scope.append(dict(prior))
                    continue
                revised = dict(prior)
                revised.update(incoming)
                revised["subtask_id"] = prior.get("subtask_id", "") or self._stable_root_todo_id(prior)
                revised["updated_at"] = float(now_ts())
                proposed_scope.append(revised)
            else:
                incoming["created_at"] = float(incoming.get("created_at", 0.0) or now_ts())
                proposed_scope.append(incoming)
        # Completed history is immutable unless the explicit rework mode names
        # and successfully reviews the row. Omission alone can never erase it.
        for identity, prior, _index in existing_entries:
            if identity in represented:
                continue
            if self._normalize_todo_status_value(prior.get("status", ""), "pending") == "completed":
                proposed_scope.insert(0, dict(prior))

        before_open, after_open, removed = self._root_todo_material_changes(existing_scope, proposed_scope)
        evidence = self._root_todo_revision_evidence(revision_evidence, board=bb)
        baseline = self._ensure_root_todo_baseline(existing_scope, board=bb)
        review = self._semantic_audit_root_todo_revision(
            reason=reason,
            baseline=baseline,
            current_rows=existing_scope,
            proposed_rows=proposed_scope,
            removed_objectives=removed,
            evidence=evidence,
        )
        if not bool(review.get("available", False)) or not bool(review.get("approved", False)):
            self._append_root_todo_revision_audit(
                actor=role_key, status="rejected", mode=mode, reason=reason,
                review=review, before_open=before_open, after_open=after_open, board=bb,
            )
            return self._plan_control_feedback(
                "preserve_todo_tree",
                f"Todo-tree revision rejected: {review.get('reason', 'semantic review did not prove full requirement coverage')}. "
                f"The canonical tree was preserved.\n\n{self.todo.render()}",
            )

        state_lock = getattr(self, "lock", None)
        if state_lock is not None:
            state_lock.acquire()
        try:
            valid, stale_reason = self._todo_write_transaction_is_current(transaction, board=self._ensure_blackboard())
            if not valid:
                return self._emit_stale_todo_write_discarded(stale_reason)
            result = self.todo.update(preserved_rows + passthrough + proposed_scope)
        finally:
            if state_lock is not None:
                state_lock.release()
        self._append_root_todo_revision_audit(
            actor=role_key, status="accepted", mode=mode, reason=reason,
            review=review, before_open=before_open, after_open=after_open, board=bb,
        )
        return (
            f"{result}\nTODO TREE REVISION: accepted after independent LLM coverage/risk review. "
            f"Reason: {review.get('reason', reason)}"
        )

    def _merge_flat_todo_items(
        self,
        items: list[dict],
        role: str = "",
        *,
        update_mode: str = "status_update",
        revision_reason: str = "",
        revision_evidence: object = None,
        transaction: dict | None = None,
    ) -> str:
        if not isinstance(items, list):
            raise ValueError("items must be array")
        role_key = self._sanitize_agent_role(role)
        existing = self.todo.snapshot()
        route_existing = self._todo_route_rows("pure_single", rows=existing, role=role_key)
        preserved_system = [
            dict(row) for row in existing
            if isinstance(row, dict) and self._todo_row_kind(row) == "system"
        ]
        return self._merge_root_todo_scope(
            items,
            role=role_key,
            existing_scope=route_existing,
            preserved_rows=preserved_system,
            update_mode=update_mode,
            revision_reason=revision_reason,
            revision_evidence=revision_evidence,
            transaction=transaction,
        )

    # --- Active-step worker todo reconciliation -------------------------------
    # Merge worker-submitted subtasks into the active plan step while
    # preserving canonical identities and preventing duplicate rewrites.
    def _merge_plan_worker_todo_items(
        self,
        items: list[dict],
        role: str = "",
        *,
        update_mode: str = "status_update",
        revision_reason: str = "",
        revision_evidence: object = None,
        trusted_restore: bool = False,
        transaction: dict | None = None,
    ) -> str:
        if not isinstance(items, list):
            raise ValueError("items must be array")
        bb = self._ensure_blackboard()
        if transaction is not None:
            valid, stale_reason = self._todo_write_transaction_is_current(
                transaction,
                board=bb,
            )
            if not valid:
                return self._emit_stale_todo_write_discarded(stale_reason)
        active_step = self._get_active_plan_step()
        if not isinstance(active_step, dict):
            if transaction is not None:
                return self._emit_stale_todo_write_discarded("active plan step no longer exists")
            return self.todo.update(items)
        step_id = trim(str(active_step.get("id", "") or ""), 20)
        if not step_id:
            if transaction is not None:
                return self._emit_stale_todo_write_discarded("active plan step no longer exists")
            return self.todo.update(items)
        role_key = self._sanitize_agent_role(role) or self._current_plan_worker_owner()
        if transaction is None:
            transaction = self._capture_todo_write_transaction(
                bb,
                active_step_id=step_id,
            )
        valid, stale_reason = self._todo_write_transaction_is_current(
            transaction,
            board=bb,
        )
        if not valid:
            return self._emit_stale_todo_write_discarded(stale_reason)
        existing = self.todo.snapshot()
        preserved: list[dict] = []
        target_rows: list[dict] = []
        worker_owners = {"developer", "explorer", "reviewer"}
        for row in existing:
            if not isinstance(row, dict):
                continue
            row_kind = self._todo_row_kind(row)
            if row_kind == "system":
                preserved.append(dict(row))
                continue
            if row_kind != "plan_worker":
                preserved.append(dict(row))
                continue
            owner = str(row.get("owner", "") or "").strip().lower()
            raw_row_step_id = trim(str(row.get("parent_step_id", "") or ""), 40)
            row_step_id = self._canonical_plan_worker_parent_id(
                raw_row_step_id,
                rows=[row],
                board=bb,
            ) or raw_row_step_id
            migrated_row = dict(row)
            migrated_row["parent_step_id"] = row_step_id
            self._capture_plan_worker_external_identity(migrated_row, row_step_id)
            migrated_row["subtask_id"] = self._stable_plan_worker_subtask_id(row_step_id, migrated_row)
            if owner in worker_owners and row_step_id == step_id:
                target_rows.append(migrated_row)
            else:
                preserved.append(migrated_row)
        target_rows = self._dedupe_plan_worker_rows(target_rows, step_id)

        incoming_normalized: list[dict] = []
        for idx, item in enumerate(items):
            if not isinstance(item, (str, dict)):
                raise ValueError(f"item {idx}: invalid type")
            if isinstance(item, dict) and not str(item.get("key", "") or "").startswith("bb:"):
                supplied_parent = trim(str(item.get("parent_step_id", "") or "").strip(), 40)
                if supplied_parent:
                    supplied_canonical = self._canonical_plan_worker_parent_id(
                        supplied_parent,
                        rows=[item],
                        board=bb,
                    )
                    if supplied_canonical != step_id:
                        canonical = self._render_plan_worker_todo_canonical(step_id, target_rows)
                        return self._plan_control_feedback(
                            "preserve_current_subplan",
                            "TodoWrite rejected a cross-step update. "
                            f"The active parent_step_id is '{step_id}', but the payload supplied "
                            f"'{supplied_parent}'. Update only the active parent step."
                            + (f"\n\n{canonical}" if canonical else "")
                        )
            raw = self._normalize_plan_worker_todo_input(
                item,
                step_id=step_id,
                role_key=role_key,
                default_status="pending",
            )
            if not raw:
                continue
            key = trim(str(raw.get("key", "") or "").strip(), 120)
            if key.startswith("bb:"):
                incoming_normalized.append(raw)
                continue
            parent_step_id = trim(str(raw.get("parent_step_id", "") or ""), 20)
            if not parent_step_id:
                raw["parent_step_id"] = step_id
            if self._plan_worker_row_is_foreign_plan_step(raw, active_step, bb):
                canonical = self._render_plan_worker_todo_canonical(step_id, target_rows)
                return self._plan_control_feedback(
                    "preserve_current_subplan",
                    "TodoWrite rejected a cross-step row in the proposed subplan. "
                    "Submit only rows whose N.M prefix belongs to the active parent step; "
                    "the entire current subplan was preserved atomically."
                    + (f"\n\n{canonical}" if canonical else "")
                )
            if self._plan_worker_row_duplicates_parent_step(raw, active_step):
                continue
            incoming_normalized.append(raw)

        incoming_worker_rows = [row for row in incoming_normalized if not str(row.get("key", "") or "").startswith("bb:")]
        if not incoming_worker_rows:
            canonical = self._render_plan_worker_todo_canonical(step_id, target_rows)
            if target_rows:
                # A resume/status call may carry only the parent bb: row (or an
                # empty structural envelope). Preserve the current canonical
                # children instead of turning a valid handoff into an error.
                return self._plan_control_feedback(
                    "preserve_current_subplan",
                    "No worker rows were supplied; the canonical current-step subtasks were preserved. "
                    "Continue the existing [>] subtask and send its status/evidence when it changes."
                    + (f"\n\n{canonical}" if canonical else ""),
                )
            return self._plan_control_feedback(
                "preserve_current_subplan",
                "No current-step worker rows were supplied; keep the active plan step and create its step-local subtasks before executing."
                + (f"\n\n{canonical}" if canonical else ""),
            )

        mode = str(update_mode or "status_update").strip().lower().replace("-", "_")
        if mode not in {"status_update", "revise_open", "rework_completed"}:
            mode = "status_update"
        if mode == "status_update" and (str(revision_reason or "").strip() or self._plan_worker_revision_references(revision_evidence)):
            mode = "revise_open"

        completion_audit_warnings: list[str] = []

        def _resolved_row_owner(prior: dict | None, incoming: dict | None = None) -> str:
            """Keep Sync ownership stable while Single retains one executor."""
            if self._is_multi_agent_mode():
                for candidate in (
                    (prior or {}).get("owner", ""),
                    (incoming or {}).get("owner", ""),
                    role_key,
                ):
                    owner = self._sanitize_agent_role(candidate)
                    if owner in worker_owners:
                        return owner
            return role_key

        def _number_key(row: dict) -> str:
            match = re.match(r"^\s*(\d+\.\d+)\b", normalize_work_text(str(row.get("content", "") or "")) or str(row.get("content", "") or ""))
            return match.group(1) if match else ""

        existing_by_id = {
            self._stable_plan_worker_subtask_id(step_id, row): dict(row)
            for row in target_rows
            if self._stable_plan_worker_subtask_id(step_id, row)
        }
        existing_by_core = {
            self._plan_worker_content_core(row.get("content", "")): self._stable_plan_worker_subtask_id(step_id, row)
            for row in target_rows
            if self._plan_worker_content_core(row.get("content", ""))
        }
        existing_by_number = {
            _number_key(row): self._stable_plan_worker_subtask_id(step_id, row)
            for row in target_rows
            if _number_key(row)
        }

        existing_entries = [
            (key, value)
            for key, value in existing_by_id.items()
            if isinstance(value, dict)
        ]
        match_cache: dict[int, tuple[str, dict | None]] = {}
        used_match_ids: set[str] = set()

        def _existing_match(row: dict) -> tuple[str, dict | None]:
            cached = match_cache.get(id(row))
            if cached is not None:
                return cached
            subtask_id = trim(str(row.get("subtask_id", "") or ""), 80)
            if subtask_id and subtask_id in existing_by_id:
                result = (subtask_id, existing_by_id[subtask_id])
                match_cache[id(row)] = result
                used_match_ids.add(subtask_id)
                return result
            core = self._plan_worker_content_core(row.get("content", ""))
            core_id = existing_by_core.get(core, "")
            if core_id and core_id not in used_match_ids:
                result = (core_id, existing_by_id.get(core_id))
                match_cache[id(row)] = result
                used_match_ids.add(core_id)
                return result
            number_id = existing_by_number.get(_number_key(row), "")
            if number_id and number_id not in used_match_ids:
                result = (number_id, existing_by_id.get(number_id))
                match_cache[id(row)] = result
                used_match_ids.add(number_id)
                return result
            # Last resort: semantic matching tolerates a changed N.M prefix,
            # translated wording, and small evidence annotations. Require a
            # strong/unique score so unrelated open rows are still audited as a
            # structural revision instead of silently merged.
            scored: list[tuple[float, str, dict]] = []
            for candidate_id, candidate in existing_entries:
                if candidate_id in used_match_ids:
                    continue
                score = self._plan_worker_todo_match_score(row, candidate)
                if score >= 0.64:
                    scored.append((score, candidate_id, candidate))
            scored.sort(key=lambda value: value[0], reverse=True)
            if scored:
                best = scored[0]
                second_score = scored[1][0] if len(scored) > 1 else 0.0
                if best[0] >= 0.86 or best[0] - second_score >= 0.08:
                    result = (best[1], best[2])
                    match_cache[id(row)] = result
                    used_match_ids.add(best[1])
                    return result
            generated = self._stable_plan_worker_subtask_id(step_id, row)
            result = (generated, existing_by_id.get(generated))
            match_cache[id(row)] = result
            if generated and generated in existing_by_id:
                used_match_ids.add(generated)
            return result

        for row in incoming_worker_rows:
            subtask_id, _matched = _existing_match(row)
            row["subtask_id"] = subtask_id or self._stable_plan_worker_subtask_id(step_id, row)

        if trusted_restore:
            current_step_rows = [dict(row) for row in incoming_worker_rows]
        elif not target_rows:
            current_step_rows = [dict(row) for row in incoming_worker_rows]
            for row in current_step_rows:
                row["owner"] = _resolved_row_owner(None, row)
                if str(row.get("status", "pending") or "pending").lower() != "completed":
                    continue
                since_value = float(row.get("created_at", 0.0) or row.get("started_at", 0.0) or 0.0)
                subtask_id = str(row.get("subtask_id", "") or "")
                if not self._plan_worker_completion_has_evidence(
                    active_step,
                    row,
                    board=bb,
                    subtask_id=subtask_id,
                    since_ts=since_value,
                    evidence=row.get("evidence", ""),
                ):
                    row["status"] = "pending"
                    row.pop("completed_at", None)
                    row.pop("completed_by", None)
                    completion_audit_warnings.append(
                        self._plan_subtask_completion_audit_warning(
                            active_step,
                            row,
                            board=bb,
                            subtask_id=subtask_id,
                            since_ts=since_value,
                        )
                    )
                else:
                    records = self._plan_worker_completion_evidence_records(
                        active_step,
                        row,
                        board=bb,
                        subtask_id=subtask_id,
                        since_ts=since_value,
                        evidence=row.get("evidence", ""),
                    )
                    binding = self._record_plan_subtask_evidence_binding(
                        active_step,
                        row,
                        records,
                        source="direct",
                        actor=role_key,
                        board=bb,
                    )
                    if binding:
                        row["evidence_ids"] = list(binding.get("evidence_ids", []) or [])
                        row["evidence_binding"] = binding
        elif mode == "status_update":
            structural_changes: list[dict] = []
            for row in incoming_worker_rows:
                _subtask_id, prior = _existing_match(row)
                if prior is None:
                    if not self._is_plan_step_acceptance_subtask(row.get("content", "")):
                        structural_changes.append(row)
                    continue
                if not self._plan_worker_rows_equivalent(row, prior):
                    structural_changes.append(row)
            if structural_changes:
                canonical = self._render_plan_worker_todo_canonical(step_id, target_rows)
                return self._plan_control_feedback(
                    "preserve_current_subplan",
                    "TodoWrite status_update cannot add, replace, remove, split, merge, or reorder open subtasks. "
                    "Use update_mode='revise_open' with revision_reason and revision_evidence that cite a current-step tool result or review finding."
                    + (f"\n\n{canonical}" if canonical else "")
                )
            patched_by_id = {key: dict(value) for key, value in existing_by_id.items()}
            order = [self._stable_plan_worker_subtask_id(step_id, row) for row in target_rows]
            for incoming in incoming_worker_rows:
                subtask_id, prior = _existing_match(incoming)
                if not subtask_id or not isinstance(prior, dict):
                    continue
                prior_status = self._normalize_todo_status_value(prior.get("status", ""), "pending")
                incoming_status = self._normalize_todo_status_value(incoming.get("status", ""), prior_status)
                if prior_status == "completed" and incoming_status != "completed":
                    incoming_status = "completed"
                if prior_status != "completed" and incoming_status == "completed":
                    since_value = float(prior.get("created_at", 0.0) or prior.get("started_at", 0.0) or 0.0)
                    completion_candidate = {**prior, **incoming, "subtask_id": subtask_id}
                    if not self._plan_worker_completion_has_evidence(
                        active_step,
                        completion_candidate,
                        board=bb,
                        subtask_id=subtask_id,
                        since_ts=since_value,
                        evidence=incoming.get("evidence", ""),
                    ):
                        # A normal status update is not a structural transaction.
                        # Commit the evidence-backed siblings and leave only this
                        # unsupported completion open, so a missing final browser
                        # check cannot roll back real implementation progress.
                        incoming_status = prior_status
                        completion_audit_warnings.append(
                            self._plan_subtask_completion_audit_warning(
                                active_step,
                                completion_candidate,
                                board=bb,
                                subtask_id=subtask_id,
                                since_ts=since_value,
                            )
                        )
                        binding = {}
                    else:
                        completion_records = self._plan_worker_completion_evidence_records(
                            active_step,
                            completion_candidate,
                            board=bb,
                            subtask_id=subtask_id,
                            since_ts=since_value,
                            evidence=incoming.get("evidence", ""),
                        )
                        binding = self._record_plan_subtask_evidence_binding(
                            active_step,
                            completion_candidate,
                            completion_records,
                            source="status_update",
                            actor=role_key,
                            board=bb,
                        )
                else:
                    binding = {}
                merged = dict(prior)
                merged["status"] = incoming_status
                if incoming_status == "completed":
                    merged["completed_at"] = float(incoming.get("completed_at", 0.0) or now_ts())
                    merged["completed_by"] = trim(str(incoming.get("completed_by", "") or role_key), 40)
                    if incoming.get("evidence"):
                        merged["evidence"] = trim(str(incoming.get("evidence", "") or ""), 300)
                    if binding:
                        merged["evidence_ids"] = list(binding.get("evidence_ids", []) or [])
                        merged["evidence_binding"] = binding
                merged["updated_at"] = float(now_ts())
                merged["owner"] = _resolved_row_owner(prior, incoming)
                merged["parent_step_id"] = step_id
                merged["subtask_id"] = subtask_id
                patched_by_id[subtask_id] = merged
            current_step_rows = [patched_by_id[key] for key in order if key in patched_by_id]
        else:
            review = self._review_plan_worker_revision(
                active_step,
                target_rows,
                incoming_worker_rows,
                update_mode=mode,
                revision_reason=revision_reason,
                revision_evidence=revision_evidence,
                actor=role_key,
                board=bb,
            )
            refs = self._plan_worker_revision_references(revision_evidence)
            if not bool(review.get("ok", False)):
                self._append_plan_worker_revision_audit(
                    step_id=step_id,
                    actor=role_key,
                    status="rejected",
                    reason=f"{revision_reason} | {review.get('reason', '')}",
                    evidence_refs=refs,
                    evidence_ids=list(review.get("evidence_ids", []) or []),
                    before_open=list(review.get("before_open", []) or []),
                    after_open=list(review.get("after_open", []) or []),
                    board=bb,
                )
                canonical = self._render_plan_worker_todo_canonical(step_id, target_rows)
                return self._plan_control_feedback(
                    "preserve_current_subplan",
                    f"Rolling subplan revision rejected: {review.get('reason', 'evidence audit failed')}. "
                    "Keep executing the current canonical subtask or collect concrete current-step evidence before revising."
                    + (f"\n\n{canonical}" if canonical else "")
                )

            completed_rows: list[dict] = []
            for prior in target_rows:
                if str(prior.get("status", "pending") or "pending").lower() == "completed":
                    completed_rows.append(dict(prior))
            completed_by_id = {
                self._stable_plan_worker_subtask_id(step_id, row): row
                for row in completed_rows
                if self._stable_plan_worker_subtask_id(step_id, row)
            }
            proposed_open: list[dict] = []
            proposed_acceptance: list[dict] = []
            for incoming in incoming_worker_rows:
                subtask_id, prior = _existing_match(incoming)
                incoming_status = self._normalize_todo_status_value(incoming.get("status", ""), "pending")
                if isinstance(prior, dict) and str(prior.get("status", "pending") or "pending").lower() == "completed":
                    if mode != "rework_completed" or incoming_status == "completed":
                        continue
                    completed_by_id.pop(subtask_id, None)
                    self._clear_plan_subtask_evidence_binding(step_id, subtask_id, board=bb)
                if incoming_status == "completed":
                    source = prior if isinstance(prior, dict) else incoming
                    source_since = float(source.get("created_at", 0.0) or source.get("started_at", 0.0) or 0.0)
                    completion_candidate = {**(prior or {}), **incoming, "subtask_id": subtask_id}
                    if not self._plan_worker_completion_has_evidence(
                        active_step,
                        completion_candidate,
                        board=bb,
                        subtask_id=subtask_id,
                        since_ts=source_since,
                        evidence=incoming.get("evidence", ""),
                    ):
                        canonical = self._render_plan_worker_todo_canonical(step_id, target_rows)
                        return self._plan_control_feedback(
                            "preserve_current_subplan",
                            "Revised subplan attempted to mark work completed without bound evidence."
                            + (f"\n\n{canonical}" if canonical else "")
                        )
                    completion_records = self._plan_worker_completion_evidence_records(
                        active_step,
                        completion_candidate,
                        board=bb,
                        subtask_id=subtask_id,
                        since_ts=source_since,
                        evidence=incoming.get("evidence", ""),
                    )
                    completed = dict(prior or incoming)
                    completed.update(incoming)
                    completed["status"] = "completed"
                    completed["subtask_id"] = subtask_id
                    completed["completed_at"] = float(completed.get("completed_at", 0.0) or now_ts())
                    completed["completed_by"] = trim(str(completed.get("completed_by", "") or role_key), 40)
                    completed["owner"] = _resolved_row_owner(prior, incoming)
                    binding = self._record_plan_subtask_evidence_binding(
                        active_step,
                        {**completed, "subtask_id": subtask_id},
                        completion_records,
                        source="status_update" if mode == "status_update" else "semantic",
                        actor=role_key,
                        board=bb,
                    )
                    if binding:
                        completed["evidence_ids"] = list(binding.get("evidence_ids", []) or [])
                        completed["evidence_binding"] = binding
                    completed_by_id[subtask_id] = completed
                    continue
                revised = dict(prior or {})
                revised.update(incoming)
                revised["status"] = incoming_status if incoming_status in {"pending", "in_progress"} else "pending"
                if mode == "rework_completed" and isinstance(prior, dict) and str(prior.get("status", "") or "") == "completed":
                    for field in ("completed_at", "completed_by", "evidence"):
                        revised.pop(field, None)
                    revised["started_at"] = float(now_ts()) if revised["status"] == "in_progress" else 0.0
                revised["owner"] = _resolved_row_owner(prior, incoming)
                revised["parent_step_id"] = step_id
                revised["subtask_id"] = subtask_id or self._stable_plan_worker_subtask_id(step_id, revised)
                revised["updated_at"] = float(now_ts())
                if self._is_plan_step_acceptance_subtask(revised.get("content", "")):
                    proposed_acceptance.append(revised)
                else:
                    proposed_open.append(revised)
            existing_acceptance = [
                dict(row) for row in target_rows
                if self._is_plan_step_acceptance_subtask(row.get("content", ""))
            ]
            current_step_rows = list(completed_by_id.values()) + proposed_open + (proposed_acceptance or existing_acceptance[-1:])
            self._append_plan_worker_revision_audit(
                step_id=step_id,
                actor=role_key,
                status="accepted",
                reason=revision_reason,
                evidence_refs=refs,
                evidence_ids=list(review.get("evidence_ids", []) or []),
                before_open=list(review.get("before_open", []) or []),
                after_open=list(review.get("after_open", []) or []),
                board=bb,
            )

        current_step_rows = self._filter_parent_step_duplicate_worker_rows(
            current_step_rows,
            active_step,
            bb,
        )
        current_step_rows = self._plan_worker_rows_with_acceptance(
            active_step,
            current_step_rows,
            expected=[str(row.get("content", "") or "") for row in current_step_rows],
            owner=role_key,
        )
        for row in current_step_rows:
            row["parent_step_id"] = step_id
            if self._is_multi_agent_mode():
                row["owner"] = self._sanitize_agent_role(row.get("owner", "")) or role_key
            else:
                row["owner"] = role_key
            row["subtask_id"] = self._stable_plan_worker_subtask_id(step_id, row)

        # Insert current-step rows right after the active plan step's bb: row in preserved,
        # so subtasks appear nested under their parent step rather than at the list bottom.
        _step_key = str(active_step.get("key", "") or "")
        _insert_idx = len(preserved)  # fallback: append at end
        if _step_key:
            for _i, _r in enumerate(preserved):
                if str(_r.get("key", "") or "") == _step_key:
                    _insert_idx = _i + 1
                    break
        final_rows = preserved[:_insert_idx] + current_step_rows + preserved[_insert_idx:]
        state_lock = getattr(self, "lock", None)
        if state_lock is not None:
            state_lock.acquire()
        try:
            valid, stale_reason = self._todo_write_transaction_is_current(
                transaction,
                board=self._ensure_blackboard(),
            )
            if not valid:
                return self._emit_stale_todo_write_discarded(stale_reason)
            result = self.todo.update(final_rows)
            # The Todo commit itself is the expected mutation. Refresh the
            # transaction signature before the blackboard mirror revalidates
            # the same atomic operation.
            if isinstance(transaction, dict):
                try:
                    transaction["todo_signature"] = hashlib.sha256(
                        json.dumps(
                            self._todo_progress_signature(self.todo.snapshot()),
                            ensure_ascii=False,
                            separators=(",", ":"),
                        ).encode("utf-8", "ignore")
                    ).hexdigest()
                except Exception:
                    transaction["todo_signature"] = ""
            try:
                self._sync_plan_worker_todos_to_blackboard(
                    step_id,
                    transaction=transaction,
                )
                self._update_plan_file_step_status()
            except Exception:
                pass
            # TodoWrite is the requested state transition, not merely a hint.  If
            # this transaction completed the final acceptance row with deterministic
            # or semantic evidence, advance now from the same committed graph.  Both
            # Single and Sync use this path; the next run-loop preflight remains a
            # harmless recovery backstop if persistence/UI work raises unexpectedly.
            try:
                self._advance_completed_acceptance_after_todo_commit(
                    active_step,
                    actor=role_key,
                )
            except Exception:
                pass
        finally:
            if state_lock is not None:
                state_lock.release()
        # Read-before-write closure: echo the canonical, renumbered subtask list
        # back as the tool result so the model SEES the reconciled arrangement it
        # just produced (numbering, statuses, the single acceptance gate) rather
        # than guessing. This is what keeps subsequent TodoWrite calls aligned to
        # the canonical N.M scheme instead of inventing a parallel set.
        canonical = self._render_plan_worker_todo_canonical(step_id, current_step_rows)
        if canonical:
            revision_note = ""
            if mode in {"revise_open", "rework_completed"} and target_rows:
                revision_note = "\nROLLING SUBPLAN REVISION: accepted after current-step evidence audit."
            audit_note = ""
            if completion_audit_warnings:
                unique_open = list(dict.fromkeys(value for value in completion_audit_warnings if value))[:4]
                audit_note = (
                    "\nSTATUS EVIDENCE AUDIT: applied every evidence-backed transition and kept "
                    "only the following requested completion(s) open pending a matching current-step check: "
                    + "; ".join(unique_open)
                )
            return f"{result}{revision_note}{audit_note}\n\n{canonical}"
        return result

    def _render_plan_worker_todo_canonical(self, step_id: str, rows: list[dict]) -> str:
        """Render the current step's canonical subtask list for the tool result.

        Shows exactly what the runtime stored after reconciliation+renumbering, so
        the worker can continue the in_progress item instead of restating work.
        """
        try:
            ordered = [r for r in (rows or []) if isinstance(r, dict)]
            if not ordered:
                ordered = self._active_plan_worker_todo_rows(step_id, role="")
            if not ordered:
                return ""
            _mark = {"completed": "[x]", "in_progress": "[>]", "pending": "[ ]", "blocked": "[!]"}
            lines = ["CANONICAL SUBTASKS for the active step (continue the [>] item; do not renumber or restate):"]
            for r in ordered:
                st = str(r.get("status", "pending") or "pending").strip().lower()
                content = normalize_embedded_newlines(str(r.get("content", "") or "")).split("\n", 1)[0].strip()
                lines.append(f"  {_mark.get(st, '[ ]')} {trim(content, 140)}")
            return "\n".join(lines)
        except Exception:
            return ""

    def _merge_owner_scoped_todo_items(
        self,
        items: list[dict],
        role: str = "",
        *,
        update_mode: str = "status_update",
        revision_reason: str = "",
        revision_evidence: object = None,
        transaction: dict | None = None,
    ) -> str:
        if not isinstance(items, list):
            raise ValueError("items must be array")
        role_key = self._sanitize_agent_role(role)
        if role_key not in {"developer", "explorer", "reviewer"}:
            return self._merge_flat_todo_items(
                items,
                role=role_key,
                update_mode=update_mode,
                revision_reason=revision_reason,
                revision_evidence=revision_evidence,
                transaction=transaction,
            )
        existing = self.todo.snapshot()
        preserved: list[dict] = []
        existing_owner_rows: list[dict] = []
        for row in existing:
            if not isinstance(row, dict):
                continue
            key = str(row.get("key", "") or "").strip()
            owner = str(row.get("owner", "") or "").strip().lower()
            if key.startswith("bb:"):
                preserved.append(dict(row))
                continue
            if owner == role_key:
                existing_owner_rows.append(dict(row))
                continue
            preserved.append(dict(row))
        return self._merge_root_todo_scope(
            items,
            role=role_key,
            existing_scope=existing_owner_rows,
            preserved_rows=preserved,
            update_mode=update_mode,
            revision_reason=revision_reason,
            revision_evidence=revision_evidence,
            transaction=transaction,
        )

    def _append_instruction_bubble(self, content: str, *, target_roles: tuple[str, ...] = (), summary: str = "") -> bool:
        text = trim(str(content or "").strip(), PLAN_NOTICE_BODY_MAX_CHARS)
        if not text:
            return False
        recent = self.messages[-8:]
        if any(str(row.get("content", "") or "").strip() == text for row in recent if isinstance(row, dict)):
            return False
        stamp = now_ts()
        self.messages.append({"role": "user", "content": text, "ts": stamp})
        for role in target_roles:
            self._append_agent_context_message(
                role,
                {
                    "role": "system",
                    "content": text,
                    "ts": stamp,
                    "agent_role": role,
                },
                mirror_to_global=False,
            )
        if summary:
            self._emit("status", {"summary": trim(summary, 120)})
        return True

    def _wrapped_control_block(self, content: str) -> tuple[str, str]:
        text = str(content or "").strip()
        if not text:
            return ("", "")
        m = re.fullmatch(r"<([a-zA-Z0-9_-]+)>\s*([\s\S]*?)\s*</\1>", text)
        if not m:
            return ("", text)
        return (str(m.group(1) or "").strip().lower(), str(m.group(2) or "").strip())

    def _build_plan_guidance_notice_data(self, content: str, *, summary: str = "") -> dict:
        text = trim(str(content or "").strip(), PLAN_NOTICE_BODY_MAX_CHARS)
        if not text:
            return {}
        lang = normalize_ui_language(getattr(self, "ui_language", DEFAULT_UI_LANGUAGE))
        if lang == "zh-CN":
            title = "计划执行提示"
            note = "当前计划步骤与 Todo 规则已同步到本轮执行上下文。"
        elif lang == "zh-TW":
            title = "計畫執行提示"
            note = "目前計畫步驟與 Todo 規則已同步到本輪執行上下文。"
        elif lang == "ja":
            title = "計画実行ガイド"
            note = "現在の計画ステップと Todo ルールは今回の実行コンテキストへ同期されました。"
        else:
            title = "Plan Execution Guidance"
            note = "The active plan step and Todo rules were synced into the current execution context."
        control_tag, control_body = self._wrapped_control_block(text)
        notice_kind = "plan_notice"
        display_body = control_body if control_tag else text
        if control_tag == "todo-focus":
            notice_kind = "todo_focus"
            if lang == "zh-CN":
                title = "Todo 焦点"
                note = "当前 in_progress 子任务已同步为本轮执行焦点。"
            elif lang == "zh-TW":
                title = "Todo 焦點"
                note = "目前 in_progress 子任務已同步為本輪執行焦點。"
            elif lang == "ja":
                title = "Todo フォーカス"
                note = "現在の in_progress サブタスクを今回の実行フォーカスとして同期しました。"
            else:
                title = "Todo Focus"
                note = "The current in_progress subtask was synced as the execution focus."
        elif control_tag == "reminder":
            notice_kind = "reminder"
        bb = self._ensure_blackboard()
        step = self._current_plan_step_row(bb)
        total = int(bb.get("plan_step_total", 0) or 0)
        step_idx = int(step.get("plan_step_index", 0) or 0) + 1 if isinstance(step, dict) else 0
        step_text = trim(str(step.get("content", "") or ""), 160) if isinstance(step, dict) else ""
        step_id = str(step.get("id", "") or "") if isinstance(step, dict) else ""
        step_label = (
            self._ui_text("plan_step_label", step=step_idx, total=max(1, total))
            if step_idx > 0
            else ""
        )
        subtitle_parts = [part for part in (step_label, step_text) if part]
        subtitle = " · ".join(subtitle_parts) or trim(str(summary or ""), 120) or PLAN_FILE_RELATIVE_PATH
        pills: list[dict] = []
        if step_label:
            pills.append({"text": step_label, "tone": "info"})
        if control_tag:
            pills.append({"text": control_tag, "tone": "neutral", "mono": True})
        if step_id:
            pills.append({"text": step_id, "tone": "neutral", "mono": True})
        rows = [{"label": "plan.md", "value": PLAN_FILE_RELATIVE_PATH, "mono": True}]
        if step_id:
            rows.append({"label": "parent_step_id", "value": step_id, "mono": True})
        return {
            "kind": notice_kind,
            "control_tag": control_tag,
            "title": title,
            "subtitle": subtitle,
            "note": note,
            "body": display_body,
            "pills": pills,
            "rows": rows,
        }

    def _append_plan_guidance_bubble(self, content: str, *, target_roles: tuple[str, ...] = (), summary: str = "") -> bool:
        if str(self.plan_mode_user_preference or "auto").strip().lower() == "off":
            return False
        if not isinstance(self._current_plan_step_row(self._ensure_blackboard()), dict):
            return False
        text = trim(str(content or "").strip(), PLAN_NOTICE_BODY_MAX_CHARS)
        if not text:
            return False
        recent = self.messages[-10:]
        if any(str(row.get("content", "") or "").strip() == text for row in recent if isinstance(row, dict)):
            return False
        stamp = now_ts()
        notice_data = self._build_plan_guidance_notice_data(text, summary=summary)
        self.messages.append({"role": "user", "content": text, "ts": stamp, "_ui_hidden": True})
        self.messages.append(
            {
                "role": "system",
                "content": "",
                "ts": stamp,
                "type": "plan_notice",
                "agent_role": "planner",
                "data": notice_data,
            }
        )
        self._emit(
            "message",
            {
                "role": "system",
                "type": "plan_notice",
                "text": "",
                "data": notice_data,
                "agent_role": "planner",
                "summary": trim(summary or str(notice_data.get("subtitle", "") or "plan guidance"), 120),
            },
        )
        for role in target_roles:
            self._append_agent_context_message(
                role,
                {
                    "role": "system",
                    "content": text,
                    "ts": stamp,
                    "agent_role": role,
                },
                mirror_to_global=False,
            )
        return True

    def _build_plan_todo_reminder_text(self, plan_step: dict, *, missing_subtasks: bool = False) -> str:
        if missing_subtasks:
            return (
                "<reminder>"
                "No current-step subtasks are active. First call TodoWrite for this plan step only, "
                "using parent_step_id for every row and exactly one in_progress item."
                "</reminder>"
            )
        return (
            "<reminder>"
            "Existing todos are active for this step. Continue the current in_progress item by default. "
            "Use TodoWrite update_mode='status_update' for real progress. If new current-step tool/reviewer evidence "
            "proves the OPEN subplan is unsuitable, use update_mode='revise_open' with a concrete reason and exact evidence references; "
            "the runtime will audit the whole revision atomically."
            "</reminder>"
        )

    def _plan_todo_discipline_prompt(self, role: str = "", *, for_manager: bool = False) -> str:
        step = self._get_active_plan_step()
        if not isinstance(step, dict):
            return ""
        step_id = trim(str(step.get("id", "") or ""), 20)
        step_idx = int(step.get("plan_step_index", 0) or 0) + 1
        step_text = trim(str(step.get("content", "") or ""), 220)
        rows = self._active_plan_worker_todo_rows(step_id, role=role)
        current = next((r for r in rows if str(r.get("status", "") or "").strip().lower() == "in_progress"), None)
        pending = [r for r in rows if str(r.get("status", "") or "").strip().lower() == "pending"]
        completed = [r for r in rows if str(r.get("status", "") or "").strip().lower() == "completed"]
        current_text = str((current or {}).get("content", "") or "")
        current_is_acceptance = self._is_plan_step_acceptance_subtask(current_text)
        acceptance_terms = self._plan_step_acceptance_terms()
        auto_progress = not self._is_multi_agent_mode()
        acceptance_hint = (
            f"The final subtask must be a semantic {acceptance_terms['prefix']} item with a concrete check action and evidence shape. "
        )
        if current_is_acceptance:
            acceptance_hint += (
                "The current subtask is the acceptance gate: execute the concrete check now. "
                + (
                    "The runtime records matching evidence and closes the acceptance row atomically; use TodoWrite only to correct an exceptional mismatch. "
                    if auto_progress
                    else "Record the evidence and only mark the row completed when the check passes. "
                )
            )
        else:
            acceptance_hint += (
                "Do not delegate reviewer-style validation before the current work subtask is completed; continue executable work first. "
            )
        continuity = self._plan_continuity_context_block(max_chars=4200, include_steps=False)
        continuity_note = (
            f"{continuity}\n"
            if continuity else ""
        )
        if not rows:
            todo_state = (
                "No worker subtasks are active for this step. First create 3-6 step-local TodoWrite rows; the final row must be a semantic acceptance check with evidence shape. "
                f"scoped to parent_step_id='{step_id}', with exactly one in_progress item. "
            )
            subtasks_exist_ban = ""
        else:
            state_parts: list[str] = []
            if current:
                state_parts.append(
                    f"Current in_progress subtask: {trim(str(current.get('content', '') or ''), 160)}. "
                )
            elif pending:
                state_parts.append(
                    f"Next pending subtask: {trim(str(pending[0].get('content', '') or ''), 160)}. "
                )
            state_parts.append(
                f"Existing worker subtasks for this step: {len(completed)} completed, {len(pending)} pending. "
            )
            todo_state = "".join(state_parts)
            subtasks_exist_ban = (
                "ROLLING SUBPLAN RULE: continue the current in_progress subtask by default. "
                "Do not rewrite open subtasks from preference or speculation. If concrete current-step tool evidence or a reviewer finding "
                "shows that the OPEN portion is incomplete, obsolete, wrongly ordered, or poorly split, first inspect the canonical list and evidence, "
                "then submit the complete revised open snapshot with update_mode='revise_open', revision_reason, and exact revision_evidence references. "
                "The runtime audits structural changes atomically and preserves completed history. Use update_mode='rework_completed' only with cited failure/reviewer evidence. "
            )
        if for_manager:
            return (
                f"PLAN/TODO DISCIPLINE: `{PLAN_FILE_RELATIVE_PATH}` is a read-only runtime mirror of the authoritative execution path. "
                "It may be inspected with read_file but must never be edited with write_file/edit_file/bash redirection. "
                "Plan advancement must happen only through route_to_next_agent with advance_plan_step=true after evidence is reviewed. "
                f"Delegate ONLY against the current in-progress plan step (Step {step_idx}: {step_text}). "
                "The delegation must preserve the approved plan charter, prior step outputs, and final deliverable logic. "
                f"{continuity_note}"
                f"{subtasks_exist_ban}"
                f"{todo_state}"
                f"{acceptance_hint}"
                "Treat worker subtasks as the live execution state for the current plan step. "
                "Tell the owner to use status_update for normal progress and revise_open only after collecting concrete revision evidence. "
                "Do not route to finish_current_task while the approved plan still has unfinished steps."
            )
        tracking_rule = (
            "Observable tool results provide completion evidence but do not close ordinary work rows by themselves. After each real subtask boundary, use TodoWrite/TodoWriteRescue update_mode='status_update' before starting work from another row. If one tool round proves several rows complete, update them together in one call and keep exactly one remaining open row in_progress. The runtime may close the final acceptance row atomically only after all ordinary work rows are explicitly completed and matching acceptance evidence passes. "
            if auto_progress
            else "After EACH completed subtask, use TodoWrite/TodoWriteRescue update_mode='status_update' before starting the next one. "
        )
        return (
            f"PLAN/TODO DISCIPLINE: `{PLAN_FILE_RELATIVE_PATH}` is a read-only runtime mirror of the approved plan. "
            "Read it for status; never write/edit it directly. "
            f"Work ONLY on the current in-progress plan step (Step {step_idx}: {step_text}). "
            "Keep this step aligned with the approved plan charter, prior step outputs, and final deliverable logic. "
            f"{continuity_note}"
            f"{subtasks_exist_ban}"
            f"{todo_state}"
            f"{acceptance_hint}"
            f"{tracking_rule}"
            "Do not call finish_current_task for a subtask or a single plan step; use it only when the overall user task is truly complete."
        )

    def _append_plan_single_todo_reminder(self, plan_step: dict, *, missing_subtasks: bool = False) -> bool:
        if not isinstance(plan_step, dict):
            return False
        step_idx = int(plan_step.get("plan_step_index", 0) or 0) + 1
        now_tick = now_ts()
        if (now_tick - self.last_todo_reminder_ts) < 8:
            return False
        content = self._build_plan_todo_reminder_text(plan_step, missing_subtasks=missing_subtasks)
        if not content:
            return False
        self._append_plan_guidance_bubble(content, summary="todo reminder")
        self.last_todo_reminder_ts = now_tick
        self.todo_reminder_count += 1
        self._emit(
            "status",
            {
                "summary": (
                    "plan+single todo reminder injected "
                    f"(step={step_idx}, missing_subtasks={'yes' if missing_subtasks else 'no'})"
                )
            },
        )
        return True

    def _is_plan_step_acceptance_subtask(self, text: object) -> bool:
        import re

        raw = normalize_work_text(str(text or "")) or str(text or "")
        low = re.sub(r"^\s*\d+\.\d+\s+", "", raw.strip().lower())
        if not low:
            return False
        prefixes = (
            "验收", "驗收", "最终验收", "最終驗收",
            "acceptance", "final acceptance", "final verification",
            "verify acceptance", "semantic acceptance",
            "受入確認", "受け入れ確認", "検収", "最終確認",
        )
        if low.startswith(prefixes):
            return True
        return (
            low.startswith(("final check", "final verify"))
            and ("evidence" in low or "证据" in low or "證據" in low or "証拠" in low)
        )

    def _plan_step_acceptance_terms(self) -> dict[str, str]:
        lang = normalize_ui_language(getattr(self, "ui_language", DEFAULT_UI_LANGUAGE))
        if lang == "en":
            return {
                "prefix": "Acceptance",
                "evidence": "Evidence",
                "suffix": "Evidence: record the actual check result and key tool/file output.",
            }
        if lang == "zh-TW":
            return {
                "prefix": "驗收",
                "evidence": "證據",
                "suffix": "證據：記錄實際檢查結果與關鍵工具/檔案輸出。",
            }
        if lang == "ja":
            return {
                "prefix": "受入確認",
                "evidence": "証拠",
                "suffix": "証拠：実際の確認結果と主要なツール/ファイル出力を記録する。",
            }
        return {
            "prefix": "验收",
            "evidence": "证据",
            "suffix": "证据：记录实际检查结果和关键工具/文件输出。",
        }

    def _explicit_plan_step_acceptance_contract(self, plan_step: dict) -> str:
        """Extract the plan author's acceptance signal instead of re-inferring it."""
        if not isinstance(plan_step, dict):
            return ""
        raw = normalize_embedded_newlines(
            plan_step.get("full_content", "") or plan_step.get("content", "") or ""
        )
        if not raw.strip():
            return ""
        marker = re.compile(
            r"^\s*(?:[-*•>]\s*)?(?:\d+(?:\.\d+)*[.)、]?\s*)?(?:"
            r"(?:最终)?验收(?:信号|标准|条件)?|验证(?:结果|标准|条件)?|完成标准|"
            r"(?:最終)?驗收(?:信號|標準|條件)?|驗證(?:結果|標準|條件)?|完成標準|"
            r"acceptance(?:\s+(?:signal|criteria|condition))?|pass\s+criteria|"
            r"verification|validation|verify|"
            r"受入確認|受入基準|受入条件|検証|確認|完了条件"
            r")\s*[:：]\s*(.+?)\s*$",
            flags=re.IGNORECASE,
        )
        contracts: list[str] = []
        for line in raw.splitlines():
            match = marker.match(line)
            if not match:
                continue
            contract = trim(str(match.group(1) or "").strip().rstrip("。.;；"), 500)
            if contract and contract not in contracts:
                contracts.append(contract)
            if len(contracts) >= 3:
                break
        return trim("; ".join(contracts), 900)

    def _effective_plan_step_acceptance_text(
        self,
        plan_step: dict,
        acceptance_text: object,
    ) -> str:
        """Use an explicit plan contract as the authoritative gate semantics."""
        explicit = self._explicit_plan_step_acceptance_contract(plan_step)
        if not explicit:
            return trim(str(acceptance_text or "").strip(), 1200)
        terms = self._plan_step_acceptance_terms()
        sep = ":" if normalize_ui_language(getattr(self, "ui_language", DEFAULT_UI_LANGUAGE)) == "en" else "："
        return trim(f"{terms['prefix']}{sep}{explicit}", 1200)

    def _localized_explicit_acceptance_evidence(self, contract: str, lang: str) -> str:
        expected = self._acceptance_expected_evidence(contract)
        if lang == "en":
            if expected == "runtime/test/build/browser execution evidence":
                return "record the command, exit code, file/content assertions, and decisive output"
            if expected == "file/path/directory inspection evidence":
                return "record the target path and the read/content checks that prove each condition"
            if expected == "research/retrieval evidence":
                return "record the retrieval status, sources, and extracted facts"
            return "record the observable check and its decisive result"
        if lang == "zh-TW":
            if expected == "runtime/test/build/browser execution evidence":
                return "記錄命令、exit code、檔案/內容斷言及關鍵輸出"
            if expected == "file/path/directory inspection evidence":
                return "記錄目標路徑，以及逐項證明條件的讀取/內容檢查結果"
            if expected == "research/retrieval evidence":
                return "記錄檢索狀態、來源及提取到的事實"
            return "記錄可觀察檢查及其關鍵結果"
        if lang == "ja":
            if expected == "runtime/test/build/browser execution evidence":
                return "コマンド、exit code、ファイル/内容の検証項目、および主要出力を記録する"
            if expected == "file/path/directory inspection evidence":
                return "対象パスと、各条件を証明する読み取り/内容確認結果を記録する"
            if expected == "research/retrieval evidence":
                return "検索状態、情報源、抽出した事実を記録する"
            return "観測可能な確認と決定的な結果を記録する"
        if expected == "runtime/test/build/browser execution evidence":
            return "记录命令、exit code、文件/内容断言和关键输出"
        if expected == "file/path/directory inspection evidence":
            return "记录目标路径，以及逐项证明条件的读取/内容检查结果"
        if expected == "research/retrieval evidence":
            return "记录检索状态、来源和提取到的事实"
        return "记录可观察检查及其关键结果"

    def _acceptance_mentions_unsupported_targets(
        self,
        text: object,
        plan_step: dict,
        work_subtasks: list[str] | None = None,
    ) -> bool:
        """Reject acceptance laundry lists that introduce unrelated domains."""
        raw = normalize_embedded_newlines(text)
        action = re.split(
            r"(?:证据|證據|証拠|根拠|evidence)\s*[:：]",
            raw,
            maxsplit=1,
            flags=re.IGNORECASE,
        )[0].lower()
        keys = set(self._plan_step_acceptance_targets(plan_step, work_subtasks).get("keys", []) or [])
        domain_aliases = {
            "api_behavior": ("api route", "api request", "api 路由", "api 请求", "api 請求", "endpoint", "接口请求", "介面請求"),
            "infra_files": ("基础设施", "基礎設施", "infrastructure", "docker", "kubernetes", "部署文件", "部署檔案"),
            "database_schema": ("database schema", "数据库结构", "資料庫結構", "migration", "数据库迁移", "資料庫遷移"),
            "frontend_behavior": ("frontend behavior", "browser interaction", "前端交互", "前端互動", "浏览器行为", "瀏覽器行為"),
            "rendering": ("rendering/fps", "渲染/fps", "描画/fps"),
        }
        for key, aliases in domain_aliases.items():
            if key not in keys and any(alias in action for alias in aliases):
                return True
        return False

    def _normalize_plan_step_acceptance_subtask_text(self, text: object) -> str:
        raw = trim(normalize_work_text(str(text or "")) or str(text or "").strip(), 260)
        if not raw:
            return ""
        terms = self._plan_step_acceptance_terms()
        if not self._is_plan_step_acceptance_subtask(raw):
            sep = ":" if normalize_ui_language(getattr(self, "ui_language", DEFAULT_UI_LANGUAGE)) == "en" else "："
            raw = f"{terms['prefix']}{sep}{raw}"
        evidence_markers = (
            "证据", "證據", "証拠", "根拠", "evidence", "exit code",
            "输出", "輸出", "出力", "output", "日志", "日誌", "ログ", "log",
        )
        if not any(marker.lower() in raw.lower() for marker in evidence_markers):
            raw = trim(f"{raw}；{terms['suffix']}", 300)
        return raw

    def _is_generic_plan_step_acceptance_subtask(self, text: object) -> bool:
        raw = normalize_work_text(str(text or "")) or str(text or "")
        low = raw.lower()
        generic_markers = (
            "根据本步骤目标运行构建/测试/导入检查",
            "根据本步骤目标",
            "对照本步骤目标检查当前产出",
            "依照本步驟目標執行建置/測試/匯入檢查",
            "依照本步驟目標",
            "對照本步驟目標檢查目前產出",
            "このステップの目的に沿ってビルド/テスト/インポート確認",
            "このステップの目的に照らして現在の成果",
            "run the build/test/import check",
            "check whether the current output fully satisfies this step",
            "verify result",
            "check whether output satisfies",
            "current output",
            "this step's output",
            "当前产出是否",
            "本步骤产出",
            "目前產出是否",
            "本步驟產出",
            "record key output",
            "记录关键输出",
            "記錄關鍵輸出",
            "关键工具/文件输出",
            "關鍵工具/檔案輸出",
            "key tool/file output",
        )
        return any(marker.lower() in low for marker in generic_markers)

    def _plan_step_acceptance_subtask_is_specific(
        self,
        text: object,
        plan_step: dict,
        work_subtasks: list[str] | None = None,
    ) -> bool:
        raw = normalize_work_text(str(text or "")) or str(text or "")
        if not raw or not self._is_plan_step_acceptance_subtask(raw):
            return False
        if self._is_generic_plan_step_acceptance_subtask(raw):
            return False
        if self._acceptance_mentions_unsupported_targets(raw, plan_step, work_subtasks):
            return False
        low = raw.lower()
        evidence_value_markers = (
            "exit_code", "exit code", "rc=", "exit=", "pass", "passed", "ok",
            "size=", "bytes", "kb", "mb", "http 200", "status 200",
            "version=", "semantic_version", "文件大小", "字节", "退出码",
            "通过", "已通过", "成功", "证据", "證據", "証拠",
        )
        if any(marker in low for marker in evidence_value_markers):
            return True
        action_low = re.split(
            r"(?:证据|證據|証拠|根拠|evidence)\s*[:：]",
            raw,
            maxsplit=1,
            flags=re.I,
        )[0].lower()
        concrete_markers = (
            "path", "file", "directory", "folder", "console", "browser", "static", "server",
            "module", "package", "dependency", "schema", "migration", "endpoint", "api",
            "command", "build", "test", "lint", "typecheck", "compile", "runtime", "service",
            "python", "javascript", "typescript", "go", "rust", "java", "kotlin", "swift",
            "c++", "cpp", "c#", "dotnet", "php", "ruby", "html", "css", "sql", "shell",
            "three.js", "vite", "react", "vue", "svelte", "docker", "kubernetes",
            "路径", "文件", "目录", "模块", "包", "控制台", "浏览器", "静态服务", "加载", "入口", "依赖",
            "构建", "测试", "静态检查", "类型检查", "编译", "运行", "服务", "接口", "端点", "数据库", "迁移", "表结构",
            "路徑", "檔案", "目錄", "模組", "套件", "控制台", "瀏覽器", "靜態服務", "載入", "入口", "依賴",
            "建置", "測試", "靜態檢查", "型別檢查", "編譯", "執行", "服務", "介面", "端點", "資料庫", "遷移",
            "パス", "ファイル", "ディレクトリ", "コンソール", "ブラウザ", "読み込み", "依存",
            "ビルド", "テスト", "型チェック", "コンパイル", "実行", "サービス", "エンドポイント", "データベース",
        )
        if any(marker in action_low for marker in concrete_markers):
            return True
        targets = self._plan_step_acceptance_targets(plan_step, work_subtasks)
        for path in targets.get("paths", []) or []:
            if str(path or "").lower() in low:
                return True
        target_aliases = {
            "project_dir": ("project directory", "project folder", "workspace", "项目目录", "工程目录", "專案目錄", "프로ジェクト", "ディレクトリ"),
            "source_code": ("source", "code", "module", "源码", "代码", "模組", "程式碼", "ソース", "コード"),
            "language_code": ("python", "javascript", "typescript", "go", "rust", "java", "kotlin", "swift", "c++", "cpp", "c#", "dotnet", "php", "ruby"),
            "three_dependency": ("three.js", "threejs", "three.min", "three 依赖", "three 依賴", "three 依存"),
            "html_css_js_entry": ("html/css/js", "html", "css", "javascript", "入口文件", "入口檔案", "エントリファイル"),
            "html_entry": ("html", "入口文件", "入口檔案", "エントリファイル"),
            "html_file": ("html",),
            "css_entry": ("css", "入口文件", "入口檔案", "エントリファイル"),
            "css_file": ("css",),
            "js_entry": ("javascript", ".js", "入口文件", "入口檔案", "エントリファイル"),
            "js_file": ("javascript", ".js"),
            "dependency_config": ("dependency", "package", "requirements", "cargo", "go.mod", "pom.xml", "gradle", "package.json", "vite", "npm", "pnpm", "yarn", "依赖", "依賴", "依存"),
            "build_config": ("build", "compile", "makefile", "cmake", "webpack", "vite", "构建", "建置", "ビルド"),
            "frontend_behavior": ("frontend", "webui", "web ui", "界面", "介面", "交互", "互動", "browser", "浏览器", "瀏覽器"),
            "rendering": ("render", "canvas", "fps", "渲染", "描画"),
            "runtime_service": ("run", "runtime", "service", "server", "port", "运行", "服務", "サーバー"),
            "api_behavior": ("api", "endpoint", "route", "request", "response", "接口", "端点", "介面", "エンドポイント"),
            "database_schema": ("database", "schema", "migration", "sql", "sqlite", "postgres", "mysql", "数据库", "資料庫"),
            "data_files": ("csv", "json", "parquet", "dataset", "data", "数据", "資料"),
            "asset_files": ("asset", "image", "svg", "png", "jpg", "font", "资源", "素材", "画像"),
            "config_files": ("config", "settings", ".env", "yaml", "toml", "配置", "設定"),
            "infra_files": ("docker", "kubernetes", "deployment", "ci", "workflow", "部署", "インフラ"),
            "test_output": ("test", "pytest", "ruff", "py_compile", "jest", "vitest", "go test", "cargo test", "测试", "測試", "検証"),
            "lint_typecheck": ("lint", "typecheck", "mypy", "eslint", "tsc", "ruff", "静态检查", "型別檢查"),
            "document_output": ("document", "markdown", ".md", "文档", "文件", "章", "章节", "outline", "chapter", "小说", "文章"),
            "referenced_paths": ("path", "file", "路径", "路徑", "パス", "ファイル"),
        }
        for key in targets.get("keys", []) or []:
            aliases = target_aliases.get(str(key or ""), ())
            if any(alias.lower() in action_low for alias in aliases):
                return True
        return False

    def _plan_step_acceptance_targets(self, plan_step: dict, work_subtasks: list[str] | None = None) -> dict:
        raw_parts = [
            str((plan_step or {}).get("full_content", "") or (plan_step or {}).get("content", "") or "")
        ]
        raw_parts.extend(str(item or "") for item in (work_subtasks or [])[:8])
        text = normalize_embedded_newlines("\n".join(raw_parts))
        low = text.lower()
        document_context = any(
            token in low
            for token in (
                "文档", "文件", "document", "docs/", ".md", "markdown", "说明", "手册",
                "文件", "ドキュメント", "説明", "マニュアル",
            )
        )
        api_runtime_context = any(
            token in low
            for token in (
                "endpoint", "route", "handler", "controller", "middleware", "server", "service", "curl",
                "http request", "api request", "call api", "run server", "serve", "websocket",
                "端点", "路由", "处理器", "控制器", "中间件", "服务", "运行请求", "启动服务", "调用接口",
                "端點", "路由", "處理器", "控制器", "中介軟體", "服務", "執行請求", "啟動服務", "呼叫介面",
                "エンドポイント", "ルート", "ハンドラ", "コントローラ", "ミドルウェア", "サーバー", "サービス",
            )
        )
        paths: list[str] = []
        path_re = re.compile(
            r"(?:[\w.@()+ -]+/)+[\w.@()+ -]+\.[A-Za-z0-9]{1,8}\b"
            r"|[\w.@()+-]+\.(?:html|css|js|mjs|ts|tsx|jsx|json|md|py|txt|yaml|yml|toml|rs|go|java|kt|swift|cpp|c|h)\b"
        )
        for match in path_re.finditer(text):
            value = match.group(0).strip(" \t\r\n.,;:，。；：)）]")
            if " " in value or "\t" in value:
                value = value.replace("\t", " ").split()[-1].strip()
            if value.lower() in {"three.js"}:
                continue
            if value and value not in paths:
                paths.append(value)
            if len(paths) >= 5:
                break

        keys: list[str] = []

        def add(key: str):
            if key not in keys:
                keys.append(key)

        if any(token in low for token in ("项目目录", "工程目录", "专案目录", "專案目錄", "project directory", "project folder", "workspace", "ディレクトリ")):
            add("project_dir")
        source_extensions = (
            ".py", ".go", ".rs", ".java", ".kt", ".kts", ".swift",
            ".cpp", ".cc", ".cxx", ".c", ".h", ".hpp", ".cs", ".php", ".rb", ".lua", ".r", ".scala", ".dart",
            ".sh", ".bash", ".zsh", ".ps1", ".sql",
        )
        if any(re.search(re.escape(ext) + r"(?![A-Za-z0-9])", low) for ext in source_extensions) or any(
            token in low
            for token in (
                "source code", "module", "function", "class", "源码", "源代码", "代码", "模块", "函数", "类",
                "原始碼", "程式碼", "模組", "函式", "ソース", "コード", "モジュール", "関数", "クラス",
            )
        ):
            add("source_code")
        if any(
            token in low
            for token in (
                "python", "typescript", "javascript", "node", "deno", "go ", "golang", "rust", "java", "kotlin",
                "swift", "c++", "cpp", " c ", "c#", "dotnet", ".net", "php", "ruby", "rails", "lua", "scala",
                "dart", "flutter", "shell", "bash", "powershell", "sql",
            )
        ) and not (
            # Product/library names such as Three.js must not imply that the
            # active step asks to inspect language source modules. HTML-only
            # delivery/verification steps otherwise inherit a bogus source-code
            # acceptance dimension.
            "three.js" in low
            and not any(token in low for token in ("javascript", ".js", " js ", "js/", "/js", "脚本", "腳本", "スクリプト"))
        ):
            add("language_code")
        if any(token in low for token in ("three.js", "threejs", "three min", "three.min", "three ")):
            add("three_dependency")
        has_html = "html" in low or ".html" in low
        has_css = "css" in low or ".css" in low
        has_js = any(
            token in low
            for token in ("javascript", " js", ".js", "/js", "js/", "js ", "js入口", "js 入口", "脚本", "腳本", "スクリプト")
        )
        has_entry = any(token in low for token in ("入口", "entry", "エントリ"))
        if has_html and has_css and has_js and has_entry:
            add("html_css_js_entry")
        else:
            if has_html:
                add("html_entry" if has_entry else "html_file")
            if has_css:
                add("css_entry" if has_entry else "css_file")
            if has_js:
                add("js_entry" if has_entry else "js_file")
        if any(
            token in low
            for token in (
                "package.json", "requirements.txt", "pyproject.toml", "poetry.lock", "pipfile", "cargo.toml",
                "cargo.lock", "go.mod", "go.sum", "pom.xml", "build.gradle", "gradle", "gemfile",
                "composer.json", "pubspec.yaml", "package-lock.json", "pnpm-lock.yaml", "yarn.lock",
                "vite", "npm", "pnpm", "yarn", "pip", "uv ", "poetry", "cargo", "maven", "依赖", "依賴", "dependency",
            )
        ):
            add("dependency_config")
        if any(
            token in low
            for token in (
                "makefile", "cmakelists.txt", "cmake", "webpack", "vite", "rollup", "esbuild", "tsconfig",
                "build", "compile", "构建", "编译", "建置", "編譯", "ビルド", "コンパイル",
            )
        ):
            add("build_config")
        if any(token in low for token in ("frontend", "webui", "web ui", "界面", "介面", "交互", "互動", "ui", "画面")):
            add("frontend_behavior")
        if any(token in low for token in ("3d", "canvas", "render", "渲染", "描画", "fps", "three.js")):
            add("rendering")
        if any(
            token in low
            for token in (
                "runtime", "server", "port", "daemon", "cli", "command line", "run server", "serve",
                "启动", "运行服务", "启动服务", "端口", "命令行", "啟動", "執行服務", "啟動服務", "服務執行",
                "ポート", "起動", "サーバー", "サービス起動",
            )
        ):
            add("runtime_service")
        if any(
            token in low
            for token in (
                "api", "endpoint", "route", "request", "response", "http", "graphql", "websocket",
                "接口", "端点", "请求", "响应", "路由", "介面", "端點", "請求", "回應", "エンドポイント", "リクエスト",
            )
        ) and (api_runtime_context or not document_context):
            add("api_behavior")
        if any(
            token in low
            for token in (
                "database", "schema", "migration", "sql", "sqlite", "postgres", "postgresql", "mysql", "redis",
                "mongodb", "db table", "database table", "database index", "db index",
                "数据库", "表结构", "迁移", "資料庫", "遷移", "データベース",
            )
        ):
            add("database_schema")
        if any(
            token in low
            for token in (
                "csv", "tsv", "jsonl", "parquet", "dataset", "data file", "data set",
                "数据文件", "数据集", "资料文件", "資料檔案", "資料集", "データファイル", "データセット",
            )
        ):
            add("data_files")
        if any(token in low for token in ("png", "jpg", "jpeg", "svg", "webp", "gif", "font", "asset", "image", "资源", "素材", "画像")):
            add("asset_files")
        if any(token in low for token in (".env", "config", "settings", "yaml", "yml", "toml", "ini", "配置", "設定")):
            add("config_files")
        if any(token in low for token in ("dockerfile", "docker-compose", "kubernetes", "k8s", "ci", "github actions", "workflow", "部署", "インフラ")):
            add("infra_files")
        if any(
            token in low
            for token in (
                "测试", "測試", "test", "pytest", "unittest", "jest", "vitest", "go test", "cargo test",
                "ruff", "py_compile", "验证", "驗證", "検証",
            )
        ):
            add("test_output")
        if any(token in low for token in ("lint", "typecheck", "type check", "mypy", "eslint", "tsc", "clippy", "fmt", "静态检查", "类型检查", "型別檢查")):
            add("lint_typecheck")
        if any(token in low for token in ("文档", "文件", "document", "markdown", ".md", "章", "章节", "outline", "chapter", "小说", "文章")):
            add("document_output")
        if paths:
            add("referenced_paths")
        return {"keys": keys[:8], "paths": paths[:5], "low": low}

