    def _tool_calls_fingerprint(self, tool_calls: list[dict]) -> str:
        if not isinstance(tool_calls, list) or not tool_calls:
            return ""
        parts: list[str] = []
        for tc in tool_calls[:6]:
            fn = tc.get("function", {}) if isinstance(tc, dict) else {}
            name = str(fn.get("name", "")).strip()
            args = fn.get("arguments", {})
            args_error = str(tc.get("args_error", "")).strip()
            try:
                if isinstance(args, (dict, list)):
                    args_text = json.dumps(args, ensure_ascii=False, sort_keys=True, separators=(",", ":"))
                else:
                    args_text = str(args)
            except Exception:
                args_text = str(args)
            args_text = trim(args_text, 280).replace("\n", " ")
            parts.append(f"{name}|{args_error}|{args_text}")
        raw = "||".join(parts)
        if not raw:
            return ""
        return hashlib.sha1(raw.encode("utf-8")).hexdigest()

    def _inject_forced_convergence_hint(self, tool_names: list[str], reason: str):
        uniq = []
        for name in tool_names:
            n = str(name or "").strip()
            if not n or n in uniq:
                continue
            uniq.append(n)
        focus = ", ".join(uniq[:3]) if uniq else "tool call"
        goal = self._latest_user_goal_text()
        self._prune_runtime_retry_hints()
        self.messages.append(
            {
                "role": "user",
                "content": (
                    "<forced-converge>"
                    f"Repeated tool loop detected on {focus}: {trim(reason, 220)}. "
                    "Mandatory convergence mode: "
                    "1) execute exactly ONE concrete tool call in next round, "
                    "2) use complete arguments and avoid planning-only text, "
                    "3) if blocked, report blocker and stop instead of retrying same call, "
                    "4) if task is complete, call finish_task and wait for user input. "
                    f"Goal reference: {goal}"
                    "</forced-converge>"
                ),
                "ts": now_ts(),
            }
        )
        self._emit(
            "status",
            {"summary": f"forced segmented convergence enabled for {focus}"},
        )

    def _inject_edit_recovery_hint(self, file_path: str, fail_count: int, diagnostic: str, role_key: str):
        """Inject recovery hint after consecutive edit_file failures."""
        import re as _re
        line_hint = ""
        m = _re.search(r"line\(?s?\)?\s*([\d,\s]+)", diagnostic.lower())
        if m:
            line_hint = f"Diagnostic line hints: {m.group(1).strip()}. "

        stall_reached = fail_count >= DEVELOPER_EDIT_STALL_THRESHOLD
        if stall_reached:
            strategy = (
                f"FORCED STRATEGY CHANGE: edit_file has failed {fail_count} times on this file. "
                "You MUST use one of these alternatives NOW: "
                "A) Use write_file to rewrite the entire file. "
                "B) Break edit into single-line old_text (one unique line only). "
                "C) Use bash with sed for simple replacements. "
                "Do NOT attempt edit_file again without first reading the file fresh. "
            )
        else:
            strategy = (
                "RECOVERY: "
                f"1) Call read_file on '{file_path}' to get FRESH content. "
                "2) Check exact whitespace/indentation at target location. "
                "3) Use shorter, unique old_text (1-3 lines max). "
                "4) If still failing next time, use write_file instead. "
            )

        hint = (
            f"<edit-recovery>"
            f"edit_file failed {fail_count} time(s) on '{file_path}'. "
            f"{line_hint}"
            f"Last diagnostic: {trim(diagnostic, 300)}. "
            f"{strategy}"
            f"</edit-recovery>"
        )

        self._prune_runtime_retry_hints()
        self.messages.append({"role": "user", "content": hint, "ts": now_ts()})
        self._emit("status", {"summary": f"edit-recovery hint for {file_path} (fail #{fail_count})"})

    def _diagnose_no_tool_idle(self, latest_text: str, streak: int) -> dict:
        raw = str(latest_text or "")
        clean = strip_thinking_content(raw).strip()
        informative = self._looks_like_substantial_informative_reply(raw)
        recent = list(self.messages[-40:])
        tool_errors = 0
        truncate_hints = 0
        compact_hints = 0
        blank_assistant = 0
        for row in recent:
            role = str(row.get("role", "")).strip()
            content = str(row.get("content", "") or "")
            low = content.lower()
            if role == "tool" and low.strip().startswith("error:"):
                tool_errors += 1
            if "truncate-rescue" in low or "truncated" in low:
                truncate_hints += 1
            if "<compact-resume>" in low or "context_recall" in low:
                compact_hints += 1
            if role == "assistant" and not strip_thinking_content(content).strip():
                blank_assistant += 1
        if self.last_compact_ts > 0:
            compact_hints += 1
        causes: list[str] = []
        actions: list[str] = []
        if truncate_hints > 0:
            causes.append("possible truncation/partial output")
            actions.append("split into smaller subtasks and regenerate full tool JSON")
        if compact_hints > 0:
            causes.append("context may be compacted")
            actions.append("call context_recall mode='summary', then mode='search' or mode='window' for focused details")
        if tool_errors > 0:
            causes.append("recent tool execution errors")
            actions.append("repair arguments for one failing tool and retry only that tool")
        if not clean:
            causes.append("assistant content is empty or thinking-only")
            actions.append("produce one concrete tool call instead of narration")
        if blank_assistant >= 2:
            causes.append("repeated blank assistant turns")
            actions.append("force one-tool convergence mode")
        if not causes:
            causes.append("model drifted into analysis-only mode")
            actions.append("if done call finish_task, otherwise run one concrete execution tool")
        goal_hint = self._latest_user_goal_text()
        todo_blocking = self._todo_should_block_auto_continue(raw)
        conclusive = self._looks_like_conclusive_reply(raw)
        return {
            "streak": int(streak),
            "causes": causes[:4],
            "actions": actions[:4],
            "work_pending": bool(
                (not conclusive)
                and (not informative)
                and (
                    todo_blocking
                    or self._looks_like_incomplete_reply(raw)
                    or self._looks_nontrivial_request(goal_hint)
                )
            ),
        }

    def _inject_no_tool_recovery_hint(self, diagnosis: dict):
        streak = int(diagnosis.get("streak", 0) or 0)
        causes = ", ".join(str(x) for x in (diagnosis.get("causes") or []) if str(x).strip()) or "unknown"
        actions = [str(x).strip() for x in (diagnosis.get("actions") or []) if str(x).strip()]
        action_text = " | ".join(actions[:4]) if actions else "run one concrete tool call"
        recall_hint = ""
        if self.context_archives:
            seg = self.context_archives[-1]
            seg_id = str(seg.get("id", "")).strip()
            if seg_id:
                recall_hint = (
                    f"Call context_recall with segment_id='{seg_id}' and mode='summary' to map the segment, then mode='search' for the missing topic or mode='window' with around_index/context for nearby messages. "
                )
        self._prune_runtime_retry_hints()
        self.messages.append(
            {
                "role": "user",
                "content": (
                    "<no-tool-recovery>"
                    f"提示：检测到连续文本回合（streak={streak}）。诊断：{causes}。"
                    f"{recall_hint}"
                    "如果任务已经完成，请调用 finish_task（可附简短 summary）或直接停止并等待用户。"
                    "如果任务尚未完成，请在下一轮只执行一个具体工具调用（参数需有效）来推进。"
                    "不要为了通过恢复检查而编造新的 Todo。"
                    f"建议动作：{action_text}。"
                    "</no-tool-recovery>"
                ),
                "ts": now_ts(),
            }
        )
        self._emit(
            "status",
            {
                "summary": (
                    "no-tool idle diagnosis injected "
                    f"(streak={streak}; causes={trim(causes, 120)})"
                )
            },
        )

    def _inject_plan_no_tool_recovery_hint(self, assistant_text: str = ""):
        bb = self._ensure_blackboard()
